/* 令和5年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r05.committeeSessions.push(...[{"id":"r05-20231127-9","meetingId":"r05-cm11","date":"2023年11月27日","dateIso":"2023-11-27","committee":"文教委員会","time":"午前１０時００分～午後 ３時３４分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を92件整理しています。","topics":[{"id":"topic-01","title":"第８０号議案、品川区児童相談所設置条例","agenda":"第８０号議案、品川区児童相談所設置条例","exchanges":[{"speaker":"安藤委員","kind":"確認","question":"２点伺いますけれども、どんな内容の条例になるのでしたかという確認が１つと、伺いたいと思います。","respondent":"長谷川児童相談所開設準備課長","answer":"今、所管部署と協議をしておりますけれども、おおよそ１３本程度予定をしております。協力していただけるよう、積極的にＰＲを図っていきたいと考えています。","id":"exchange-001"},{"speaker":"高橋（し）委員","kind":"質問","question":"この条例とは関係ないというか、あれなのですけれども、そういうことについては検討されているのか尋ねました。","respondent":"長谷川児童相談所開設準備課長","answer":"区として今後検討すべき事項であるとは認識していますが、現時点においては、制定するといったところで考えているわけではございません。最終的には、区として考えを検討すべき事項ではありますけれども、児童相談所という名称を最大限押していく必要はあるかと考えています。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"子育て世代の利用者等から見直しを求める意見も上がった経緯も過去にはありまして、基礎自治体での児童相談所の設置は大変重要だと考えております。全ての子どもたちの幸せを願って、賛成したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"先ほど質問したのですけれども、通称ということを、皆さんがハードルが低くなるようなことを考えていってほしいと求めました。それは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"}]},{"id":"topic-02","title":"第８１号議案、品川区立保育所条例の一部を改正する条例","agenda":"第８１号議案、品川区立保育所条例の一部を改正する条例","exchanges":[{"speaker":"安藤委員","kind":"確認","question":"こちらは１歳児園ということでよろしかったのでしょうかということと、あと、この地域での待機児対策というのは十分ですという考えなのでしょうか。伺いたいと思います。","respondent":"今井保育教育運営担当課長","answer":"来年度当初からの民営化を予定してございまして、改築工事実施後、移転をした後に民営化するというスケジュールで現在進めているところです。","id":"exchange-005"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"ただ、来年の４月から６月に予定されていると思われますが、こちらの解体工事の地域住民への配慮と周知を改めて徹底してほしいと求めました。こちらは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"安藤委員","kind":"意見","question":"改築して、施設を新しくして、民間委託を進めると。完全に民間に渡すという流れの中での改築でありますので、認められないということで、反対ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"}]},{"id":"topic-03","title":"第８４号議案、品川区いじめ防止対策推進条例の一部を改正する条例","agenda":"第８４号議案、品川区いじめ防止対策推進条例の一部を改正する条例","exchanges":[{"speaker":"安藤委員","kind":"提案","question":"臨時委員にはどのような方を据えることを想定していらっしゃるのか伺いたいのが１つと、すごく知る権利というのは尊重すべきだと思うのですけれども。そういう提案、そういう提案とか希望とかがあれば、そういうのはどのようにお考えか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"福祉、心理の専門家、場合によっては医療の専門家ということで想定をしているものです。ご家族の推薦、提案というのは考えてはいないところですけれども、その辺りは重大事態と認定する段階で丁寧に進めてまいりたいと考えております。","id":"exchange-008"},{"speaker":"安藤委員","kind":"質問・要望","question":"被害者とか家族の知る権利というのはすごく重要視していただきたい、尊重していただきたいと、要望します。確認させてください。","respondent":"丸谷教育総合支援センター長","answer":"条例の中ではなくて、規則のほうで規定をしています。","id":"exchange-009"},{"speaker":"吉田副委員長","kind":"質問","question":"１点だけ伺いたいのですけれども、「次に掲げる事項について調査審議し」となっております。その調査の権限の中に、例えば、当事者からの聞き取りとか、そういうものは含まれるのか、その点について伺いたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"調査の中には、場合によっては、被害に遭われた児童・生徒、保護者については必ず聞き取るようにということでこれまでも調査を進めてきておりますので、今後も丁寧に進めてまいりたいと考えております。","id":"exchange-010"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"ついては、そこの子どもたちの声を引き出すことが、それなりにそれまでのお勉強とかをされているような方をぜひ選んでほしいと求めました。これについて何か既にお考えのことがあったら、ご見解を伺いたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"実際に当事者、加害となったお子さんの聞き取りということは非常に調査の中核となってくるものですから、大切なものだという認識はあります。そういったところで、心理の専門家や福祉の専門家、子どもに丁寧に対応できる委員というのを選定、進めていきたいと考えております。","id":"exchange-011"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"本当に公正な立場で、いじめをしてしまった側、いじめられたと思っている側の意見を丁寧に聴取できるような方をぜひ選定してほしいと求めました。これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"高橋（し）委員","kind":"意見","question":"２０条には、ということは、対策委員会は調査するのですよね。１４条が先だからあれですけれども、法律の立てつけが不勉強で分からないのですけれども、そのことをお尋ねしますとの意見を述べました。","respondent":"丸谷教育総合支援センター長","answer":"確かにこれまでも２０条にそのことは記載があったところなのですけれども、今回改めて１４条に役割として２点しっかりと明記することで、対策委員会の役割を明確にしたです。","id":"exchange-013"},{"speaker":"高橋（し）委員","kind":"質問","question":"役割をはっきりさせたということで、万が一、いじめの行為が起きたときには、しっかりと対策委員会で調査することを宣言したというか、決意を新たにしたというか、そういう認識でよろしいか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"重大事態が起こった際に臨時委員を置くことができるということで、次のほうにつながるような記載が必要ということもございましたので、この重大事態のことも併せてそこに明記をしたです。","id":"exchange-014"},{"speaker":"ゆきた委員","kind":"意見","question":"先日、文教委員会で視察した寝屋川市や他自治体でも、いじめ対策委員会の条例や規則で臨時委員を設置できるようにしている自治体も多いので、現実に即した対応だと思われますので、公明党としては賛成ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"},{"speaker":"安藤委員","kind":"質問・要望","question":"要望なのですけれども、子どもたち同士で話し合って自治的に解決できるような、子どもが主体の学校づくりというのをぜひ望みたいと思います。賛成いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"}]},{"id":"topic-04","title":"第８６号議案、指定管理者の指定","agenda":"第８６号議案、指定管理者の指定","exchanges":[{"speaker":"安藤委員","kind":"確認","question":"３年間やったわけですが、まだきちんとたくさん残っているのかということの確認、それが２点目です。それと、そこの(3)番目の１期目の成果についてというところで、それはどういう理念なのでしょうかというのを伺いたいと思います。","respondent":"立木保育課長","answer":"こちらは、ぷりすくーる西五反田が開設当初から、ＮＰＯ法人子育て品川のほうで運営を指定管理者として実施しておりました。特に特別な支援が必要なお子様への対応、保護者への支援等、公募によらずに指定管理者の選定を行ったです。","id":"exchange-017"},{"speaker":"安藤委員","kind":"質問","question":"前回のときには公募すべきだったと私は改めて思うのですけれども、なぜ公募にしなかったのかというのを改めて伺いたいというのが１つ。伺いたいと思います。","respondent":"立木保育課長","answer":"それを引き続き施設の運営に活かしてもらうというような考え方から、そのまま残りの３年間を福栄会にお願いしたという形になっております。幼保連携型認定こども園に移行認可を受けるためには、園庭の部分が９０m2ほど不足しておりまして、区のほうで取り組んでいるところです。","id":"exchange-018"},{"speaker":"安藤委員","kind":"質問","question":"園庭の課題もあるではないですかというのは当時も分かっていたわけで、急いでやる必要はなかったのではないかと。５年目となる今回でいろいろやればよかったのではないですかと思うのですけれども、なぜ現在移行していないのであれば、最後に伺いたいと思います。","respondent":"立木保育課長","answer":"認定こども園化に向けましては、区としましても、早期に実現をしたいと考えている中で、できる部分から取組をさせていただいたです。指定管理期間の途中ではございましたが、まずはそちらをやらせていただいたです。","id":"exchange-019"},{"speaker":"せお委員","kind":"確認","question":"幾つかお伺いしたいのですが、報告書の中で、委員の意見のところ、５ページです。７ページの委員の意見のところの(1)で認証心理士と書いてあるのですけれども、そこを確認したいのと、そこだけお願いします。","respondent":"立木保育課長","answer":"特別支援に関しての保護者の支援等に関しましては、障害児者総合支援施設のほうは福栄会がやっておりますので、そういったところをうまくお子さまや。これは直しておきます。","id":"exchange-020"},{"speaker":"せお委員","kind":"質問・要望","question":"具体的に保育課で共有するのかというところをもう一回教えていただきたいのと、それとも、区の巡回の方だけということなのか。そこもすみません、もう一度お聞かせほしいと求めました。","respondent":"立木保育課長","answer":"発生原因ですとか、今後の対応についてというようなところをまとめてもらって、それを区のほうに提出してもらうというような形になります。福栄会のほうにも恐らく臨床心理士がいると思いますので、それは福栄会の中でもそういった形で行われているものと考えております。","id":"exchange-021"},{"speaker":"せお委員","kind":"質問・要望","question":"私も以前からいろいろ要望させていただいていますけれども、以前から要望しているので、ぜひ引き続きお願いします。スムーズに連携できるようなところはお願いしたいというところで、そこはまた要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"石田（し）委員","kind":"確認","question":"この７ページでは、いわゆる人員体制は確認できたとなっていて、園庭の面積が大きな課題なわけですよね。その辺の確認だけさせてください。","respondent":"立木保育課長","answer":"シルバーセンターの部分も一体的に考えていかないといけないというような点で、今、取組をさせていただいている。区のほうで責任を持ってやる部分になってあります。","id":"exchange-023"},{"speaker":"石田（し）委員","kind":"質問","question":"シルバーセンターとかという話なので、そういうのを含めてやると、福栄会が指定管理でやられているのが非常にいいという意味合いなのですか。区が今描こうとしているのがいくのかという印象があるのだけれども、言える範囲でいいのですけれども、説明を求めました。","respondent":"立木保育課長","answer":"西五反田地区の保育需要等も考えた中で、例えば、合築も当然一つの形だと思っています。検討していかないといけないと思っていますが、特に今、福栄会がそのためにやっていただいているということでは特にリンクはしていないところです。","id":"exchange-024"},{"speaker":"石田（し）委員","kind":"質問","question":"そういった意味で質問を先ほど。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"吉田副委員長","kind":"提案","question":"それを、では今後どうやって防ぐかというあたりの提案はどうだったのか、その辺について伺いたいと思います。提案内容の評価が、お話を伺えるようでしたら、伺いたいと思いますとの意見を述べました。","respondent":"立木保育課長","answer":"こういうことがあったので、改めて気をつけるようにというような、そういったことも共有するようにしています。財務的なところで言いますと、今回のところでは、そういったところの中で満点まではいかないというところになっております。","id":"exchange-026"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"ぜひ今後、いろいろな点で、事故情報の共有は文教委員会メンバーには資料として出してほしいと求めました。満点にならないというのはよく理解できないので、今後、その辺についてはぜひ満点を出してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"高橋（し）委員","kind":"確認","question":"お伺いしたいのは、もう一回確認ですけれども、それは検討の俎上に載っているというところでしょうかというのが１つ。名前はどうにしても、一体化したものとしてやれば、改築しないでも可能なのかというところをお伺いしたいのですけれども。","respondent":"立木保育課長","answer":"当然、検討の一つとして、隣の敷地を使うという部分に関して検討はさせてもらっているというところです。９０m2分を隣の敷地の一部を使うような形で何かできないかというようなところも含めたり、今、再度検討をしているような状況です。","id":"exchange-028"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"屋上の２方向は工事とか、今お話のあったことも含めて、ぜひ検討を早急に進めてほしいと求めました。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"ゆきた委員","kind":"確認","question":"理事者からご説明があったとおり、社会福祉法人の強みを生かせる点、人員体制についても確保されている内容を確認いたしましたので、賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"先ほど質問いたしましたが、安全確保とか、それから全体の財務状況というのは、やはり満点というのは難しいのかもしれないですけれども、満点を目指して、今後とも見直していただきたいという思いを込めて、賛成いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"安藤委員","kind":"意見","question":"賛成です。令和２年度の期間途中の指定管理交代の必然性についての区の説明については、継続というのは理解できますので、賛成ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-032"}]},{"id":"topic-05","title":"第７６号議案、令和５年度品川区一般会計補正予算（歳出 文教委員会所管分）","agenda":"第７６号議案、令和５年度品川区一般会計補正予算（歳出 文教委員会所管分）","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"同じような措置をしてほしいのですが、区民で国立とか私立に通っている児童・生徒というのを把握しているのか、伺いたいと思います。それと、マイスクールのほうは、こちら、対象の学年を伺いたいと思います。","respondent":"柏木学務課長、丸谷教育総合支援センター長","answer":"私からは、国立・私立に通っている方の人数ですが、小学校で約１,２００名、中学校で約３,０００名と把握しています。 新しく開設するマイスクールの対象の学年ですけれども、資料２の(2)にありますとおり、区立小・中・義務教育学校に通う３年生から９年生の児童・生徒と考えております。","id":"exchange-033"},{"speaker":"安藤委員","kind":"質問","question":"このように表明をされているわけですから、今回と同じような同様の手法で拡大すべきだと思いますけれども、お考えを伺いたいと思います。今までなかったわけですから、そういったことは検討しなかったのか伺いたいのと、いかがか尋ねました。","respondent":"柏木学務課長、丸谷教育総合支援センター長","answer":"特別支援学校以外に、国立・私立学校への支援の拡大ですが、現時点で国立・私立の学校の支援拡大については検討はしてございません。子ども・子育て支援の強化についてのほうでも、特別区も含めまして… 多様な学びの場の提供ということでは非常に大切なことだと認識しておりますので、例えば、今後も提供を考えていきたいと思います。","id":"exchange-034"},{"speaker":"安藤委員","kind":"質問・要望","question":"そういった意味で、いろいろ検討してほしいと求めました。２３区全部踏み出したという感じではなかったかと思うので、私立、都立の学校の児童・生徒へも拡大をぜひ検討していただければと要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"理解は得られていると思うのですが、この町会長会議の中でどういう質問があったのか、質疑があったのかというのをお尋ねしたいと思います。これ、何か違いが、横文字になって、どういう仕切りになっているのかと思って、その確認です。","respondent":"丸谷教育総合支援センター長","answer":"地域説明、町会長会議が１１月１０日にございまして、町会長に説明をしてまいりました。引き続き地域の方にも十分な説明を心がけながら、開設を進めてまいりたいと思います。","id":"exchange-036"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"我々も一生懸命やりますけれども、そこは要望しておきたいと思います。この３０名を新たに設置していただけるのは非常にすばらしいことなのですが、この予測を基にどのようにイメージをしているのか、説明を求めました。","respondent":"丸谷教育総合支援センター長","answer":"確かにこの推移を見ますと、マイスクールだけではなかなか対応が難しいという認識ではあります。家庭との連携の中で対応しているものと、校内に別室指導の支援員を、一人一人の多様な学びに対応していきたいと考えています。","id":"exchange-037"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"忙しくない時間帯ではないですか。これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"高橋（し）委員","kind":"質問","question":"５年度で１５８人の希望ですから、登録者数が３分の２ぐらいというのは、その辺の数字の事情をお尋ねするのが１つ。どういった方が指導する体制になるのかということ、３０人ですから、八潮と同じぐらいなのか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"八潮型で考えると、音楽の免許であるとか、そういった教科の免許を持った方というのも募集をしていきたいと考えております。人数の規模ですけれども、今まさにその辺りを調整しているところでございまして、八潮と同等の人数を想定して募集をかけていきたいと考えております。","id":"exchange-039"},{"speaker":"高橋（し）委員","kind":"質問","question":"ですから、いろいろ校長先生の指導とかがあったとしても、余計に厳しいところがあるのではないかと思っています。ただ、そこの適応指導教室のことについて、最後、お尋ねします。","respondent":"丸谷教育総合支援センター長","answer":"他地区でも不登校特例校を設置している動きが徐々に見られているというところも我々認識していますので、検討も併せてしていきたいと考えております。","id":"exchange-040"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"ありがとうございました。国や他区の動きを十分注視して、特例校についてはぜひ進めていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"せお委員","kind":"質問","question":"私から２点お伺いしたいのですが、区や都が準備しているのは存じ上げているのですが、私立や国立というのはあるものなのか。集団での学習・体験活動というところを、どのように工夫してやっていくのかというのが分からなかったので、そこを説明を求めました。","respondent":"柏木学務課長、丸谷教育総合支援センター長","answer":"私から、奨励費の件ですが、こちら、特別支援学校への就学奨励に関する法律というのがございまして、そちらでは公立、私立、国立がこの対象になるということで定められておりますので、私立、国立も奨励費があるということになります。 今後、カリキュラムの検討等を進めていく中で考えていきたいと思います。例えば、こちらのマイスクールでも利用申請させていただいて利用するなど、そういったことも併せて今検討しています。","id":"exchange-042"},{"speaker":"吉田副委員長","kind":"質問","question":"２年生に不登校が増えているということに対しての、１、２年生を対象としたところも増やしてほしいという趣旨の質問をいたしました。こういう１、２年生の不登校が増えているという状況に対して、説明を求めました。","respondent":"丸谷教育総合支援センター長","answer":"２年生の不登校児童への対応ということですけれども、場所が４か所しかないということと、今回も見送っております。そうしたことを踏まえて、今後の不登校対策というものを進めていきたいと考えております。","id":"exchange-043"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"区全体として求めるべきことと考えていますが、それがすぐ実現が不可能であれば、ぜひ全体として検討してほしいと求めました。もし何か見解があったら、伺いたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"不登校児童・生徒の問題については、単独の学校の問題ではなくて、区全体、もっと言えば、国全体の課題だと考えておりますので、国や都の動きも注視しつつ、品川区としてできることを引き続き検討して進めてまいりたいと考えております。","id":"exchange-044"},{"speaker":"ゆきた委員","kind":"意見","question":"ただ１点、品川区として、国立・私立の特別支援学級に入学した際の学籍までは把握していると聞いております。マイスクール西大井については、こちらも賛成ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-045"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"特別支援学校給食費については求めてきたところですので、賛成をいたします。それから、マイスクールについては、先ほど要望もいたしました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"}]},{"id":"topic-06","title":"第８２号議案、品川区特定教育・保育施設および特定地域型保育事業の運営の基準に関する条例の一部を改正する条例","agenda":"第８２号議案、品川区特定教育・保育施設および特定地域型保育事業の運営の基準に関する条例の一部を改正する条例","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"参考までに、今回の文言整理に関わる、就学前の子どもに関する教育、保育等の総合的な提供の推進に関する法律、この改正の内容は何だったのか伺いたいのと、また、今回、条例改正によって、区の事業の内容に何か変化が伴ってくるものなのか、伺いたいと思います。","respondent":"石井保育支援課長","answer":"認定こども園を認定する際に、政令指定都市が都道府県に対して事前の協議をせねばならなかったところ、事前通知で済むようになったです。今回の改正は政令指定都市に係る部分ですので、区の事業内容等に変更があるものではございません。","id":"exchange-047"}]},{"id":"topic-07","title":"令和５年請願第１５号、品川区私立幼稚園保護者負担教育費の軽減に関する請願","agenda":"令和５年請願第１５号、品川区私立幼稚園保護者負担教育費の軽減に関する請願","exchanges":[{"speaker":"安藤委員","kind":"意見","question":"区として、連合会の活動についてどういう認識というか、評価されているのか。実際、連合会の活動というのはどういうことが行われているのか、もう少し説明してほしいと求めました。","respondent":"石井保育支援課長","answer":"今後行われる幼児画展覧会ですとか、ＰＴＡの大会などがあります。やはりこういった中で、保護者ですとか教職員相互の連携を図りながら、幼児教育の下支えとしてとても貢献していただいているという認識です。","id":"exchange-048"},{"speaker":"吉田副委員長","kind":"質問","question":"いわゆる学校に入ってからの教育以前の、非認知機能を育てるという意味でも、この時期の集団教育は大変大切だと認識しております。なかなか厳しい運営だというのを伺っておりますので、この請願については採択でお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"}]},{"id":"topic-08","title":"令和５年陳情第４５号、品川区立学校図書館の充実に関する陳情","agenda":"令和５年陳情第４５号、品川区立学校図書館の充実に関する陳情","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"それで、図書館運営支援スタッフの委託契約の内容について最初に伺いたいのですが、週に何日、何時から何時までという契約なのでしょうか。今実際に働いているスタッフの方というのは、正規雇用になるのか、非正規雇用になっているのか、伺いたいと思います。","respondent":"吉田品川図書館長","answer":"レファレンスや授業支援業務、教職員の相談対応、多岐にわたる内容になっております。その際には、５年間は連続して受託をするということを前提に、５年間を前提として考えているところです。","id":"exchange-050"},{"speaker":"安藤委員","kind":"質問・要望","question":"何時から何時という勤務時間の定めというのはなかったのかというのを伺いたいのと、５年間の途中であっても、変更も可能なのではないかと思います。いることで意義を果たしていると思っていらっしゃるのか、併せて伺いたいと思います。","respondent":"吉田品川図書館長","answer":"これは、学校司書は、学校図書館を活用した授業その他の教育活動を司書教諭や教員とともに進めるというところと。児童・生徒に対する直接的支援、教育目標を達成するための教育指導への支援という大きな３点、これが役割として果たされるところと認識しています。","id":"exchange-051"},{"speaker":"安藤委員","kind":"質問・要望","question":"そちらのほうについても伺いたいと思うのですが、全ての学校で定められているものなのでしょうかというのと、現行。そこら辺、伺いたいと思います。","respondent":"中谷指導課長","answer":"もう１点、スタッフとの連携というところで補足をします。所属している学校のお子さんに対してどういった情報提供ができるかというところで連携をさせていただいているというところだと理解しております。","id":"exchange-052"},{"speaker":"安藤委員","kind":"質問","question":"計画的に学校図書館を活用して、情報活用能力の育成ということで、すごく位置づけが高まっているわけです。図書館司書、運営スタッフの存在意義というのをどのように考えていらっしゃるのか、伺いたいと思います。","respondent":"吉田品川図書館長","answer":"品川区でいうところの支援スタッフにつきましては、学校や地域の状況を踏まえて、学校図書館ガイドラインのほうでもうたっているところです。その辺の総合的なところで、司書を含めて、学校図書館の運営をしていければと考えているところです。","id":"exchange-053"},{"speaker":"安藤委員","kind":"質問・要望","question":"分かりましたけれども、やはり図書館のスタッフが充実することで、もっと図書館を使った授業というのもすごく充実できると思うのです。スタッフの役割、存在というのはどのように考えていらっしゃるのか、教えてほしいと求めました。","respondent":"丸谷教育総合支援センター長","answer":"社会であるとか、そういったもので調べ学習を行ったりということは、教員が計画的に学校図書館を活用して行うものであると考えております。支援スタッフとどう連携をして、子どもたちへの充実した教育活動実現のために、打合せをしっかり行っていくことが大切だと考えております。","id":"exchange-054"},{"speaker":"安藤委員","kind":"質問","question":"週に２.５日という配置では、実際の学校図書館の開館状況について伺いたいのですが、学校図書館は実際どれぐらい開いているのでしょうか。伺いたいと思います。","respondent":"吉田品川図書館長","answer":"確かに実際の学校図書館支援員の業務としても、あと、一定楽しい場所などとなるように努力している。それはボランティアを含めましても、努力しています。","id":"exchange-055"},{"speaker":"安藤委員","kind":"質問","question":"ただ、私はこの状況ですと、居場所という点でも不十分だと思うのですけれども、居場所として、現状の２.５日で十分と言えるのでしょうか。ここも伺いたいと思います。","respondent":"吉田品川図書館長","answer":"例えば、授業等の取組につきましても支援に取り組んでまいりますし、学校図書館運営を進めてきた歴史もあります。各学校から毎年アンケートをいただいている内容も踏まえまして、今後も機会をうかがいながら対応を検討してまいります。","id":"exchange-056"},{"speaker":"安藤委員","kind":"質問・要望","question":"臨機応変に契約は見直していただきたいのですけれども、５年に一度の、要望もありました。日数を増やすという検討はしなかったのか伺いたいと思いますし、最終的に配置の時数については現行どおりとなった経過、それを伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-057"},{"speaker":"安藤委員","kind":"質問・要望","question":"これは頑張ってほしいと求めましたし、契約期間としては１年ということでもあるので、相手方を変えろとは言いません。内容を充実させる方向で協議を続けて、増やしていく方向でぜひ頑張っていただきたいという期待を込めて、質疑を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"そこをまず１点教えていただきたいのと、今の話の中で、実質２.５日ぐらい、週１５時間だとそうなると。分かる範囲で教えていただきたいのと、仮に５日間の体制をつくってくださいといったときに、その業者が人的も含めて可能なのか。","respondent":"吉田品川図書館長","answer":"途中で変更するということは、そこのところは後から大幅な変更はできないですので、基本的には見直せないという形で考えております。今いる人を替えなければならないという状況が発生するということは、昨年度、検討する中で各事業者が異口同音にお話しされていたところです。","id":"exchange-059"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"そこをどうやって工夫して充実をさせていくかというのは、ぜひ引き続き検討していただいて、いい案を見つけていただきたいと。一緒に新しい答えを見つけていきたいと思いますけれども、現実的に今どういう課題があるのかというのが分かったので、以上で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-060"},{"speaker":"ゆきた委員","kind":"質問","question":"現状の中でどういった工夫、もしあれば、教えてほしいと求めました。その中で司書資格を持っている方がどれだけいるのかという分母と分子、何割ぐらいなのかというのを教えてほしいと求めました。","respondent":"吉田品川図書館長","answer":"そのうち司書資格、司書教諭等を持っている職員、社員につきましては、５６名中４９名おりますので、８７.５％、今現在はこのような構成です。そのようなところで、質の向上を図るというところを現在進めているところでもあります。","id":"exchange-061"},{"speaker":"吉田副委員長","kind":"質問","question":"他区の状況といいますか、他区の学校の図書館の状況とか、司書の配置状況とか、把握しておられるのでしょうか。何々区とか何々市は既に５日間配置しているとか、どれぐらいの配置状況なのか把握しておられたら、伺いたいと思います。","respondent":"吉田品川図書館長","answer":"一番多いところは１,５００時間を超えているようなところもありますし、品川区の２倍程度のところも当然あります。品川区は、大体１０番目から１３番目ぐらい、７３５時間につきましてはそのぐらい、真ん中辺りです。","id":"exchange-062"},{"speaker":"吉田副委員長","kind":"確認","question":"真ん中ぐらいというのは、要するに２３区に限ってということでしょうか。それを１個確認させてください。","respondent":"吉田品川図書館長","answer":"大変失礼いたしました。２３区中、大体１０番目から１３番目辺りのところの年間委託時間数です。","id":"exchange-063"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"ぜひこの辺は手厚くしていただきたいと思っているのですけれども、そういうので出てきて、それで決めてしまうということなのでしょうか。どれくらい事業者の希望と、微妙な線も入ってしまうかと思いますが、お答えになれる範囲で教えてほしいと求めました。","respondent":"吉田品川図書館長","answer":"大きくは４つぐらいに、契約の金額の内訳が分かれます。支援スタッフにつきましては、そちらの金額が、提案された金額がほぼ人件費の中にという形で受け止めているところです。","id":"exchange-064"},{"speaker":"吉田副委員長","kind":"確認","question":"そうしますと、契約はほとんど人件費ということになるという理解でよろしいでしょうか。確認させてください。","respondent":"吉田品川図書館長","answer":"契約の金額につきましては、ほぼ人件費の金額になります。","id":"exchange-065"},{"speaker":"吉田副委員長","kind":"質問","question":"それは１人当たり何時間の、１時間当たりは幾らぐらいというような形でフィックスされてしまっているという契約のやり方なのでしょうか。契約金額、結構大切かと思うので、説明を求めました。","respondent":"吉田品川図書館長","answer":"契約の金額に当たりましては、各事業者それぞれ思惑があるのか、１人当たり一律の金額ではないところです。１人当たりの金額は異なっている部分でありまして、５つ契約がありますけれども、それぞれ金額はまちまちです。","id":"exchange-066"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"資格はともかく、その辺についての契約をするときの品川区としての要望とかをどのように話し合っておられるのか、伺いたいと思います。それで、司書を契約するときに、そういうことも入っているのか、伺いたいと思います。","respondent":"吉田品川図書館長","answer":"今までもこれは司書もそうですが、図書館のボランティアも含めて、学校図書館の開館には尽力をされてきたところです。図書館も含めて、いろいろな意味で知見のあるスタッフというのを準備するよう、事業者にはお願いしています。","id":"exchange-067"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"その一つの条件として、司書の配置というのはすごく重要だと思いますので、ぜひ今後前向きに考えてほしいと求めました。これは要望にしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-068"},{"speaker":"せお委員","kind":"質問・要望","question":"私の視点では、特別な支援が必要な児童・生徒への支援員など、そういったところを早急に増やしていくことを優先させたい。児童・生徒が、まずは特別な支援が必要なお子さんの支援員などを充実させていただきたいという思いもありますので、本日は不採択でお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-069"},{"speaker":"ゆきた委員","kind":"確認","question":"もちろん図書館運営支援スタッフの勤務日数の増加の重要性は前向きに捉えていくべきものですが、予算の絡みもある話もただいま伺いました。不足部分を補っている点から、質の向上に向けて施策を前に進めていることを確認いたしましたので、この陳情に関しては不採択でお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-070"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"やはり今、５年間の総合評価の中の途中の年であるということで、そこで急に金額を大幅に増やすということは確かに難しいかと思います。それも本当に早急にやるべきだと思うのですけれども、しかも、ぜひ前向きに検討してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-071"},{"speaker":"安藤委員","kind":"意見","question":"学校図書館をどう充実させるか、司書をどう配置するかという話なので、支援員も進める。そうした事業は見直すということで財源を生み出して、進めていくというのが私は大事だと思っていますので、採択ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-072"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"何学級以上の小学校が幾つとありますけれども、小中一貫校は、２校分なので２人配置されていると伺っています。ですから、２０学級以上云々というのがありますけれども、今回のこの陳情に関しては不採択としてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-073"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"今、学校図書館の位置というのは非常に重要な位置に来ているのだと思いますので、そこの充実というのはしてほしいと求めました。その辺に関してはぜひやっていただきたいと思いながらも、今回、この陳情に関しては不採択で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-074"}]},{"id":"topic-09","title":"教育目標および基本方針の改訂","agenda":"教育目標および基本方針の改訂","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"そこら辺の教育委員会の中での審議状況などを聞かせていただきたいというのが１つと、それは理由は何なのですかというか、そこら辺を伺います。","respondent":"宮尾庶務課長","answer":"２点目の、現行の考え方を継承して、表現の修正をしているという大きな考え方の下に行ってあります。私ども教育委員会には共通して持っている考え方ですが、方針に関しては、改めての表記というのはしていないというものです。","id":"exchange-075"},{"speaker":"安藤委員","kind":"提案","question":"最後、もう１点質問しますけれども、少なくとも人権というところがあるではないですか。国際条約ですから、ぜひ検討していただきたいのですが、ご答弁を伺いたいと思いますとの意見を述べました。","respondent":"宮尾庶務課長","answer":"教育目標、基本方針につきましては、本当に我々教育委員会の大きな考え方、指針、よりどころとなるものです。考え方としては、現状のところでは、大きくここについて変更を加えるという考えは現時点ではございません。","id":"exchange-076"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"教育大綱は令和１１年までかかっているので、令和３年に完全実施されて、まずは区立学校の大きいほうの教育要領をどうされるかということが１つ。一般質問のご答弁にもありましたけれども、２２年に改訂してから、どのようにされていくのでしょうかということです。","respondent":"中谷指導課長","answer":"こちらにつきましては、現在、教育検討委員会という組織の中で、様々、今までの振り返りと、今後どうしていくかということで議論をしています。こちらも行く行くは改訂ということで、中長期的に見る中での見込みとして、そのようなスケジュールで進めしています。","id":"exchange-077"},{"speaker":"高橋（し）委員","kind":"質問","question":"では、小中一貫教育要領も一緒にということでよろしいのか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"小中一貫教育要領は平成２２年度に改訂を行いまして、学習指導要領が改訂になった平成２９年、それを基に教育活動を進めているところです。ですので、小中一貫教育要領は、名称が変わって、品川区立学校教育要領になっているです。","id":"exchange-078"}]},{"id":"topic-10","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"主な相談の内容というのですか、この実績はそれぞれ何件ぐらいあるのでしょうかということと、何が変わるのでしょうかというか。それも伺います。","respondent":"染谷子ども家庭支援センター長","answer":"子ども家庭支援センターにご相談いただくといった連続性を保ってはいるものの、それぞれ個別にご相談を対応させていただいていたところを。","id":"exchange-079"},{"speaker":"安藤委員","kind":"質問・要望","question":"これ、いわゆる子ども家庭支援センターという名前がなくなって、子ども家庭センターになるということなのでしょうかということを確認します。相当利用が伸びているということで、やはりすごく求められている事業ですし、その時々で気軽に相談できるところがある。","respondent":"染谷子ども家庭支援センター長","answer":"子ども家庭センターを令和７年度に開設するに当たっては、区民の方に混乱がないよう、分かりやすい名称で統一していければと考えております。近距離にあって、継続的に相談ができるような、そういう機関というのはより重要性を増しているのではないかと認識しています。","id":"exchange-080"},{"speaker":"安藤委員","kind":"質問・要望","question":"最後、質問はこれで終わりにしますが、おむつの宅配の事業を新規でやるではないですか。それはこのどこら辺に位置づくのですかというところを最後に説明を求めました。","respondent":"染谷子ども家庭支援センター長","answer":"保健センター側で実施している事業にはなりますけれども、先ほどご説明をしたバースデーサポートをこちらで実施する、きちんと見守りが利くような体制を取っていきたいと考えております。","id":"exchange-081"},{"speaker":"安藤委員","kind":"質問・要望","question":"０歳の境というのは、横串を刺すといいますか、そういったこともお願いしたいと思います。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-082"},{"speaker":"ゆきた委員","kind":"質問","question":"地域の声で、相談したいと思っていても、児童センターに行かないと相談できないのだというのを現場の声でよく聞きます。妊娠期面談では、児童センターの子育て相談員とのオンライン面談について、区のお考えがあれば改めてお聞きできればと思います。","respondent":"染谷子ども家庭支援センター長","answer":"今回、その検討をする中でも、オンラインの面談の必要性のところについては検討を進めてまいりたいと考えております。バースデーサポートの事業を実施するに当たって、アウトリーチといった、そういったことも実施をしていければと考えているところです。","id":"exchange-083"},{"speaker":"ゆきた委員","kind":"質問","question":"そうなると、相談できる場というのが、職場から帰ってきて、保育園に行って、保育園の先生に相談するしかないというような声も聞きます。急なのですけれども、区のお考えがあれば、お聞きできればと思います。","respondent":"染谷子ども家庭支援センター長","answer":"地域子育て相談機関というものについては、一部、保育園における相談といったところも視野に入っております。それとも、なるべく多くの方がご相談いただけるような体制というのは、引き続き充実に向けて検討してまいりたいと考えております。","id":"exchange-084"},{"speaker":"高橋（し）委員","kind":"意見","question":"できるだけ同じ担当の方というのがうまくいければいいかと思うので、ぜひ今構築していくというお話だったとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-085"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"それぞれありがとうございました。どの媒体なのかあれですけれども、どこから情報というのを皆さん多く受けて、インプットされているのかというのを説明を求めました。","respondent":"染谷子ども家庭支援センター長","answer":"産後の家事育児支援の利用助成、本事業を知ったきっかけが何かというところの回答につきましては、こちらで知ったという方が４５％いらっしゃいます。それから、あと、区のホームページで情報を得たというのが上位に来ているような状況です。","id":"exchange-086"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"いきなりずっとホームページを毎日見ないですから、今日こんな情報がというのはないです、そんな普通の人が。やっていただけたら、もっと皆さんがやっていることが役に立つものになってくるのかと思うので、その辺はぜひ徹底してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-087"},{"speaker":"せお委員","kind":"質問","question":"皆さん時間がない中で、そこが本当に大変で、それはシステムの構築とか、どういった検討になっているのかというのをあえてお聞きしたいです。そちらをお願いします。","respondent":"染谷子ども家庭支援センター長","answer":"情報共有の関係の分科会みたいなものを設置して、その中で情報の共有の在り方等について検討を進めていければと今考えているところですので、この中で十分検討してまいりたいと思います。","id":"exchange-088"},{"speaker":"せお委員","kind":"質問・要望","question":"もちろん全てが全て、ある程度の基本的なところとかは共有していただきたいというのは私たちの思いではあるので、ぜひ検討をお願いします。保護者の方からご要望いただいたのが、どういったサポート、説明を求めました。","respondent":"染谷子ども家庭支援センター長","answer":"こういったものを発掘し整理をしていく中で、それ自体を皆さんに分かりやすくお伝えできるようなものをきちんと整理していければと考えております。フローチャートという形なのかどうかというところも含めて、検討させていただければと考えています。","id":"exchange-089"},{"speaker":"吉田副委員長","kind":"質問","question":"そのときは状況も変わっているでしょうから改めて相談してくださいとか、何かそのような最初の合意があれば、ある程度できるのではないかと。直接今関係なくても、配布できるようなところまでは検討していただけたらいいと思っているのですけれども、いかがか尋ねました。","respondent":"染谷子ども家庭支援センター長、藤村子ども育成課長","answer":"１点目の情報の共有のところについて、私からお答えをします。先ほど令和７年度開設の子ども家庭センターの説明の中で、その組織を検討していく中で、検討を積極的にしていきたいと考えております。 子育てガイドのところについて、私からお答えします。そちらについても対応するために、考えていきたいと考えていますので、よろしくお願いいたします。","id":"exchange-090"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"すごく両方あって初めてきちんと認識されるというのが、私が議員になる前の役割を務めていたときも、片方では駄目なのですよね。ホームページとかを確認して出ていると、やはり両方、より多くの方たちが適切な情報を受け止められるように努めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-091"},{"speaker":"つる委員長","kind":"質問・要望","question":"確認させていただいた、私も追いながら確認していきたいというところで、改めて今後確認させてほしいと求めました。どうしてもいろいろな予算の関係上だとか、この辺りのいわゆる第２子の年齢の捉え方、都なのかということを説明を求めました。","respondent":"染谷子ども家庭支援センター長","answer":"ここの上限時間の設定につきましては、現状でいうと、東京都の補助金を最大限活用して、上限いっぱいで実施しているものです。３歳以上になると、やはり２０時間の上限設定は少ないという話を伺うこともありますので、現状もさせていただいているところです。","id":"exchange-092"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/106437?Template=document&Id=5114#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":81664,"voices":298}},{"id":"r05-20231127-5","meetingId":"r05-cm11","date":"2023年11月27日","dateIso":"2023-11-27","committee":"総務委員会","time":"午前１０時００分～午前１１時１３分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を29件整理しています。","topics":[{"id":"topic-01","title":"冒頭に申し上げましたとおり、取り上げる順番を変更して行います。 まず、(2)第８５号議案、浜川小学校校舎・幼稚園園舎改築その他工事請負契約の変更","agenda":"冒頭に申し上げましたとおり、取り上げる順番を変更して行います。 まず、(2)第８５号議案、浜川小学校校舎・幼稚園園舎改築その他工事請負契約の変更","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"そういう産業、また、そういう事業者に対しても平等な対応を行政としてとるべきだと私は思います。意見だけ言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"石田（秀）委員","kind":"質問","question":"お伺いしたいのは、なるべく当初の金額からあまり上がらないような形で交渉していただいているのだろうと思っています。集めているのは私も知っているけれども、リアルタイムで集めるという作業を、そこら辺はどうされているのかというところだけ聞きたいと思います。","respondent":"小林施設整備課長","answer":"私のほうから一括してご説明いたしますが、月に１回必ず、情報を提供していただいているところです。その辺につきましては、施設整備課と学校施設担当についても同様の流れで、今、進んでいるところです。","id":"exchange-002"},{"speaker":"石田（秀）委員","kind":"意見","question":"多分これぐらいの規模になると、５％取るのもやっとだと思います。それはそれで非常にぎりぎりの話をしているのだろうから、そういうお互いぎりぎりの中でやっているので、ぜひそこら辺はとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-003"},{"speaker":"須貝委員","kind":"質問","question":"ですから、様々な建設業界でそういうことが起きているということは、私はやはり自治体としてもそれは捉えていてほしいと思います。それがインフレスライドということで公共機関だけこういう制度をとっているというのは、私はいかがなものかなということで、指摘します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"須貝委員","kind":"質問","question":"かなり高額だと思うのですが、今の様々な小中学校においても、このような設備というのはどんどん導入されているのでしょうか。説明を求めました。","respondent":"柏木学務課長","answer":"給食設備の関係ですが、今回契約しております機器につきましては、学校給食法に基づき定められている学校給食衛生管理基準にのっとりまして整備しているものですので、ほかの学校についても同様のものが整備されているものです。","id":"exchange-005"}]},{"id":"topic-02","title":"第７７号議案 品川区組織条例の一部を改正する条例","agenda":"第７７号議案 品川区組織条例の一部を改正する条例","exchanges":[{"speaker":"澤田委員","kind":"質問","question":"総務部が区長室となり、税務課が企画経営部に移管されますけれども、区税に関することという中で、ふるさと納税に関することを行っていくと思うのですけれども、具体的にはどのようなことを職員の方はされるのか尋ねました。","respondent":"佐藤（憲）企画課長","answer":"既に検討や、来年度予算の検討もしているところですが、税務課を企画経営部に移管するものです。具体的には、今、予算内容の検討をしておりますので、別途、適切にご報告したいと思います。","id":"exchange-006"},{"speaker":"須貝委員","kind":"質問","question":"仕事ですからそれぞれ割り振られたところはやるのでしょうけれども、こういうふうに細かく分けてきた根本的な理由を教えてください。それぞれそこに課長が今度配置されるわけですから、その課長もやはり相当増えて、何か所くらい増えたのか。","respondent":"佐藤（憲）企画課長","answer":"行政課題に対応することと体制の強化、あと、区民の方に分かりやすくという面を３本柱として検討しています。経済支援、そういった課題に適切に対応していくために、適切に対応していきたいと考えております。","id":"exchange-007"},{"speaker":"須貝委員","kind":"質問","question":"品川区でも行財政改革をやっていますけれども、こういうふうに予算が増えていくという、そこら辺もいろいろ検討しながらやっているのですか。それぞれの政策を遂行するに当たって、それが優先で、課長はこれだけ増えるなら増えてしようがないのだよということなのか尋ねました。","respondent":"佐藤（憲）企画課長","answer":"こちらに関しましては、品川区の職員の人件費は２３区平均より下というところでご説明していると思います。そこに対応するために、適切に人員増も図りつつ、行革も行いながらバランスよく進めていきたいと考えております。","id":"exchange-008"},{"speaker":"須貝委員","kind":"質問・要望","question":"できるだけ区民に分かりやすい、迷わないような取組は、今までどおりしっかりやってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"松本委員","kind":"意見","question":"今の須貝委員のところに追加で、数字が出てこなかったのであれなのですが、人件費はどれぐらい増えるのか、多分そろそろある程度出ているのかなと思うのですけれども、そこの数字をお示しいただければなと思いますとの意見を述べました。","respondent":"佐藤（憲）企画課長","answer":"課長級ポスト増に伴う人件費ですが、詳細な資料を今持っていないのですが、１人１,０００万円として、ポストが８増ですので、８,０００万円。〔「もともといた人との差額は」と呼ぶ者あり〕 そこまで詳細な数字が今手元にないです。申し訳ございません。","id":"exchange-010"},{"speaker":"松本委員","kind":"質問","question":"すごい極論で申し上げると、これまで例えば５００万円だった人が１,０００万円になるとすると、５００万円分の増になるわけではないですか。この移管によってどういう効果があるのかというところだと思って、どうしても税務課になる、いかがか尋ねました。","respondent":"佐藤（憲）企画課長","answer":"ご質問は、ふるさと納税に関して、税務課の移管をどのように検討したかというところかと思います。調整機能をさらに強めたほうがいいだろうという議論をしてきまして、来年度、さらにふるさと納税の対応を進めていこうという議論をしたところです。","id":"exchange-011"},{"speaker":"松本委員","kind":"質問","question":"そうすると、例えば地域産業と連携するという視点とかもふるさと納税の場合はあると思うのですけれども、そこは企画経営部という、どちらかというと全体を見ることができるので、そちら側で各所管課と調整するような枠組みを考えていらっしゃるということでよろしいか尋ねました。","respondent":"佐藤（憲）企画課長","answer":"ふるさと納税に関するご質問ですが、地域産業、あと福祉施策ですか、子ども食堂のように区民の方がより参加しやすいものについても横串を刺して、企画経営部が中心になって進めていきたいと考えております。","id":"exchange-012"},{"speaker":"松本委員","kind":"質問","question":"人件費の部分はそれでそうだと思うのですけれども、課の数というのは、２３区、他の区と比べたらどうなのでしょうか。今回、新設する課が８あるということで、課は増えると思いますが、それは他区と比べると、どういうふうに考えたらいいか尋ねました。","respondent":"佐藤（憲）企画課長","answer":"他自治体と比べた課の数というところです。２３区の課長職の情報については、ざっくりな感覚で申し上げるのですが、品川区の課の数は比較的少ない自治体なのかなと考えています。","id":"exchange-013"},{"speaker":"大倉委員","kind":"質問","question":"課長級をやってもらう人の人材を確保するのはどうするのかというので、人材育成をどのようにしっかり進めていくのかというところを教えてください。その専門性とかも、そういった育成をしていく専門的な部分をどのように考えていくのかというお考えを持たれていると思うので、ぜひ説明を求めました。","respondent":"佐藤（憲）企画課長","answer":"２３区全体でですが、新たな行政課題にしっかり対応していくというところで、組織改正をご提案しています。人材育成基本方針を今改定している中で、包括的に検討しているところですので、人材の育成を図っていきたいと考えております。","id":"exchange-014"},{"speaker":"大倉委員","kind":"質問・要望","question":"専門的な部分、戦略を持ってやっていくというところは非常に賛成するところであるので、ぜひしっかり進めていっていただきたいなというところです。１点、特に広報なんかは、この辺についてはどういう意識というか戦略を持ってこのようにしているのかというのを説明を求めました。","respondent":"佐藤（憲）企画課長","answer":"今回は情報発信やコンプライアンス対応の強化を図る組織を新たに配下といたしまして。組織名称は、所掌業務を表すとともに、区の打ち出しとしても考えておりますので、そういった点も踏まえて、今回、区長室としたところです。","id":"exchange-015"},{"speaker":"大倉委員","kind":"提案","question":"所管に係る行政の課題とかをしっかり進めていくというところでは、区長にも様々判断するところが増えるのかなと思いますが、分かりました。提案を様々していきながら、区長がスピード感を持ってとか、何かの判断をしながら進めていくという認識でいいのかだけ説明を求めました。","respondent":"佐藤（憲）企画課長","answer":"区長室設置に伴うスクラップアンドビルドと、区長が積極的に進めていく施策については直接指示が、よりスピード感を持って区政を進めていくというところだと認識しております。","id":"exchange-016"},{"speaker":"須貝委員","kind":"質問","question":"もう１点だけ、人事課長にお聞きしたいのですけれども、こうやって増やしていくのは大丈夫なのですか。そうすると、今後さらに次の担い手、次の課長、またその次の課長というのが、今度そろわなくなったら、また縮小するようなことになっていくのか尋ねました。","respondent":"崎村人事課長","answer":"人事課としても非常に強く意識して実施していますし、これまで人事委員会が選考を実施して管理職に昇任させていたのですけれども、管理職については引き続き確保を図っていきたいと考えております。","id":"exchange-017"},{"speaker":"松本委員","kind":"意見","question":"すごく細かいところですけれども、資料を見ると、人権啓発課のフォントが小さくなっているのですが、これは何か意図があるのか。１０ポイントぐらいなのが９ポイントぐらいになっているのは、何か意図があるのか、全くないのかとの意見を述べました。","respondent":"佐藤（憲）企画課長","answer":"課に関しては今検討中でございまして、人権啓発課の分掌事務は検討しているというところもありますので、新しい組織規則の範囲内でご説明いたします。","id":"exchange-018"},{"speaker":"石田（秀）委員","kind":"質問","question":"その目的は何ですかといったときに、区民の幸福（しあわせ）ですということなのだろうと思います。区民の方にもっと期待してください、この組織改正でというのを、もう少し説明してほしいな。","respondent":"佐藤（憲）企画課長","answer":"区民や事業者の声などから、幸福度の向上につながる施策とはどういったものかというのを来年度予算に向けて検討しているところです。","id":"exchange-019"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"もう少し丁寧にやってもらわないと、あまりに軽視し過ぎではないかなと思っていて、そこら辺も答えてほしいな。最初にそこの入り口で。","respondent":"佐藤（憲）企画課長","answer":"体系的にどう進めていくのかというところは今しっかり検討していますので、そういった中でまたしっかり進めていきたいと考えております。今、来年度予算の編成を検討していることもありますので、その辺も踏まえて、しっかり検討していきたいと考えています。","id":"exchange-020"},{"speaker":"石田（秀）委員","kind":"質問","question":"少なくとも１年、そこは答弁は要らないので、ぜひそういう人材育成をしてほしいと思っています。人を増やしてほしい部分と、極端なことを言って私は部長が２人いてもいいぐらいな、えっと思った私がいます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"塚本副委員長","kind":"質問","question":"８ポスト増えるということで、例えば新庁舎なんかは分かりやすくて、造るまでの仕事なのだという。どこかがゴールとか、何の課というふうにするのかというところの判断は、どういう考えに基づいているのかというのを最初にお伺いしたいと思います。","respondent":"佐藤（憲）企画課長","answer":"長期的に考える場合は、またそれはそれで体制を考えるということで、担当課長としております。","id":"exchange-022"},{"speaker":"塚本副委員長","kind":"意見","question":"ミッションが終わったときに、次のステップというところで、コストみたいな話になりがちです。その辺のところは、現在、どのぐらい検討されていますかとの意見を述べました。","respondent":"佐藤（憲）企画課長","answer":"様々な課題に行政としてしっかり対応していくというところですので、様々な実施計画ごとの改定も予定されていますので、適宜適切に組織の再編をしていくというところで考えております。","id":"exchange-023"},{"speaker":"塚本副委員長","kind":"質問","question":"庁舎のこととか広報、それから人事とか人権啓発だとか、そういったところでたくさんの所管を抱えると。そういうことで、区長としてここを直轄で力を入れて推進していくのだというメッセージが込められているという捉え方でよろしいか尋ねました。","respondent":"佐藤（憲）企画課長","answer":"特にそこだけを進めていくというところではなく、区長に一番近い位置で仕事をしている総務部をベースにして、区長の意向をより反映していくという考え方です。","id":"exchange-024"},{"speaker":"塚本副委員長","kind":"質問","question":"ちょっと細かいというか、突っ込んだ話になりますが、例えば区政運営会議とかをやっているではないですか。やはりそこは区長室なのだから、区長裁決で進めていくみたいな感じになるのかというのは、いかがか尋ねました。","respondent":"佐藤（憲）企画課長","answer":"今まで区政運営会議という形で月２回ほど実施しておりまして、その運営の仕方を変える予定はございません。意見をいただいて、あとはいろいろ確認しながら進めていくというところは、全く変わる予定はございません。","id":"exchange-025"}]},{"id":"topic-03","title":"専決処分の報告","agenda":"専決処分の報告","exchanges":[{"speaker":"須貝委員","kind":"意見","question":"毎回言っていると思うのですが、インフレスライド条項は、今回も第１回・第２回変更ということになります。こういう仕組みがあるならば、他の産業においても平等な対応をしていただけたらありがたいなと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-026"}]},{"id":"topic-04","title":"専決処分の報告について（報告第３５号）","agenda":"専決処分の報告について（報告第３５号）","exchanges":[{"speaker":"須貝委員","kind":"質問・要望","question":"インフレスライドは、他の産業にも平等な対応をしていただきたい。お願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"}]},{"id":"topic-05","title":"専決処分の報告について（報告第３６号）","agenda":"専決処分の報告について（報告第３６号）","exchanges":[{"speaker":"須貝委員","kind":"質問・要望","question":"インフレスライド条項は、ここに適用されているなら、他の産業にも平等な対応をしていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"}]},{"id":"topic-06","title":"専決処分の報告について（報告第３８号）","agenda":"専決処分の報告について（報告第３８号）","exchanges":[{"speaker":"須貝委員","kind":"質問・要望","question":"今回は排水施設の設置の取りやめによる変更もありますが、やはりインフレスライドに対しては他の産業においても平等な対応をしていただきたい。今回、ほとんどみんなインフレスライドで請負契約が変更されるというのは本当にまれな例だと思いますが、早く解消してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/246119?Template=document&Id=2282#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":24465,"voices":130}},{"id":"r05-20231128-6","meetingId":"r05-cm11","date":"2023年11月28日","dateIso":"2023-11-28","committee":"区民委員会","time":"午前１０時０７分～午前１１時２５分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を36件整理しています。","topics":[{"id":"topic-01","title":"施設予約システムのリニューアルに伴う運用変更等","agenda":"施設予約システムのリニューアルに伴う運用変更等","exchanges":[{"speaker":"横山委員","kind":"質問","question":"こちらは手数料といいますか、ランニングコストみたいな部分が今までとこれからでどういった形で変わってくるのかというところを教えてください。最後に、４の周知方法なのですけれども、周知の時期はどのくらいの時期を考えていらっしゃるのか説明を求めました。","respondent":"横田情報推進課長","answer":"５月１３日から１４日ですが、最終的なデータ移行などを行いますので、そのときはシステムの利用停止ということを予定しております。３月１日号の広報しながわで周知を予定していまして、また４月以降、ホームページとかＳＮＳで周知をする予定になっております。","id":"exchange-001"},{"speaker":"横山委員","kind":"確認","question":"お休み等、区のほうから利用者にという形で、一方向でそういったことができる機能がシステムとしてできるという認識で合っていますでしょうか。確認だけお願いします。","respondent":"横田情報推進課長","answer":"おっしゃるとおりです。","id":"exchange-002"},{"speaker":"横山委員","kind":"質問","question":"理解いたしました。利用停止の間の対応というのは区としてどうされるのかというところをちょっとお聞きしたかったので、そちらの補足をお願いできればと思います。","respondent":"横田情報推進課長","answer":"今現在この辺りはどうすべきかとちょうど詰めているところでして、決まり次第またご報告させていただければと思いますので、よろしくお願いします。","id":"exchange-003"},{"speaker":"横山委員","kind":"質問・要望","question":"どうやってフォローするかというところもしっかりと留意していただいて、そして５月からの新しいシステムの切替えというところでランディングさせてほしいと求めましたので、どうぞ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"あくつ委員","kind":"質問","question":"細かいことを伺いたいのですけれども、オンラインで予約をして、逆に今までどおりの現金の支払いというのはできるのかどうかということが一つ。領収書名というのは団体名で出るのか、これはちょっと細かい事務的なところですけれども、利用する側としてお伺いさせてください。","respondent":"篠田文化観光課長、横田情報推進課長","answer":"現金のお取扱いに関しては、クレジットカードでのお支払いができるというのが一つ新しい取組であります。当然クレジットカードをお持ちでないお客様もいらっしゃいますから、現金の取扱いは、今後も変える予定はございません。 領収書の件ですが、今手元に資料がございませんので、確認してまたご報告します。","id":"exchange-005"},{"speaker":"あくつ委員","kind":"質問・要望","question":"これがカードになった場合に、個人名が出ると、その辺りは利用者側の都合に合わせた形でしっかり領収書が出るような仕組みにしていただきたいです。細かいことで恐縮ですけれども、。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"えのした委員","kind":"意見","question":"より一層区民の利便性向上につながると思っていますけれども、２の主な変更点の(2)、オンラインクレジットカード決済を導入する。","respondent":"横田情報推進課長","answer":"確認漏れなどによって事故が起きるという可能性がありますので、スタート時点ではキャッシュレスでの返金を見送る予定になっております。今後につきましては、システム事業者とかキャッシュレス事業者と区で、３者でできるような形で調整していく予定になっております。","id":"exchange-007"},{"speaker":"えのした委員","kind":"確認","question":"確認が取れましたので、安心しました。そういった取組を進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"山本委員","kind":"質問","question":"そうすると、今回システムとして、抜本的というのはどういったところに見直しを試みたのかというところをお伺いしたいと思います。それ以外のキャッシュレスの方法も今後使えるようになるのでしょうかというところもお聞かせほしいと求めました。","respondent":"横田情報推進課長","answer":"システムの選定ですが、令和４年度にシステムのプロポーザルを実施しまして、選定された事業者でシステムを構築しているということになります。","id":"exchange-009"},{"speaker":"山本委員","kind":"質問・要望","question":"このようにお伺いできてとてもよかったなと思います。いろいろなものに広げていただくと、使いやすさがより増していくと思いますので、その対応も引き続きお願いできればと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"せらく委員","kind":"質問","question":"今ある口座振替というのも残されるのでしょうかということをお聞きしたいのと、令和４年度の時点でリニューアルの予算が組まれていたということなのか、お聞きしたいです。","respondent":"三井スポーツ推進課長、宮澤地域活動課長","answer":"公園の施設につきましては、口座振替の登録をしておりますので、今後も残していく予定にしております。 令和４年度にプロポーザルで事業者を選定しましたが、このリニューアルに向けた予算については、令和５年度に予算を計上しております。ですので、契約は令和５年度になってから契約をしたです。","id":"exchange-011"},{"speaker":"藤原委員","kind":"質問","question":"施設予約システムですけれども、まず何で中小企業センターは、ここに参加していないのか尋ねました。","respondent":"小林商業・ものづくり課長","answer":"個別に文化観光課長とスポーツ推進課長からご説明させていただいた部分というのは、付加情報として説明させていただいたところです。ですので、中小企業センターも含めて、幅広く施設予約システムの対象施設だというふうに認識しています。","id":"exchange-012"},{"speaker":"藤原委員","kind":"質問・要望","question":"中小企業センターも施設がありますよね。入っているのだけれども、最初の説明で入っていないとか、でも入っているのですとか、よく分からないので、具体的に教えていただきたいです。","respondent":"宮澤地域活動課長","answer":"区民集会所を含めまして、先ほど主な変更点ということで、キャンセルの際の取扱いというのを説明させていただいたところです。ですので、区民集会所だけというわけではなくて、その他の施設も含めて、運用を変更しますです。","id":"exchange-013"},{"speaker":"藤原委員","kind":"質問","question":"地域活動課長が説明してくれれば、もうそれで分かるでしょうということだったということですか。７日前にいろいろ計画したりとなるのは、その辺についてどういう声があったのか、また分けたのかという点についても説明していただけますか。","respondent":"宮澤地域活動課長、篠田文化観光課長、三井スポーツ推進課長","answer":"キャンセルの取扱いを変更する背景という部分なのですけれども、７日以内に窓口等で現金でお支払いをしていただいていたというところです。… 使わなくなったのだけれども、７日前までで全額返ってくるのだったらということで、そういった連絡をなかなかいただけないということも考えられます。… 直前にキャンセルされてしまうとそのまま埋まらないというところもありますので、そちらについて考えた結果、運用は変更しないということで考えています。","id":"exchange-014"}]},{"id":"topic-02","title":"住民基本台帳事務における「特定個人情報保護評価」の実施","agenda":"住民基本台帳事務における「特定個人情報保護評価」の実施","exchanges":[{"speaker":"えのした委員","kind":"確認","question":"令和３年にページができていて、どのような団体が点検するのか、そこだけ確認させてください。","respondent":"吉野戸籍住民課長","answer":"こちらは個人情報保護委員会とは直接全く関わってはいないところなのですけれども、品川区個人情報保護審議会の委員になります。実際に特定個人情報保護評価の概要と説明も、この評価が正しいかどうかというところで、第三者委員の方に評価していただくような形になります。","id":"exchange-015"},{"speaker":"えのした委員","kind":"確認","question":"品川区にもそういった委員会があるということで、確認が取れました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"せらく委員","kind":"質問","question":"１２月１日からパブリックコメントの実施という予定なのですけれども、区民意見の聴取ということで、何に対しての区民の意見を聴取するのかよく分からなくて、教えてほしいと求めました。","respondent":"吉野戸籍住民課長","answer":"こういったリスクがありますよとか、こういったファイルを使っていますとか、そういったところも全部記載されているのです。皆さんの情報をどのように使っています、リスクに対してはこういったリスクに対応していますというところが全て書かれたものになりますので。","id":"exchange-017"},{"speaker":"せらく委員","kind":"質問","question":"評価書をご覧いただいて、その上で意見を聴取するという形になるのか尋ねました。","respondent":"吉野戸籍住民課長","answer":"そのとおりです。","id":"exchange-018"},{"speaker":"横山委員","kind":"質問・要望","question":"ちょっと確認させていただけたらと思うのですけれども、移行作業が円滑かつ安全に実施されるということを求めているのかなと思うのですけれども。全体の流れを確認させてください。","respondent":"吉野戸籍住民課長","answer":"特定個人情報ファイル、いわゆる特定個人情報を扱う機関は、少なくとも５年以内に１回は、個人情報保護委員会の評価を受けなければいけないのです。","id":"exchange-019"},{"speaker":"横山委員","kind":"質問","question":"今のご説明だと、もともと評価書というものが品川区のホームページに公開されていますよね。それが５年前につくられたので、評価のタイミングであるという理解でよろしいか尋ねました。","respondent":"吉野戸籍住民課長","answer":"実際には前回の評価は令和２年ではあるのですけれども、今回の標準化システムは令和７年１月に開発をしなければいけませんので、それに合わせて少し前倒しで全体の評価をやっているという次第です。","id":"exchange-020"},{"speaker":"横山委員","kind":"質問","question":"５年に１回というものではなくて、令和２年に行ったばかりですけれども、そのような理解でよろしいですか。それとも、５年に１度やらなければいけない修正の見直しみたいなものを、そのどちらなのかというのがちょっと分からなかったのです。","respondent":"吉野戸籍住民課長","answer":"今回はシステムの改修があるので実施するということになります。ただ修正がある場合には、その都度実施することになります。","id":"exchange-021"},{"speaker":"横山委員","kind":"質問","question":"相談しながら、項目と修正項目を見直していただいている作業を、今進めていらっしゃるということなのでしょうか。準備中なのかもしれないのですけれども、概要はどのような形なのか、イメージを説明を求めました。","respondent":"吉野戸籍住民課長","answer":"そういったデータ項目がこう変わりましたとか、そういった内容が全て網羅されたような形になります。そういった意味でいきますと、全体の項目が出ているようなイメージになります。","id":"exchange-022"},{"speaker":"横山委員","kind":"質問","question":"例えばＡというところに書いてあるけれども、ガバメントクラウドを利用することになると、今度はＢという場所に変わりますみたいなイメージでよろしいか尋ねました。","respondent":"吉野戸籍住民課長","answer":"委員のご指摘のとおりでして、今回主な修正項目を３に記載しています。委員のご指摘のとおり、それがガバメントクラウドという、いわゆる政府のクラウドに移行するというようなイメージになります。","id":"exchange-023"},{"speaker":"あくつ委員","kind":"質問・要望","question":"私も今の横山委員のご質問を聞きながら、２０２０年１月２０日、お寄せいただきました意見・質問は残念ながら０件でございました。そこについては、質問はしませんけれども、しっかりと区民に対してできるだけ分かりやすい方法で意見を求めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"第三者点検の結果を報告して、個人情報保護委員会に評価書を提出して、それが返ってくる形になるのですか。そして評価書も含めてパブリックコメントもするということなのですけれども、それは全てが公開されるということでいいのか、伺います。","respondent":"吉野戸籍住民課長","answer":"２の評価内容の特定個人情報ファイルの概要の移転事項のところが、区の内部の税務課であったり、子育て応援課であったりします。特定個人情報保護評価の回答なのですけれども、問題ありませんというような回答をいただいてから、公表する形になります。","id":"exchange-025"},{"speaker":"石田（ち）副委員長","kind":"確認","question":"特定個人情報保護評価をするに当たってはパブリックコメントもやらなければならないというふうに入っているものなのですか。そこの確認と、もうちょっと分かりやすくできる工夫というのを区として検討しないのか、伺いたいと思います。","respondent":"吉野戸籍住民課長","answer":"今回なのですけれども、対象の人数によって、こういったパブリックコメントであったり、第三者点検というのが実施義務になっています。３０万人以上の場合はこういった第三者点検とパブリックコメントは実施しなければならないということが規定されております。","id":"exchange-026"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"なかなか分かりづらい部分でもありますけれども、本当に個人情報は大事な部分で、そしてそれが国のシステム標準化で変わっていくことになるので、そこは丁寧にしていただきたいなと私も要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"}]},{"id":"topic-03","title":"顔認証マイナンバーカードの開始","agenda":"顔認証マイナンバーカードの開始","exchanges":[{"speaker":"横山委員","kind":"確認","question":"１点だけ伺わせてください。どういう事例があるのかというのと、その場合の対策についてどのように考えられているのかというのを確認させてください。","respondent":"吉野戸籍住民課長","answer":"医療機関等で実際に使うときに、顔の写真を撮って、それと整合がつかないときがありまして、それでうまく読み取れないというような形になります。そういった方がもし健康保険証として利用される場合には、顔認証の場合には、券面の写真と住所を確認して目視での確認になります。","id":"exchange-028"},{"speaker":"横山委員","kind":"質問","question":"なるべく認識しやすいような写真を使っていただくとか、そういったご案内というのもしていただくといいのかなと思っているのですが、その辺りはいかがか尋ねました。","respondent":"吉野戸籍住民課長","answer":"そういったときでもやはり顔の目と鼻と口の部分が認識できればできるような形になっておりますけれども、そういったところも気をつけてくださいというアナウンスは、今後気をつけていきたいと考えています。","id":"exchange-029"},{"speaker":"あくつ委員","kind":"質問","question":"ちょっと前の８月の資料ですけれども、そんな仕組みで考えているということが書いてあったのですが、ここで言っている顔認証マイナンバーカードというのはそういう意味なのかどうか説明を求めました。","respondent":"吉野戸籍住民課長","answer":"今回のカードが実装する意味なのですけれども、病気や体が不自由な方、マイナンバーカードの暗証番号の管理がとても不安な方がいらっしゃるという声が上がりまして、そういったところを解消するために、顔認証マイナンバーカードが導入されたという経緯になっております。","id":"exchange-030"},{"speaker":"あくつ委員","kind":"意見","question":"１１月２７日と書いてあるから、現在持っているマイナンバーカードを持って行って、どのような手続きをすればそれが顔認証マイナンバーカードになるのかとの意見を述べました。","respondent":"吉野戸籍住民課長","answer":"先ほどの開始時期の、対応可能窓口のところで書かせていただいたのですけれども、顔認証カードの交付であったり、あと切替えのところです。その場でカードのほうは切替えを行いまして、カードの券面のところに顔認証というような印字をしますので、即日で手続きはできます。","id":"exchange-031"},{"speaker":"あくつ委員","kind":"質問","question":"印字をするということは分かったのですけれども、先ほど私が申し上げたような、いわゆる電子的なロックをかけるということではないということか尋ねました。","respondent":"吉野戸籍住民課長","answer":"電子証明書を使えなくするロックをかけます。","id":"exchange-032"},{"speaker":"あくつ委員","kind":"確認","question":"その手続きについては即日でできるし、簡易だということは今、確認させていただきました。今年、来年度を含めて、そういったこともご検討されているのか説明を求めました。","respondent":"吉野戸籍住民課長","answer":"高齢者施設であったり、障害者施設の方からも、暗証番号の管理がとても難しいというお声が上がった経緯もあると考えています。令和５年度は大分お手伝いいただきまして、もしお手伝いいただけるのであれば、今後も協力していきたいと考えている次第です。","id":"exchange-033"},{"speaker":"あくつ委員","kind":"確認","question":"それともう一点だけ確認です。こういったところについて周知ができているのかどうかというところを最後に確認させてください。","respondent":"吉野戸籍住民課長","answer":"委員ご指摘の疎明資料なのですけれども、出頭困難な方に対しましては、施設長であったり、ケアマネージャーの方に署名していただくと顔写真で代理申請、それから代理受領というのが可能ですので、そういったところは高齢者等の担当と連携を取りながらやっているところです。","id":"exchange-034"},{"speaker":"えのした委員","kind":"質問・要望","question":"ご説明、どうもありがとうあります。目視による顔確認、責任だったり、その辺は区独自で何か対策として考えていることなどがあればお聞かせいただきたいです。","respondent":"吉野戸籍住民課長","answer":"社会保険診療報酬支払基金という、そういったところでの読み取りの精度が悪かったり、そういったところは機器のメーカーによって多少あるようです。区として機器を提供するとか、そういった独自のものは、現在は考えておりません。","id":"exchange-035"},{"speaker":"えのした委員","kind":"確認","question":"窓口での目視の場合に、やはり人間がすることですから、ヒューマンエラーではないですけれども、違う方と見間違えるということは、そうないとは思うのですけれども、万が一のことを考えた場合に、区としてその辺は何か、１人だけで確認するのではなくて、２人で確認するとか、何かそういったことは。","respondent":"吉野戸籍住民課長","answer":"委員のご指摘のとおり、本人確認というのはとても大切なことですので、私どもの窓口では確かに１人ではなくて、数人で確認しております。医療機関のほうにもそういった呼びかけをしていきたいと考えています。","id":"exchange-036"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/753456?Template=document&Id=2976#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":24130,"voices":97}},{"id":"r05-20231128-7","meetingId":"r05-cm11","date":"2023年11月28日","dateIso":"2023-11-28","committee":"厚生委員会","time":"午前１０時０８分～午後 ３時２７分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を85件整理しています。","topics":[{"id":"topic-01","title":"を聴取したいと思います。 初めに、(1)「品川区障害者計画及び第７期品川区障害福祉計画・第３期障害児福祉計画（素案）」に係るパブリックコメントの実施","agenda":"を聴取したいと思います。 初めに、(1)「品川区障害者計画及び第７期品川区障害福祉計画・第３期障害児福祉計画（素案）」に係るパブリックコメントの実施","exchanges":[{"speaker":"おぎの委員","kind":"意見","question":"３月に、こちらの障害者計画等を作成するための報告書、こちらのほうをいただいたのですけれども、こちらの１７ページ。〔「計画策定のための基礎調査」と呼ぶ者あり〕との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"},{"speaker":"おぎの委員","kind":"質問","question":"障害者計画等策定のための基礎調査報告書。大丈夫か尋ねました。","respondent":"川崎障害者施策推進課長","answer":"アンケートのほうですね。","id":"exchange-002"},{"speaker":"おぎの委員","kind":"質問","question":"同じ報告書の１６６ページ、子どもの障害のところでも発達障害は６０.９％を占めておりまして、私の考え方がありまして。令和３年から始まっていますので、計画等もまた次期に盛り込んでいっていただけたらいいなと思いますが、いかがか尋ねました。","respondent":"川崎障害者施策推進課長","answer":"令和４年度に実施した基礎調査の報告、アンケートの結果になります。私どもも発達障害についても今後、どのような点で取り上げていくかというのは、検討させていただきたいと思います。","id":"exchange-003"},{"speaker":"おぎの委員","kind":"意見","question":"今回の素案の８２ページ、令和６年度以降が見込量で利用者数１、利用時間が８６時間となっております。〔居宅介護〕が１２.１％〔行動援護〕が１０.７％と１割台で高く」という評価も出ておりますけれど、これはニーズがあるのかなと思うのですがとの意見を述べました。","respondent":"川崎障害者施策推進課長","answer":"４年、５年と実績がゼロになっているというのは、利用実績がなかったということでゼロという記載になります。今後、令和６年度以降は、利用者１を見込んでいるという形で、記載となっております。","id":"exchange-004"},{"speaker":"おぎの委員","kind":"質問","question":"こちら、利用者１名を見込んで８６時間ということなのですが、８６時間確保できる準備等はできているのか尋ねました。","respondent":"松山障害者支援課長","answer":"この程度の時間数の見込みというのは、通常のサービス量から見込んだものですので、お一人利用されれば８６時間がほぼ目安だろうと。ただ、その方の状態によっては、時間数は異なるものと見込んでおります。","id":"exchange-005"},{"speaker":"おぎの委員","kind":"意見","question":"今までこういったことがなかったので、０時間であったと理解いたしました。そして、今後、今のところは希望の人数があまり多くないので、８６時間という準備でされているということで、承知いたしましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-006"},{"speaker":"ひがし委員","kind":"確認","question":"それとも、令和６年度に向けてサービスを提供できる見込みということなのか、というところは確認したいかなと思いました。いかがか尋ねました。","respondent":"松山障害者支援課長","answer":"障害者の方の場合、その方によって個別性がかなり異なってまいりますので、その方に応じて、必要なお時間を提供するというものです。令和６年度からということになっていますけれども、事業者との契約ということが整えば、この時間数は今年度であっても提供されるものです。","id":"exchange-007"},{"speaker":"ひがし委員","kind":"質問・要望","question":"希望されるときに使えるのかというところを確認したかったのかなと思いましたので、私も付け加えて質問させていただきました。素案だけでも１２０ページぐらいあり、それともそこで閲覧してコメントしてくださいという形なのか、その点について確認をしたいと思います。","respondent":"川崎障害者施策推進課長","answer":"ただ、やはりボリュームがありますので、配布も含めて検討はします。今のところ、別途説明会という予定はございません。","id":"exchange-008"},{"speaker":"ひがし委員","kind":"質問・要望","question":"ホームページに記載があったり、この間の一般質問でもありましたけれど、ぜひその点については検討してほしいと求めました。今はまだ検討していないということだったのですけれど、今後検討していただければいいなと思いますし、強く要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"鈴木委員","kind":"質問・要望","question":"切実な要求だけに、ぜひやっていただきたいと思うのですけれど、ご検討いただけないでしょうかというのが１点です。障害者団体の方もパブリックコメントが出せるような形になるといいかなと思ったのですけれど、そのヒアリングのやり方も説明を求めました。","respondent":"川崎障害者施策推進課長","answer":"１つ目の説明会について。３つ目の方法ですけれども、基礎調査の際にヒアリングをしたときと同様のスタイルで、実施することになります。","id":"exchange-010"},{"speaker":"鈴木委員","kind":"質問","question":"基礎調査の時のヒアリングの中身を、教えていただけないでしょうか。何というのですか、団体の中心の方にだけ集まっていただいて意見を聞くという感じなのか、そこら辺のやり方について説明を求めました。","respondent":"川崎障害者施策推進課長","answer":"主には団体の中心の方と、ヒアリングをするという形になるかと思います。","id":"exchange-011"},{"speaker":"鈴木委員","kind":"質問・要望","question":"だから１ページ抜けてしまったのかなと思ったのですけど。これがもし抜けたのであれば、追加していただいたほうがいいかなと思ったのが、１点です。","respondent":"川崎障害者施策推進課長","answer":"確認させていただいて、もしこちらが抜けていたら、早急に対応いたします。ありがとうございました。","id":"exchange-012"},{"speaker":"鈴木委員","kind":"質問・要望","question":"これに基づいて発達障害というのも取組が求められていると思うのですけれど、そういうのが発達障害の方は特に高いということが書かれています。それなのにこれまでよりも減ってしまう見込量で、３年間変わらないという見込量というのはなぜなのか、伺いたいと思います。","respondent":"川崎障害者施策推進課長","answer":"２つを比較して、将来サービスの見込量が多いほうを、採用しております。ただ、見込量としてはサービスの上限を定めるものではありませんので、そこは丁寧に進めていきたいと考えております。","id":"exchange-013"},{"speaker":"鈴木委員","kind":"質問・要望","question":"要望があれば受けていきますよということなのか、でも、そうしたら何のための見込量なのかということになってくるのではないかと思うので。そこのところはどう考えたらいいのか、もう１回お聞かせほしいと求めました。","respondent":"川崎障害者施策推進課長","answer":"先ほどもご説明したとおり、サービス利用実績というのはあくまでも見込みになります。サービスの見込量が多いほうを採用しておりますが、あくまでも見込みになりますので、その方に対しての対応というのはしていくことになります。","id":"exchange-014"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それはどういう形で具体化していくのかということで、放課後デイはそういう形で補助とか何か検討をされているのか、その点も伺いたいと思います。下がってしまって、放課後等デイサービスの確保と見込量、そこに対しての考え方についても伺いたいと思います。","respondent":"川崎障害者施策推進課長、松山障害者支援課長","answer":"確かに令和３年度以降、利用者数も増えておりまして、倍近くになっているような現状です。今、そちらの個別相談への対応も含めて民間の参入が結構ありますので、民間事業者への働きかけというのも積極的に行っていきたいと考えておりま… それぞれの事業所の質を上げるための仕組みを国が検討しておりまして、それに伴って報酬が変わる可能性が高いと考えております。","id":"exchange-015"},{"speaker":"鈴木委員","kind":"質問","question":"ぜひ、よろしくお願いしたいと思います。どのようなところがどういう形でされているのか、そういうものに区も関わって、その取組がどうなっているのかも伺いたいと思います。","respondent":"松山障害者支援課長","answer":"事業所連絡会についての状況について、お答え申し上げます。障害児者総合支援施設、その３者が協力をしまして、事業所連絡会というのを開催しています。","id":"exchange-016"},{"speaker":"鈴木委員","kind":"質問","question":"私も他区でいろいろ話を伺ったとき、お話を伺ったことがあるのですけれど、その点も伺いたいと思います。","respondent":"松山障害者支援課長","answer":"ご説明申し上げます。これから検討してまいります。","id":"exchange-017"},{"speaker":"やなぎさわ委員","kind":"意見","question":"３０ページの就労機会の拡充のところですが。令和５年から開始されていると思うのですけれど、どこでどういうふうに行っているか、情報をお知らせしてあげてほしいのですがとの意見を述べました。","respondent":"松山障害者支援課長","answer":"ご利用者の方はまだ現段階ではいらっしゃいませんが、来年度モデルを実施する予定です。来年度モデル実施の予定なので、いずれスタートアップしたときに、何かしらの目標は必要かなと考えております。","id":"exchange-018"},{"speaker":"やなぎさわ委員","kind":"質問","question":"ほかの委員の前の質問と重なるところがあるかもしれませんけれども、パブリックコメントの周知に関してなのですけれども。例えば区の旧ツイッターとか、そういったＳＮＳでの発信の予定というのは、特に今のところは検討中ということか尋ねました。","respondent":"川崎障害者施策推進課長","answer":"そこも含めて十分検討します。","id":"exchange-019"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"ご自身のツイッターなどでも発信していただけたら、より目に留まって関心が高まるのではないかと思うので、ぜひ前向きな検討をお願いいたします。先ほどご答弁で確認はできたのですけれども、どうしても数字だけ見ると、その辺は要望として伝えておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"鈴木委員","kind":"質問","question":"医療的ケア児のことで伺いたいのですけれど、同じこの計画の４３ページの、ｎが５４となっているのですよね。ケア児だけで５４人ということになるのではないかと思うのですけれど、この５４と３０の数というのはどう捉えたらいいのか、伺いたいと思います。","respondent":"川崎障害者施策推進課長","answer":"委員ご指摘の１９ページの３０人というのは、区として把握しているケア児の人数ということになります。４３ページ以降、これは病院に入院させている方もいらっしゃいますし、区としては把握し切れていない方の人数というのも含まれております。","id":"exchange-021"},{"speaker":"こしば副委員長","kind":"質問・要望","question":"恐らくホームページで、先ほどおぎの委員も提示されていましたけれども、ほかの委員は把握できていないところもあるので。１週間前とか２日前か、全員にそれはしっかり事務局と相談した上で、共有していただきたいと考えます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"鈴木委員","kind":"質問","question":"どう質問するかというのは、何というのですか、なかなかならないと思うのですよね。これまでも。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"鈴木委員","kind":"質問","question":"こういうもので、ということは、もう少し皆さんにも分かるような形で、質問の仕方にするようにしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"鈴木委員","kind":"質問・要望","question":"少なくとも５４人は医療的ケアの方がいらっしゃると、そういう捉え方でいいのかという確認を、お願いしたいと思います。それであれば、もう少し増やしていただきたいという思いがするのですけれど、その移動支援についての考え方についても伺いたいと思います。","respondent":"川崎障害者施策推進課長、松山障害者支援課長","answer":"医療的ケア者の人数というものが、今回基礎調査を通して、この人数の方がいらっしゃるということを把握することができました。今後も実態の把握には努めてまいりたいと思います。日常生活用具事業に関して変更点というのは、区のほうとしてはございませんので、引き続き必要な要望に関しては支援をしていく予定です。","id":"exchange-025"},{"speaker":"鈴木委員","kind":"質問","question":"そうすると、全体的にサービス見込量というのはこれから３年間、今までより少なくなると、何となく希望があまり持てないような気がしてしまうのですけれど、これから検討して、この数字は変わり得るということはあるのか尋ねました。","respondent":"松山障害者支援課長","answer":"ただ、やはりコロナがありまして、実際に見込量を、令和２年、３年と下回ってしまった事業、サービスもあります。そこから実態というのを把握して、見込量の推計については実際には２パターン出しながら、比較して高いほうをこちらでは取ったというものになります。","id":"exchange-026"},{"speaker":"鈴木委員","kind":"質問","question":"これはどういうときに招集されるのか、そういうのもなかなかこの中では見えてこなかったので、その点を伺いたいと思います。もう１つありますけれど、それは誘致も含めて区内に１００人分増やすということで捉えていいのか、その点も伺いたいと思います。","respondent":"松山障害者支援課長、川崎障害者施策推進課長","answer":"それから、１１８ページの虐待防止・権利擁護の促進というところで、２つ目の枠です。確かに委員おっしゃるように２.６％になっておりますが、それは人事課所管のものですので、数字としては把握しているものではございません。令和３年度末の障害者グループホーム定員数を基準として、令和８年度末までに合計１００人分の定員増を目標としますと、記載させていただきました。","id":"exchange-027"},{"speaker":"鈴木委員","kind":"質問・要望","question":"いろいろありがとうございました。ぜひ、障害者の皆さんからご意見を伺っていただきながら、本当に障害者福祉が前進するような形で取組を進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"筒井委員","kind":"確認","question":"確認なのですけれど、素案の８ページの第２章、タイトルは「障害児者の現状」と書いているのですけれど、書いてあることは障害児に限らず、成人の障害者のことにも触れているのですけれど、なぜタイトルが障害児者にしてあるのか、伺いたいと思います。","respondent":"川崎障害者施策推進課長","answer":"こちらの障害児者の現状は、こちらの棒グラフを見ていただくと分かりますとおり、年齢別にも分かれておりますので、障害児、障害者、大人と子どもの推計というものが載っている形ですので、現状把握として掲載しております。","id":"exchange-029"},{"speaker":"筒井委員","kind":"質問","question":"あえて障害児者をクローズアップしたいから、この書き方にしたということでよろしいか尋ねました。","respondent":"川崎障害者施策推進課長","answer":"今回、障害者計画という、障害者の基本計画に当たる部分の策定となりますので、障害者全般に関わる部分になりますので、このように障害児者を取り上げているということになります。","id":"exchange-030"},{"speaker":"筒井委員","kind":"質問","question":"そうしたとき、このひきこもりという用語は、入れないのでしょうか。ひきこもりについて、どうお考えなのか伺いたいと思います。","respondent":"松山障害者支援課長","answer":"実際の支援の中ではもちろん、具体的な事例検討の中では、計画のところと実際の対応では差があるものです。ですが、委員のご意見につきましては参考とします。","id":"exchange-031"},{"speaker":"おぎの委員","kind":"意見","question":"すみません、最後に１点だけ、災害のところだけお聞かせください。２７ページの人工呼吸器使用者の、自家発電装置というのを令和４年度から追加して入っているのですけれども、支給した実績等はありますかとの意見を述べました。","respondent":"松山障害者支援課長","answer":"在宅人工呼吸器の方への自家発電装置につきましては、令和４年度には１件ございまして、５年度につきましては、少しずつ広がっているところです。数件以上は支給した実績があります。","id":"exchange-032"},{"speaker":"おぎの委員","kind":"質問・要望","question":"告知のほうも進めてほしいと求めました。実際に災害が起きたときというのは、人工呼吸器の方が自己避難する場所というのは、どちらを想定されているのか尋ねました。","respondent":"松山障害者支援課長","answer":"それぞれの個々人によって、災害時の避難計画というのはご本人やご家族と相談しながら作っていくものです。人工呼吸器の方は、移動にリスクも伴いますので、在宅をご希望されている方が多い状況です。","id":"exchange-033"}]},{"id":"topic-02","title":"戸越四丁目区有地の今後の活用","agenda":"戸越四丁目区有地の今後の活用","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"定員が何人くらいになる見込みなのか伺いたいのと、それから、そこのところもお聞かせほしいと求めました。そこら辺はどういう、対象の障害種別も含めて、どのようなグループホームになるのかも伺いたいと思います。","respondent":"川崎障害者施策推進課長","answer":"人数についてですけれども、現在の想定では２ユニット、定員１０名を考えております。こちらの運営につきましては、資料の米印にありますとおり、選定事業者にて実施予定ということで、民設民営で選定を行っていくことになります。","id":"exchange-034"},{"speaker":"鈴木委員","kind":"質問","question":"どういう形で公募をされるのか、応募していただけるような公募の仕方はどう考えられているのか、も伺いたいと思います。ほかにもこういう土地というのは可能性として、検討できるような場所があるのか、その点についても伺いたいと思います。","respondent":"川崎障害者施策推進課長","answer":"公募は令和６年度になるのですけれども、具体的な運営方法等の中身については、これからの検討になります。今後の区有地の考え方ですけれども、検討を進めていくことになりますので、連携する企画課含めて検討していくことになります。","id":"exchange-035"},{"speaker":"鈴木委員","kind":"質問","question":"見つけなくてもあるのかもしれないですけれど、そこら辺の可能性はほかにもまだあると考えていいのか、その点だけ伺います。","respondent":"川崎障害者施策推進課長","answer":"今後は、先ほども申し上げましたとおり、区全体の行政需要を考慮していくということになります。土地を所有しているオーナー様への働きかけというのも十分検討しながら、実際に今年度、個別相談会というのも実施させていただきましたので。","id":"exchange-036"},{"speaker":"鈴木委員","kind":"確認","question":"ということは、民有地を品川区が取得して、それで区有地として貸出して、定期借地みたいな形でする、そういうことも考えているということですか。それとも、そうではなくて自分の土地を使って自分で建ててくださいよと、そういうことだけなのか、そのことだけ確認をお願いします。","respondent":"川崎障害者施策推進課長","answer":"現在は、障害当事者のご家族の方で土地をお持ちの方に向けた相談会ということで、具体的な話が進んでいるということになっております。","id":"exchange-037"},{"speaker":"やなぎさわ委員","kind":"確認","question":"改めて確認なのですけれど、運営主体は民営になるのか、区でやるかというのは、まだ決まってないということですね。","respondent":"川崎障害者施策推進課長","answer":"民間事業者にて実施をすることになります。","id":"exchange-038"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"１社だけとか。そういったことを考えて、持続性があるものを考えていただきたいなと思いますので、要望ということでお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"ひがし委員","kind":"質問","question":"品川区で、１０月２５日にホームページを見ると最終更新されていて、その時もう既に申込者多数につき受付終了というふうに書いてあって。２日間ぐらいで予約多数だったのかなと考えると、参加された方々の人数はどのぐらいだったのか聞けたらと思うのですが、いかがか尋ねました。","respondent":"川崎障害者施策推進課長","answer":"こちらの相談会は、５組の方を対象に予約制で行いました。開始から１時間で埋まってしまいまして、１０月２５日にはホームページのほうで予約受付は終了しましたというふうに掲載しています。","id":"exchange-040"},{"speaker":"ひがし委員","kind":"質問・要望","question":"今回の場合に当てはまるかどうかはあれですけれど、今回は５組ということでしたけれど、その方々の力をぜひ活用できればと思うのです。今回申込みが多かったということを踏まえると、今後も開催はぜひ検討していただきたいと思うのですが、その点について、検討状況を説明を求めました。","respondent":"川崎障害者施策推進課長","answer":"私どもも今回は試験的に初めて行いまして、そこについては開設したい方々がいらっしゃるのだという実態をつかむことができました。今後も、この件については前向きに検討していきたいと考えております。","id":"exchange-041"},{"speaker":"鈴木委員","kind":"質問","question":"５組来られたというのは、品川区の補助金が受けられますよということも含めた相談会ということなのでしょうか。これまで品川区は補助金を大幅アップして、品川区の補助金を活用された事業所というのは何件ぐらい今まであったのか、その件数も説明を求めました。","respondent":"川崎障害者施策推進課長","answer":"どうやったら開設できるのかという基本的な知識がまだない方が多いというのが事実ですので、そこも含めて補助金のご案内というのはしています。今まで公的補助を使った事業者ですけれども、グループホーム金子山と、令和４年度の民間でのグループホームの運営者と、今、２件です。","id":"exchange-042"},{"speaker":"鈴木委員","kind":"意見","question":"２件しか使われてないという、それなのに補助金が使われていない理由というのは、どのようなものがあるのか説明を求めました。","respondent":"川崎障害者施策推進課長","answer":"そのタイミングも含めて、品川区の整備費補助のタイミングとずれてしまうということも、１つあります。自己資金などで建てられるという方もいらっしゃる、それは事実です。","id":"exchange-043"},{"speaker":"やなぎさわ委員","kind":"質問","question":"今の質問に追加でお伺いしたいのですけれど、手持ちの資金でやるというのは、例えば補助金を受けると何か制約ができてしまうから、あえて自分たちの自己資金でやるという、そういう事務所が多いというか、いるということか尋ねました。","respondent":"川崎障害者施策推進課長","answer":"区の補助金を使うということは、東京都の申請もありますので、手続に時間がかかるというのもあります。早急に建てたいという方、そこで２段階の申請を早めて建てたいという方は、ご自身の蓄えで作られるという方もいらっしゃいます。","id":"exchange-044"},{"speaker":"やなぎさわ委員","kind":"質問","question":"では、私が今お伺いした、いろいろ条件が出てしまうとかいうことではなく、スピード感という方が多いということで、よろしいか尋ねました。","respondent":"川崎障害者施策推進課長","answer":"そのとおりです。","id":"exchange-045"}]},{"id":"topic-03","title":"「第九期品川区介護保険事業計画概要（案）」に係るパブリックコメントの実施","agenda":"「第九期品川区介護保険事業計画概要（案）」に係るパブリックコメントの実施","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"様々要望があると思いますので、要望を聞く機会としても、説明会をぜひ持ってほしいと求めました。その点、いかがか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"区では今までも、パブリックコメントを通して広くご意見をいただくというところもありますので、説明会の実施しておりません。例えば大田区が１２月に２回ほど予定をしている、説明会を実施する区もあれば、説明会を実施していないだろうという区もあるというところなので。","id":"exchange-046"},{"speaker":"鈴木委員","kind":"質問・要望","question":"前回調べたときには、近隣区どこでもやっていると思ったのですが、そこら辺のところはつかまれていないでしょうか。説明会はぜひやっていただきたいと思うのですが、ちなみに３年前のパブリックコメントは何件ぐらい来たか、それも分かったら説明を求めました。","respondent":"菅野高齢者福祉課長","answer":"説明会、説明会については、実施していないのかなというところです。１２月１日よりパブリックコメントが公開予定なのですが、説明会については不明で、こちらでは捉えておりません。","id":"exchange-047"},{"speaker":"鈴木委員","kind":"質問・要望","question":"６件というのは、８万１,０００人からの高齢者で、区の捉え方はいかがでしょうか。皆さんからご要望を伺う場としても、知らせてご意見を伺う場としても、改めてお願いします。","respondent":"菅野高齢者福祉課長","answer":"６,１００円は高い、在宅介護支援センターを人員的に強化して、区としては丁寧な回答に努めているところです。この中でも審議しているということと、あとは今回のパブリックコメントも実施するというところで、今のところ説明会の予定はないとお答えします。","id":"exchange-048"},{"speaker":"鈴木委員","kind":"質問・要望","question":"こういう大きな計画、３年に１回ですから、説明会をやっていただきたいということで強く要望をしておきたいと思います。続いてその下の（３）ですが、それはなぜ有料老人ホームを誘導するのか、その点を伺いたいと思います。","respondent":"菅野高齢者福祉課長","answer":"第九期においては２か所の整備というところについては、八潮南特別養護老人ホームの令和８年度に増築分が開設予定で、ここの部分が約５０床です。","id":"exchange-049"},{"speaker":"鈴木委員","kind":"質問","question":"私は、有料老人ホームというのは要支援から入れますし、片や特別養護老人ホームは要介護３以上でないと入れない。有料老人ホームを誘導するというよりも、自治体の方針としてはすべきではないかなと思うのですが、その点の考え方も伺いたいと思います。","respondent":"菅野高齢者福祉課長","answer":"特定施設、有料老人ホームにつきましては、やはり定員の４割ぐらいの方が区民の方ということでご入居いただいているという実態もあります。必ずしも皆さん、そのあたりを的確に捉えながら、今後も有料老人ホームの誘致などについては検討していきたいと思っているところです。","id":"exchange-050"},{"speaker":"鈴木委員","kind":"質問・要望","question":"７年とかかっていますので、３施設の後の特別養護老人ホームの計画をぜひとも立てていただきたいと思うのですが、そういう点も伺いたいと思います。プラス１１６人ということになるのですが、ここまでにはさすがに１か所さらに増設するという考えなのか、その点も伺いたいと思います。","respondent":"菅野高齢者福祉課長","answer":"区内でも２か所ありますけれども、ほかのところとも地域のバランスなども考えながら、検討していかなくてはいけないと思っているところです。こちら、区においては介護医療院に転換する施設はないと認識しております。","id":"exchange-051"},{"speaker":"鈴木委員","kind":"質問・要望","question":"２０４０年のところまでにはプラス１１６人となってはいるものの、何というのですか、その点は確認をさせてほしいと求めました。仕組みとして少し教えていただきたいのが、２０か所で幾らぐらい在宅介護支援センターに委託料が出ているのか、その点を伺います。","respondent":"菅野高齢者福祉課長","answer":"１点目の、老人保健施設の今後の整備計画というところですが、こちら、区としては今のところ明確な予定はございません。在宅介護支援センターと区が共に、そういったケアプランなどについて、介護予防のフォローなどについてできるような仕組みとなっております。","id":"exchange-052"},{"speaker":"鈴木委員","kind":"質問・要望","question":"どこから来ているのかということを伺いたいと思います。ここのところというのは（２）番でも、九期に向けての介護職員の待遇改善というところに対してはどう考えられているのかも、伺いたいと思います。","respondent":"菅野高齢者福祉課長","answer":"１点目の在宅介護支援センターの介護報酬以外の部分についてお答えします。現在、国のほうで１２月末をめどに介護報酬などについての決定がなされるというところも、区としては対応していきたいと思っておるところです。","id":"exchange-053"},{"speaker":"鈴木委員","kind":"質問・要望","question":"前に処遇改善交付金という形で国から出されたことがありましたので、そういう形もぜひ区からも求めてほしいと求めました。取りあえず、では一旦。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"},{"speaker":"ひがし委員","kind":"質問","question":"私もこの１３ページのプロジェク７の「介護・福祉職員の確保・育成と介護現場の生産性の向上」について質問します。高齢化が進む中で介護職員の人材確保に力を入れてほしいという内容で、「品川区は介護士が不足しているのですか」という趣旨の質問に対して、今回。","respondent":"菅野高齢者福祉課長","answer":"区内においては、そういった事態までには今のところ陥っていないと、そういうところは共通していると認識しているところです。今回、計画をつくるに当たっては、少しそういった現実を捉えた形で表現させていただきました。","id":"exchange-055"},{"speaker":"ひがし委員","kind":"質問・要望","question":"今まで、足りないというところが顕在化したと、また課題として認識しているという文言に変わったのかなと理解させていただきました。何か支援の方法を模索していくべきかなと思いますので、その点については要望にはなるのですけれども、引き続き取り組んでいければなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-056"},{"speaker":"やなぎさわ委員","kind":"質問","question":"そこで区民の方の意見も吸い上げているよと、多分そういったことなのかなと思ったのですけれども、この公募の区民の方というのは５名ですかね。何か応募基準というか、どういった形で公募されたのか、詳しくお聞かせほしいと求めました。","respondent":"菅野高齢者福祉課長","answer":"３年に１期というところで事業計画は改定しておりますので、その３年ごとに委員も募集をさせていただいて、４名の方を選ばせていただいております。広く区民の声という意味では、区民の声も吸い上げられるのかなというところで、今日も報告をさせていただいている次第です。","id":"exchange-057"},{"speaker":"やなぎさわ委員","kind":"質問","question":"分かりました。当然、介護事業所も大きく関わってくるお話かなと思うのですが、介護事業所というのはその委員会の中に何名ほど入られているのか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"事業者代表として社会福祉法人の理事の方、あとはホームヘルスなどの会社をやっていますＮＰＯ法人を運営している方の理事の方２名、現場の声としては２名の方が具体的には委員として入っていただいております。","id":"exchange-058"},{"speaker":"やなぎさわ委員","kind":"質問","question":"全体の数でいったらもう少し多くてもいいのかなという感想を思います。少し話が戻ってしまうのですが、公募の区民の方はたしか６５歳以上とか以下で区切られているというのは、何か理由はあるのか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"特に、そのあたり、何名という縛りはございませんので、毎年４名というところで選ばせてもらっています。ちなみに第１号被保険者というのは、６５歳以上ということになります。","id":"exchange-059"},{"speaker":"やなぎさわ委員","kind":"質問","question":"平日の午後ですから、そういった幅を広げることによって、広く区民の方がそういった公募に応募しやすいのかなと思うのです。そういった取組とかはいかがか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"その理由としては、医師会の先生たちなどが、水曜日の午後というところもあります。全体の委員の構成を考えたときに、様々検討しなくてはいけないところもありますので、委員の構成については考えていきたいと思っているところです。","id":"exchange-060"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"私も決算特別委員会で同じような質問をさせていただいたし、ここの委員会でも質問して、私も少し安心しております。これは一般質問でおぎの委員も質問されていたのですが、これも変わらず積極的に採用支援は行っていくような取組の理解でよろしいか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"きちんと定着してもらうような支援をまずは事業者、そこについて難しい部分があれば、区で支援をしていきたいと捉えております。そういった連携、情報共有を進めていって、区としても支援をしていきたいと思っているところです。","id":"exchange-061"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"どうしても人材派遣とか紹介会社とかにすごいお金がかかってしまって、あくまで要望ですが、そういったことも個人的にはあるとよいなと思います。現場からの声です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-062"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そういうふうに地域には１か所もないわけですから、地域包括支援センターが地域に設置されていないというのはほかの自治体ではないですから。地域包括に変わることができるわけですから、地域包括支援センターということで切り替えていただきたいと思うのですが、その点いかがか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"何よりも２０か所の各在宅介護支援センターと高齢者福祉課、迅速かつ適切な対応が可能となっておりますので、そういったいい部分もたくさんあります。","id":"exchange-063"},{"speaker":"鈴木委員","kind":"質問・要望","question":"少し伺いたいのは、一般質問でも伺ったのですが、今年度末には４億円になりますよということだったのです。少しそこら辺の見通しというのはどうなっているのかということを１点伺いたいのと、それから、その期ごとに随分変わってきたと思うのです。","respondent":"菅野高齢者福祉課長","answer":"６,５００円から７,０００円の間に何とか介護保険料を少しでも安くお示しできればなというところで、今、検討をしているところです。２０４０年を見ると、今まさに検討しているところですので、そのあたりはまた決まりましたら皆様にご報告したいと思っているところです。","id":"exchange-064"},{"speaker":"鈴木委員","kind":"質問","question":"６５歳以上の方の保険料そのものなので、保険料の引下げで６５歳以上の人に返していくという考え方でやるべきだと思いますし、その点。先ほど伺った市町村特別給付のことも、ご答弁をお願いしたいと思います。","respondent":"菅野高齢者福祉課長","answer":"市町村特別給付のことについてのご質問に答弁漏れがありましたので、改めてご説明をします。例えば要支援者夜間対応サービスや通院等外出介助サービス、そして、適切なサービスの提供に努めてまいりたいと考えています。","id":"exchange-065"},{"speaker":"鈴木委員","kind":"質問・要望","question":"本当に介護保険が始まったところからすると約２倍になるわけですから、保険料を引き上げる、ぜひ一般財源に変えてほしいと求めました。国の負担の割合というのが２０％は必ず各自治体に来ますが、国の調整交付金の５％は、伺いたいと思います。","respondent":"菅野高齢者福祉課長","answer":"ちなみに区では大体３.５％から３.７％前後で近年推移しております。こちらにつきましては、全国の市町村会議等におきまして、５％一律でというところは毎年要求しているところです。","id":"exchange-066"},{"speaker":"鈴木委員","kind":"質問・要望","question":"応能負担というところでしていただきたいと思うのですが、今の段階での品川区の考えを伺えたらと思います。１.６倍ぐらいに増えているので、ここのところは、ぜひさらなる応能負担の多段階化を求めたいと思います。","respondent":"菅野高齢者福祉課長","answer":"区としては１４段階で、そこについての見直しも含めて、今検討を図っているところです。現在の第１４段階の方の人数ですけれども、１,０１３人、実績としてはありますので、少し減っている状態になっています。","id":"exchange-067"},{"speaker":"鈴木委員","kind":"質問・要望","question":"私は渋谷区の保険料の決め方というのをぜひ参考にしていただきたいなと思ったのが、この段階のところにさらに０.８を掛けて８割にしているのです。これは他区の状況も見ながら、ぜひ多段階化、応能負担を進めていただきたいと要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-068"},{"speaker":"おぎの委員","kind":"質問・要望","question":"要望というか意見なのですが、２０１１年の震災の直前まで台湾におりまして、早くから介護に関して外国人人材の導入に踏み切っておりました。足りない分はどうしてもお願いする部分も出てくると思いますけれども、なるべく国内で、品川区内で採用に尽力していただけたらいいなと思いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-069"}]},{"id":"topic-04","title":"後期高齢者医療制度令和６・７年度保険料率の改定","agenda":"後期高齢者医療制度令和６・７年度保険料率の改定","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"何点か伺いたいのですが、一番左側の（６）の剰余金ですが、剰余金の分だけは保険料の算定の中に入れて安くなるという考え方でいいのでしょうか。一番上の赤い字の年額で１１万３,７７４円、今までと比べたら８,９３２円、年間増えることになるということで確認させていただいてよいか尋ねました。","respondent":"池田国保医療年金課長","answer":"前回、今、令和６・７年度については２５０億円を見込んだということになっています。１点、前回の部分は８.７２％から９.４９％ということに所得割が上がっておりますので、実際には前回のほうが多く上がっているかと思われます。","id":"exchange-070"},{"speaker":"鈴木委員","kind":"質問","question":"何かこの８,９３２円というのは、この８０万円とか、そういうことはないか尋ねました。","respondent":"池田国保医療年金課長","answer":"私たちは率でお話しをさせていただいたところで、率としては、令和４・５年の保険料を決める際が一番高く上がっているところではあります。すみません、座らせてください。","id":"exchange-071"}]},{"id":"topic-05","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"こしば副委員長","kind":"質問","question":"そういった少しの変化に気づけるようなチェックリストというのを設けていまして、それがなかなかより具体的に書かれていまして、そういったものを品川区で取り組まれているのかどうかも踏まえて教えてもらえますか。","respondent":"坂野保健予防課長","answer":"「夜、眠れていますか」というのはチェックのポイントとして非常によく使うことでございまして、ゲートキーパー研修でも私がよく受講生にお話しする。","id":"exchange-072"},{"speaker":"おぎの委員","kind":"質問","question":"こちらの心の健康相談訪問事業のところですが、電話相談の件数が思ったよりすごく多いなというのがありまして、この電話を受けている職員の方というのは大体何人ぐらいで、１回の通話はどれくらいお話しされているのか尋ねました。","respondent":"榎本荏原保健センター所長","answer":"それから精神保健相談員という者がおりますが、その職種が中心になって、こころの健康相談のときは対応しております。連絡のやり取りということですと１０分、２０分とか、そういったときはそれほど長くかかっているわけではないです。","id":"exchange-073"},{"speaker":"おぎの委員","kind":"意見","question":"予想していたよりも非常に多い件数で、驚いています。顔が見えない相手にでもお話を本当に聞いてほしいとか、本当に丁寧に当たっていただいているのだなというのが分かりましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-074"},{"speaker":"ひがし委員","kind":"質問・要望","question":"様々ご説明、ありがとうございました。統一感的なところを考えると、そういうところは検討とかされているのかという状況について、お聞かせほしいと求めました。","respondent":"坂野保健予防課長","answer":"実は自殺対策で作っているカレンダーには、シナモロールですか、あれを使っております。ただ、キャラクターの権利の関係があって、なかなかほかに横展開ができていない部分があるので、また何かありましたら勉強していきたいなと思います。","id":"exchange-075"},{"speaker":"ひがし委員","kind":"意見","question":"ほかのところを見ると、こころの電話帳とか対策のマニュアルとかには載ってこないので、統一感としてはやはり何か１個あるといいのかなと。これは意見として述べておきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-076"},{"speaker":"鈴木委員","kind":"質問","question":"しかもかなり深刻で複雑という方も多いと思うのですが、このメンタルチームサポート事業にどういう形でつながっていくのか伺いたいと思います。その中身についてもう少し説明を求めました。","respondent":"榎本荏原保健センター所長","answer":"今までのこの事業で支援者総数、最低１年ぐらいは支援する形になっていますので、令和４年末で１２５人ほど支援をしております。その後、必要な方が連携して支援していくという体制になっていますので、これからの安心した生活をしていくために必要な支援体制を組みながら。","id":"exchange-077"},{"speaker":"鈴木委員","kind":"質問","question":"何というのですか、本来であれば医療機関につながってほしいなと思いながらもなかなか医療機関につながらなくて、そこら辺のところも伺いたいと思います。","respondent":"榎本荏原保健センター所長","answer":"多職種の連携の在り方です。連携のところをご説明いたしましたけれども、まずこの方をどうやって支援していこうというところを検討して、そういった導入会議を開いて。","id":"exchange-078"},{"speaker":"鈴木委員","kind":"質問","question":"こういう事業にのったとしてもなかなか難しいのでのらないのかどうなのか、すごく、考えていけばいいのでしょうかねというところです。私も「たいむ」に相談に行って教えていただいて、何というのですか、そこら辺のところは保健センターとしてはいかがか尋ねました。","respondent":"榎本荏原保健センター所長","answer":"やはり非常に難しい、なかなか一人単独では支援ができないということで、こういった方々の支援を多職種でやっているという状況です。それから、精神疾患への対応に非常に慣れていらっしゃるというのもありますし、かなり密に連携して支援をしているという状況があります。","id":"exchange-079"},{"speaker":"鈴木委員","kind":"質問・要望","question":"何というのですかね、こういう事業があるよというところもぜひ周知もしてほしいと求めましたし、今後ともぜひよろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-080"},{"speaker":"筒井委員","kind":"質問","question":"３０代、４０代の方が増えているということで、このＮＰＯ法人ＯＶＡに費用を払って業務委託してやっているということでよろしいのですか。それともほかに何かあるのであれば、説明を求めました。","respondent":"坂野保健予防課長","answer":"今、お話があったように、インターネットゲートキーパー事業はＮＰＯ法人のＯＶＡに区が委託をして行っています。これはもう継続的な支援がこの先必要だからと、区のほうに戻ってくるようなケースも何例かあります。","id":"exchange-081"},{"speaker":"筒井委員","kind":"質問","question":"２ページ目の相談訪問事業、あなた躁うつ病ですとか精神疾患ですとか、そういう診断に至らなかったというケースもあるということですか。やはりどうしても絞られていくか、具体的な診断に至るケースというのは、どうしても数字的には少なくなるということでよろしいのか尋ねました。","respondent":"榎本荏原保健センター所長","answer":"参考資料のほうのこころの健康相談の件数と、一番下のところの専門医による相談のところ。","id":"exchange-082"},{"speaker":"筒井委員","kind":"質問","question":"相談を受けて、その方がお話を聞いていただけたということでご納得されて、それで終わるというケースもあるのか尋ねました。","respondent":"榎本荏原保健センター所長","answer":"自分が少し沈みがちになってしまうという部分のときには、幾つかご様子をお聞きして、医療機関お伝えして終わるという場合もあります。そういった１回とか２回ぐらい、もうかなり、何年という形でご支援している方もいらっしゃいます。","id":"exchange-083"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"特に効果が出ているなみたいな、そういった実感がもしあるようなものがあればお教えてしてほしいと求めましたが、いかがでしょう。","respondent":"坂野保健予防課長","answer":"件数掛ける深さというのが、例えば未遂者支援対策などは、実際にコミットする件数がそんなに多くはないですね。逆に、ただ広い範囲に効いているということで、これがすごく効いているというのはなかなか挙げられない感じかなと思います。","id":"exchange-084"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"行政視察で大阪の八尾市で自殺対策ということで伺ったのですけれども、１,０００だか２,０００だか……、２,０００件全部……。恐らく令和８年には、この自殺率１１.５というすばらしい目標が達成できるのではないかなと考えていますので、要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-085"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/651938?Template=document&Id=3678#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":70409,"voices":236}},{"id":"r05-20231128-8","meetingId":"r05-cm11","date":"2023年11月28日","dateIso":"2023-11-28","committee":"建設委員会","time":"午前１０時０８分～午後 ０時０８分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を36件整理しています。","topics":[{"id":"topic-01","title":"令和６年１月区営住宅入居者募集","agenda":"令和６年１月区営住宅入居者募集","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"最近の応募状況を伺いたいのと、いつも配布期間と申込み期間がずれているのですけれども、その理由を伺いたいと思います。それで、区営住宅の中で結構空き室があるという話も伺うのですが、今、空き室が何戸あるのか伺います。","respondent":"竹田住宅課長","answer":"令和５年７月に実施しました募集では、全体で５０.７倍、令和５年１月実施が４２.２倍、令和４年７月が４７.０倍となっております。それから、空き室数ですが、申し訳ございません、今、手元にないのですが、募集が年に２回ということで、一定数の空き室はあるところです。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問","question":"応募倍率が直近で言うと５０倍になっていると。そうすると、空き室のところは半年間ずつ、空いたところは全て募集をかけているという捉えでよろしいのか尋ねました。","respondent":"竹田住宅課長","answer":"相続人の方にお引取りをお願いするのですけれども、それをなかなかしていただけない等々の理由がございまして、必ずしも空いたものが次回の募集にはかけられていないという現状もあります。","id":"exchange-002"},{"speaker":"のだて委員","kind":"質問・要望","question":"早く入れるようにしてほしいと求めましたし、この倍率を見れば、区営住宅の増設こそ進めていくべきだと思います。受付期間が今回１月２９日ということで、応募する方も、できれば受付期間まで配布をしていただきたいということを要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"西本委員","kind":"質問","question":"要は、空いたから募集という話ではないのですか。９戸というのは完全に空いているということなのか、９戸というのが空き室と理解していいのか、いかがか尋ねました。","respondent":"竹田住宅課長","answer":"今日現在空いているのが９戸なのかというご質問ですけれども、退去されて、原状回復まで全て終わったものを募集にかけております。原状回復が終わっていませんので、１月に入居されるまでに原状回復が終わらない可能性もありますので、次回送りにしているというところがあります。","id":"exchange-004"},{"speaker":"西本委員","kind":"質問","question":"分かりました。ここの募集住宅数には入っていないけれども、入れそうだという場合には、それも加えた形の募集という意味合いでよろしいのか尋ねました。","respondent":"竹田住宅課長","answer":"お部屋は退去されても、なかなかすぐに原状回復工事がかけられない場合もあります。今回の９戸よりももっと多い数が空いているのですけれども、なかなか今回の募集にはご用意できなかった空き室もあるというのが現状です。","id":"exchange-005"},{"speaker":"西本委員","kind":"質問","question":"お聞きしたかったのは、例えば１戸でも２戸でも可能だったら、それに加えられるわけではないですか。そういう意味合いでいいのか尋ねました。","respondent":"竹田住宅課長","answer":"今回の募集につきましては、９戸でやらせていただきたいと考えております。そういうことはできませんとか、原状回復ができてお部屋ができるものについては、募集にかけていきたいと考えております。","id":"exchange-006"},{"speaker":"西本委員","kind":"質問","question":"そうすると、１戸とか２戸増えれば、競争率が下がるではないですか。その間に１戸でも２戸でも入れる可能性があるのだったら、それも加えていきますということでの理解でよろしいか尋ねました。","respondent":"中村都市環境部長","answer":"入居できるところは、可能な限り入居していただきたいというところです。１戸２戸増えるかどうかというのは分かりませんが、考え方としましては、可能な限り入っていただくといった考えで運営しております。","id":"exchange-007"}]},{"id":"topic-02","title":"しながわ水族館リニューアル整備運営準備事業事業者の選定結果","agenda":"しながわ水族館リニューアル整備運営準備事業事業者の選定結果","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"運営準備事業者というのがどういうものなのか、運営事業者となるのか、そこのところを伺いたいと思います。今回、公募して１者しか来なかったということで、区としてはこのことをどのように捉えているのか、伺います。","respondent":"高梨公園課長","answer":"なお、東海先生につきましては、令和２年度に実施したしながわ水族館顧客満足度満点プロジェクトということで。議会の承認等をいただきながら選定をしていく予定ですが、区が進めたい方向性であったり、今回選定をさせていただいたところです。","id":"exchange-008"},{"speaker":"のだて委員","kind":"提案","question":"今回の提案が、もう少し詳しく説明できたら、してほしいと求めました。今回、それも含めて附帯意見をつけたということで、その附帯意見は、検討していく分についてのことなのかどうかも併せて伺いますとの意見を述べました。","respondent":"高梨公園課長","answer":"得点率６７％の評価といったところですが、考え方に沿ったものであるといったところと、考えているところです。附帯意見の考え方につきまして、それと基本設計のみならず、その先に続く実施設計等についても費用の提案をいただいているところです。","id":"exchange-009"},{"speaker":"西本委員","kind":"提案","question":"ここは１００％、意欲を持ってやっていくという気持ちが欲しかったとは思うのですが、その辺の現状はどうなのでしょうか。イルカのショーはいつまでやられるのかというのをもう一度確認したいし、何か提案があったのかというのをお聞きしたいと思いますとの意見を述べました。","respondent":"高梨公園課長","answer":"提案説明・ヒアリングでの事業者の受け答えの部分で、配点をしていただいたところ、採点をしていただいた部分であると考えています。","id":"exchange-010"},{"speaker":"西本委員","kind":"質問・要望","question":"それを大々的に紹介するとか、１代２代にわたって、その思いを思い出させるような感謝デーのイベントができるようにお願いしたい。一緒に考えてほしいと求めましたので、いい水族館を継続していただくように強くお願いしたいという思いで、終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"田中委員","kind":"質問・要望","question":"重複を避けながらお伺いしたいと思いますが、それに対してを求めたのか、まずはそこをお聞かせほしいと求めました。","respondent":"高梨公園課長","answer":"今回、しながわ水族館がリニューアルのプロポーザルをやっているといった情報は、浸透していたのかなと考えているところです。水族館の事業者に個別に、区からこういったプロポーザルの実施について申し入れたといったことは、行ってございません。","id":"exchange-012"},{"speaker":"田中委員","kind":"提案","question":"複数の方からの関心もあった上での、今回の結果ということでありましたので、そういう意味では、致し方なかったのかなと思います。今回のご提案された内容はこういうことなのですが、区側から採点の低いものに対して改善を求めるようなことが、その点はいかがか尋ねました。","respondent":"高梨公園課長","answer":"これは６割ぐらいです。現段階におきましては、事業者もしっかりとそれを真摯に受け止めて、今後協議をしてつくり上げていきたいという回答を得ているところです。","id":"exchange-013"},{"speaker":"田中委員","kind":"提案","question":"今後いろいろな提案があるかと思いますが、あるいは、特に区民からの要望だとか声といったものも。相当上回るような提案があったから、過小の提案だったために、そこはいかがなのか尋ねました。","respondent":"高梨公園課長","answer":"その予算額に対して、どれだけ低減されたかといったところで評価をしています。ここの部分につきましては、予算とほぼ同額といったところですので、中庸な評価という形で、こういった配点になっているところです。","id":"exchange-014"},{"speaker":"田中委員","kind":"提案","question":"逆にそれより上の提案の内容が、最小の費用だけを求めるだけではなく、その辺はいかがか尋ねました。","respondent":"高梨公園課長","answer":"ほぼ同額でございましたので、先ほど申しましたとおり、中庸の評価といったところです。将来にかかる実施設計や工事監理等々の費用については、今後しっかり協議していきましょうということで、意見を付させていただいたです。","id":"exchange-015"},{"speaker":"田中委員","kind":"提案","question":"提案の内容がどうなのかは分かりませんけれども、大井競馬場もぜひ品川競馬場にしていただきたいし、ぜひ取り組んでほしいと求めました。これは要望でお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-016"},{"speaker":"西本委員","kind":"提案","question":"やみくもに予算を上げるべきとは思わないですけれども、いろいろ提案を事業者の方がしてきて、それにはやはりお金が必要だ。それは少し付加するという形で、自由度を持たせてほしいと求めましたが、予算のかけ方についてお考えを説明を求めました。","respondent":"高梨公園課長","answer":"大きく制約となるようなものではないと現段階では考えてありますが、適正な時期にしっかりと、区としては予算も要求をしていく。計画的に、予算につきましても事業の進捗につきましても、進行していけるように区として取り組んでまいりたいと思います。","id":"exchange-017"},{"speaker":"西本委員","kind":"提案","question":"ぜひ、いろいろな提案があるし、状況も変わっていきますので、柔軟に対応をお願いしたいと思います。その辺の広がりもぜひ考えていただいて、あまり制約をかけないような方向に持っていっていただきたいという意見を言わせてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-018"},{"speaker":"のだて委員","kind":"質問","question":"外部有識者の意見書を今回もらっているということですけれども、外部有識者の方を選定委員にしなかった理由を伺いたいと思います。そこを伺いたいのと、説明の中で少しずつ出ていますけれども、どういったやり取りがあったのかを教えていただければ。","respondent":"高梨公園課長","answer":"附帯意見がつきましたけれども、その部分について気になるといったところで、質疑のやり取りが交わされたという状況です。会社としての取組の意欲、複数年にわたってやるといった体制の部分等、質問が委員から出されたという状況でございました。","id":"exchange-019"},{"speaker":"のだて委員","kind":"質問・要望","question":"最後に意見だけ。指定管理者などで外部委員が入って選定していると思いますので、今後そうした有識者の方を選定委員に入れて、やっていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"まつざわ副委員長","kind":"確認","question":"公募で１者ということで、その中から、選定も大分ご苦労されたというのは、質疑の中で確認が取れました。しながわ水族館に関する意見というのは、大体どれくらいまで聞けるというか、その辺で確認だけ。","respondent":"高梨公園課長","answer":"ほかの部署の関係職員を集めて、新しい水族館をどんな水族館にしたいのかというＰＴを組んで、いろいろ意見を交わしています。区民向けの説明会、また個別の説明も必要でしょうし、そういった説明の中でしっかりとご意見をいただきたいと考えていますので。","id":"exchange-021"}]},{"id":"topic-03","title":"しながわ区民公園北側ゾーン改修工事（第二期）","agenda":"しながわ区民公園北側ゾーン改修工事（第二期）","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"変更内容の（２）と（３）のところで、そういったところはあるのかどうか、伺いたいと思います。では、ほかの質問に答えてほしいと求めました。","respondent":"高梨公園課長","answer":"変更を行った場所についてですが、（２）の部分はテニスコートの舗装を全部やり替えてあります。区民への影響といったところですが、今回の変更により、解消した後の性能が落ちるといったことはございません。","id":"exchange-022"},{"speaker":"田中委員","kind":"質問・要望","question":"環境影響上問題はないということも確認した上で、そういう対応を取られたのか、お聞かせほしいと求めました。","respondent":"高梨公園課長","answer":"想定ですが、軟弱だった地盤のところに鉄鋼スラグを混ぜて、固い地盤にしています。先ほど申しましたとおり、広く改良材として使われているものですので、残置することについては問題ございません。","id":"exchange-023"}]},{"id":"topic-04","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"まつざわ副委員長","kind":"質問","question":"できる看板と、たしか私もこの足立区のをいいなと思って、質問させてもらったのです。もっと今後柔軟に、大きな意味で考えていけたらいいなと思いますけれども、ご意見を。","respondent":"高梨公園課長","answer":"全２７４の公園で、一気に全部ということは難しいのですけれども、できるところからということで実施をしています。可能な限り説明を尽くしているところではありますが、一つ一つ取組を進めていければということで、今考えているところです。","id":"exchange-024"},{"speaker":"西本委員","kind":"質問・要望","question":"それから２つ目が、樹木なのですけれども、これは要望を時々いただくのです。は堂々とキャッチボールができるものですから、そういうものをつくってほしいという意見もあり、その方向性についてお聞きしたいと思います。","respondent":"高梨公園課長","answer":"可能性を閉じずにニーズの状況を見ながら、チャレンジ、検討してまいりたいと考えています。地域の各団体の方々とお話を進めているところですので、いいものがつくれるように、これから取り組んでまいりたいと考えています。","id":"exchange-025"},{"speaker":"西本委員","kind":"質問・要望","question":"意外と都会の中で犯罪が起きるのは、死角のある公園とあるので、そこは気をつけてほしいと求めました。交通整理が必要なときには交通整理、けれども出過ぎずということで、ぜひお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"田中委員","kind":"質問・要望","question":"最近ですと、新たな土地が出たときに、手順としては、企画部がまとめるのでしょうか。特に公園があまりない場所に対して、より積極的に公園を設けようという取組が行われているのかどうか、まずお聞かせいただきたい。","respondent":"高梨公園課長","answer":"公園を持たない町会内への一町会一公園の設置といったところは、公園設置の優先度を高めてもらいたいということで、連携を密に取っているところです。","id":"exchange-027"},{"speaker":"田中委員","kind":"質問・要望","question":"その辺、ぜひお願いしたいですし、また、地元からの声もしっかり受け止めていただいた上での対応をお願いしたいと思います。すみません、不勉強であれなのですが、どういう扱いになるのかというのをお聞かせいただきたい。","respondent":"高梨公園課長","answer":"公園や児童遊園の確保というところは、これまでも取り組んでまいりましたし、これからも取り組んでまいりたいと考えています。地権者等も踏まえて、需要の状況等を見ながら、これからも取り組んでまいりたいと考えています。","id":"exchange-028"},{"speaker":"田中委員","kind":"質問・要望","question":"１００％区が負担をするのではなくて、この間も、財源は都なり国からも入るのだろうと。そこも確認なのですが、可能かどうかということと、どのように公園が活かされるのかという点もお聞かせいただきたい。","respondent":"高梨公園課長","answer":"公園設置に関しましては、例えば防災に特化しているというところであったりということで、様々なメニューがあります。都市計画の変更として、都市公園を廃止して、別の用途に転用するといった方策は取りづらいのが現状かなと考えています。","id":"exchange-029"},{"speaker":"田中委員","kind":"質問","question":"公園利用に当たっての制約なり、逆にこういうものは作らなければいけないとか、何かそういう違いがあるのか。同じ公園という範疇のものですから、どういうメリットがあるのかというのも、そういう対応というのは可能なのか尋ねました。","respondent":"高梨公園課長","answer":"今まで設置してきた歴史もありますし、これから設置するものに関しましても、指定をしていっているという状況です。そういうことはできませんということが明記されているものはないという認識ですので、東京都との相談、協議によるのかなといったところです。","id":"exchange-030"},{"speaker":"田中委員","kind":"質問・要望","question":"いろいろな手法を取ってご対応いただくことで、全体的な公園の評価の価値を高めていただけるようにお願いしたいと思います。１か所だけではあれなので、その辺の、まず電源に関しての考え方をお聞かせいただきたい。","respondent":"高梨公園課長","answer":"今の運用の中では、防災広場に一体どれだけの期間滞在するのかとか、そういったところを総合的に勘案して決めるべきかなと考えています。例えば個別の公園だけついているという形ではなくて、一定、区として公平性が保たれたような形で設置ができればと考えています。","id":"exchange-031"},{"speaker":"田中委員","kind":"意見","question":"私は必要だと思いますので、ぜひご検討をお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-032"},{"speaker":"のだて委員","kind":"質問・要望","question":"多くの方が利用しやすいような形で進めていただきたいと思うのですけれども、いかがでしょうかということと、伺いたいと思います。公園が町会に１か所もないところというところで、ぜひそれを私からも、公園がつくれるように進めていっていただきたいと要望しておきたいと思います。","respondent":"高梨公園課長","answer":"バリアフリートイレ、だれでもトイレの中には、介助用ベッドということで、大人の介助ができるようなシートの設置も現在進めているところです。","id":"exchange-033"},{"speaker":"のだて委員","kind":"質問・要望","question":"進めていただきたいと思うのですけれども、ぜひ屋根の設置を進めていただきたいと思うのですけれども、いかがでしょうか。子どもたちが利用するというところで、ぜひ無料にしていただきたいと思うのですけれども、いかがか尋ねました。","respondent":"高梨公園課長","answer":"どういう方針かですが、ご説明したように聞いているのですが、周辺の公園の遊具の状況等も調査をしています。砂場になかなか日陰がなくてという声は公園課でもいただいてありますので、メーカー等とも協議をしながら検討を進めてまいりたいと思ってあります。","id":"exchange-034"},{"speaker":"のだて委員","kind":"質問・要望","question":"樹木の伐採が出てきてしまう可能性があると思いますので、樹木の伐採は極力避けるようにしてほしいと求めましたが、いかがでしょうか。多くの利用者も含めて、声を聴いてほしいと求めましたが、いかがか尋ねました。","respondent":"高梨公園課長","answer":"１本も切らないのかどうかということにつきましては、中には古い樹木等もありますので、樹木等の対応については取り組んでまいりたいと考えています。","id":"exchange-035"},{"speaker":"のだて委員","kind":"質問・要望","question":"それと、面積としては、最大ですけれども２,０００m2余ということで、なかなかの広さだなと。樹木の伐採なども出てきますし、そういったことも考慮いただきたいということで、これは要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/372951?Template=document&Id=4396#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":38046,"voices":98}},{"id":"r05-20231128-9","meetingId":"r05-cm11","date":"2023年11月28日","dateIso":"2023-11-28","committee":"文教委員会","time":"午前１０時０７分～午後 ２時３２分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を62件整理しています。","topics":[{"id":"topic-01","title":"第１０１号議案 学校教育職員の給与に関する条例の一部を改正する条例、(2)第１０２号議案 幼稚園教育職員の給与に関する条例の一部を改正する条例の２議案","agenda":"第１０１号議案 学校教育職員の給与に関する条例の一部を改正する条例、(2)第１０２号議案 幼稚園教育職員の給与に関する条例の一部を改正する条例の２議案","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"勤勉手当というのはどういう手当なのか、改めてご説明いただきたいのと、あと今回、一般職の特別給の改正というのは、全て勤勉手当に割り当てるということでしたけれども、その理由ももう少し伺いたいと思います。","respondent":"中谷指導課長","answer":"民間における賞与等の特別給に相当するもので、かつ、そのうち成績査定分に相当するものとなっております。こちらは、民間の支給状況と比較というところにおいて割り当てるというところで、一般職員は勤勉手当に割り当てるというような結論となったものです。","id":"exchange-001"}]},{"id":"topic-02","title":"第３回～第５回品川区学事制度審議会の実施報告","agenda":"第３回～第５回品川区学事制度審議会の実施報告","exchanges":[{"speaker":"安藤委員","kind":"確認","question":"前提として、審議会の内容も確認しようと思ったのですけれども、第３回までしかホームページに出ていない。議会を軽視していると言われても仕方がないと思うのですけれども、いかがか尋ねました。","respondent":"柏木学務課長","answer":"最終調整をしているというところで、文言の表現の修正等を今実際行っているところですので、現段階ではお示しできないです。特に議会軽視ということで行っているものではございませんので、そこはご了解いただきたいと思います。","id":"exchange-002"},{"speaker":"安藤委員","kind":"確認","question":"それで、「検討が必要となる学校の再確認」というような文言がありますけれども、検討が必要となる学校とはどこなのでしょうか、伺いたいと思います。それと、中間答申の案を作成するに当たって、当該学校の学区の地域からの声や意見はどのように聞いたのでしょうか、伺いたいと思います。","respondent":"柏木学務課長","answer":"審議会のメンバーとしては、地域を限定した委員というのは、特に構成のときにはそういう形では構成はしてございません。それと、地域の意見聴取ですが、メンバーの委員の中に地域の代表等が入ってありますので、そちらから意見等はいただいてあります。","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問","question":"その辺を伺いたいのと、第１回の審議会でも委員から、検討が必要となる学校も明かさない。明かさない以上は、それでいいのでしょうか、伺いたいと思います。","respondent":"柏木学務課長","answer":"答申に具体的な学校名が出るかですが、学校ごとに学級数の状況については資料として出す予定です。区全体としての考え方として、町会の代表等にも出ていただいておりますので、そちらから意見聴取をしているということになります。","id":"exchange-004"},{"speaker":"安藤委員","kind":"質問","question":"伺うつもりがあるのでしょうかというふうに私は思うのですけれども、それだと進め方としても問題があるのではないですか。どうか尋ねました。","respondent":"柏木学務課長","answer":"それと、地域の声ですが、こちらも一部、繰り返しになりますけれども、審議会で、地域の代表等も入っていますので、そこで受けてあります。最終的な答申を受けまして制度設計をするときには、また個別の地域等とはお話をさせていただきたいと考えています。","id":"exchange-005"},{"speaker":"安藤委員","kind":"確認","question":"伺いたいのは、ではどこの学校をこういうふうにしますという学校の変更案が出てこないということなのか、確認させてください。第２回では委員から、学校の新設も含めて検討するのかという質問が出ていたのですけれども、検討の俎上には上ったのかどうかも併せて伺います。","respondent":"柏木学務課長","answer":"こちらも繰り返しになりますが、区全体としての、こういうときにはこういう方策等を検討したらどうかということですので。それと、新設の学校につきましても、委員からそういう声もございましたので、審議会の中では検討はしています。","id":"exchange-006"},{"speaker":"安藤委員","kind":"質問","question":"委員から第３回審議会で、開発の抑制に関する件について意見が出たとありますが、どのような意見だったのでしょうか。区の姿勢を示す意味でも、住民説明会の開催は私は必要不可欠だと思うのですけれども、それも併せて伺います。","respondent":"柏木学務課長","answer":"１つ目、再開発の抑制等の件ですが、委員からある自治体を例にして、そういうことは品川区で可能かというお話は、意見としては出てあります。それと、中間答申の説明会ですが、実施する予定はございません。","id":"exchange-007"},{"speaker":"安藤委員","kind":"質問","question":"なぜ実施する予定がないのかというのを教えてもらいたいのと、あと私は先ほど、まちづくりの点では、そういう意見が出たわけではないですか。だから私は、他人事ではないのではないですかと言ったので、そこについても教育委員会のお考えを伺いたいと思います。","respondent":"柏木学務課長","answer":"説明会の件ですけれども、説明会等なくてもご理解いただけるのではないか、ご意見も寄せられるのではないかと考えています。内容につきましては、中間答申でも一部触れる予定ですので、そちらをご覧いただければと思います。","id":"exchange-008"},{"speaker":"ゆきた委員","kind":"質問","question":"どうして八潮学園ではなくて、通学に危険な第一京浜を越えて浜川小学校まで行かなくてはいけないのかという声が上がってきています。品川区のホームページ上の、区全体の通学区域の設計について区民の声がどう反映されていくのか、お示しできる範囲で教えてほしいと求めました。","respondent":"柏木学務課長","answer":"基本的な考え方ですが、基本的には変更しない、できればしたくないというのが正直なところです。いろいろな場でその部分も含めて検討し、区民の声等には回答させていただいているところですが、通学区域を変更するというのは。","id":"exchange-009"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"傍聴もしていますので、学事制度審議会について、要旨であって発言録にはならないという理由が何かあったら教えてほしいと求めました。区民にとっては、こういうところに参加している方がどういう発言をしていらっしゃるかは、その辺はいかがでしょう。","respondent":"柏木学務課長","answer":"発言録等の公表ですが、発言録ですと、発言された方が特定されてしまうという部分で、審議で自由濶達なご意見等を本当に今いただいているところですので、そういう部分が制限されてしまうおそれがありますので、現状では発言録については公表する予定はございません。","id":"exchange-010"},{"speaker":"吉田副委員長","kind":"確認","question":"インターネット上の公開でなくても、公式な議事録・発言録として一般的に公開する場合には、発言者の確認は必ず取るはずです。そういう形を教育委員会事務局として取ることは可能だと思うのですが、いかがか尋ねました。","respondent":"柏木学務課長","answer":"審議会第１回で、こちらは議事録要旨の公表または内容等の記載については、審議会で審議し、了解を得ているものです。発言録につきましては、個人の特定をされるという部分で、差し控えたいと考えています。","id":"exchange-011"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"それぐらいは発言には責任を持ってほしいと求めましたし、こういう発言ということで発表しますということを確認していただいて、ここについては。これは要望でとどめます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"}]},{"id":"topic-03","title":"区立学校におけるいじめの重大事態の発生状況","agenda":"区立学校におけるいじめの重大事態の発生状況","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"伺いますけれども、品川区教育委員会は、なぜこのようにいじめの重大事態が頻発すると考えているのか伺いたいと思います。根本には、子どもたちのストレスの高まり、学校が楽しくない、つらいということがあるのではないかと思うのですけれども、伺いたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"いじめが起こる１つの原因としては、現在もそうですけれども、どういう取組ができるかということで検討を重ねているところです。いじめの予防や、万が一いじめがあったときには適切に認知して早期対応を行っていくということを、しっかりと実施してまいりたいという考えです。","id":"exchange-013"},{"speaker":"安藤委員","kind":"質問","question":"そういうのがあるのではないかと思うのですけれども、そこについては、いじめとの関連性について、どのように考えているのでしょうか。伺いたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"そういったところを教員がしっかりと把握できるような取組も含めて、子ども一人一人の様子をしっかり把握できるようなものを現在検討中です。","id":"exchange-014"},{"speaker":"安藤委員","kind":"質問","question":"先ほど、やはり加速させているという自覚はあるのでしょうか、ないのでしょうか。最後に伺いたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"本区でいうと品川区立学校教育要領も改訂を行い、保護者の方も交えたルールづくり・校則づくりというのも、ここ数年で改善を図っているところです。","id":"exchange-015"},{"speaker":"安藤委員","kind":"質問・要望","question":"日本の教育は競争し過ぎると毎年指摘されているわけですから、それで、その先頭に立ってきたのが品川区の教育なのですから。あまりにも自覚がなさ過ぎるということで、今後また具体的な事例も含めて議会で論じていきたいと思いますので、今日は終わりにいたします。","respondent":"丸谷教育総合支援センター長","answer":"それを授業改善や個への指導に生かしていくということで、子どもたちのためになるということで努めているところです。継続させていきながら、発見することが楽しい、課題解決することが楽しいと思えるような学校教育に努めてまいりたいと考えております。","id":"exchange-016"},{"speaker":"ゆきた委員","kind":"質問","question":"現在、いじめの重大事態が６件あると報告を受けています。設置が５名以内で、４名で構成されていると聞いていますが、この６件の重大事態について４名で対応されているとの認識でよろしいか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"現在の体制は、今、委員がおっしゃったとおり４名体制ということになります。この６件についてどう割り振っていくかというところは、今後、円滑に調査が進むように検討していきたいと考えております。","id":"exchange-017"},{"speaker":"ゆきた委員","kind":"質問","question":"今後は臨時委員も設置されていくと思われますが、条例にのっとることももちろんですが、公布されるまでの間の継ぎ目の期間、この間の期間の暫定的な措置があるのかないのかについても教えてほしいと求めました。","respondent":"丸谷教育総合支援センター長","answer":"条例が公布されるまでの期間ですけれども、調査の方針や、調査結果をいつまでに出せるかというところの検討は進めていきながら、円滑に引継ぎ、つなぎができるように努めてまいります。","id":"exchange-018"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"その辺のお考えをお聞かせいただきたいのと、自分のときと今の子どもたちがどうなのかというのは、確かにストレスが一定あるのかと。その辺についてもお考えを説明を求めました。","respondent":"丸谷教育総合支援センター長","answer":"法に基づいて適切に行っている中で、いじめの解決に向けた対応については、それぞれの学校が教育委員会とも連携しながら進めているところです。","id":"exchange-019"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"やはりどうしても、出してしまうといろいろ響くから、うーんと目をつぶってしまうときもあるではないですか。ぜひリアルなものを教えてくれ」という気持ちを示すことによって、そこは改めて要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"せお委員","kind":"質問・要望","question":"この２件なのですけれども、お伝えできる範囲でいいのですけれども、報告までの経路というか、何というんですか、例えばＨＥＡＲＴＳを挟んでの教育委員会なのかとか、学校から直接来たのかという、そういうところをお話しできる範囲で教えてほしいと求めました。","respondent":"丸谷教育総合支援センター長","answer":"いずれも、２号、いじめに遭って不登校になったケースということで、いじめの報告と併せて不登校の報告が教育委員会に上がってきます。ある程度、日数が超えたので重大事態になりますということで、認定していったという経緯になります。","id":"exchange-021"},{"speaker":"せお委員","kind":"質問・要望","question":"件数が上がってきて、そういったところもぜひ一緒に検証していただきたいというところを要望します。仲間として、少しはいじめを減らす方向につながっていくのかというのは感じていたので、意見として言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"高橋（し）委員","kind":"質問","question":"お尋ねしたいことは、学校種のところで、義務教育学校の前期か後期かを書いていないのはなぜなのかと。何というか、そういうものが上がってきているか、その辺の対応をどうされているかというのをお聞きします。","respondent":"丸谷教育総合支援センター長","answer":"学校と教育委員会で、風通しよくしっかりと情報を共有しながら進めていくことが大切だと考えますので、引き続き努めてまいります。そういった児童・生徒に対しては、スクールカウンセラーとの連携やＨＥＡＲＴＳの支援等も含めて、継続的に行っていきたいと考えております。","id":"exchange-023"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"２年生になって、今お話をしていただいたので、よろしくお願いします。それは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"吉田副委員長","kind":"質問","question":"私から伺いたいのは、今日、委員会に向けた報告のためにこのようにまとめられたという理解でよろしいのか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"こちらは国の調査等もございまして、いじめがあった際に、どの態様に当てはまるのかというのをまず分類いたします。８つ示された中でのものということで、絞った形での報告も上がっていますし、それを基に調査を行っていくということになっています。","id":"exchange-025"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"ぜひその辺については忘れずに、いじめることでしか承認欲求が満たされないという子どもたちに対しての手もぜひ差し伸べてほしいと求めました。もし何か見解があれば伺いたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"しっかりと学校の中では、そういった取組も進めているところでありますので、いじめの予防に努められるようにしていきたいと考えています。","id":"exchange-026"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"でも、まずは本人の言い分を徹底的に受け止めるということは、ぜひ教員の方には徹底してほしいと求めました。これは要望でとどめます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"そこをどういうふうに、大小にかかわらず上がってくると思うのですけれども、具体的に何かそういった例もあったら教えていただきたい。絶対それはもう最終的には家庭教育というのが一番だと私は思っているので、もし、ほかに何かお考えがあれば教えてほしいと求めました。","respondent":"丸谷教育総合支援センター長","answer":"適切に認知して対応していくということは、努めているところではありますけれども、こちらからもご提案しながら実践を進めているです。いじめの定義の共通認識を、そういった家庭への啓発ということも、今後しっかりと努めていきたいと考えています。","id":"exchange-028"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"要望させてほしいと求めましたので、ぜひ家庭への啓発も改めてやってほしいと求めましたので、どうぞ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"高橋（し）委員","kind":"意見","question":"最後に一言。そういうのはいいのですけれども、それに対して教育委員会としてどうかというのはお答えいただいたほうがいいと思ったので、お尋ねしますとの意見を述べました。","respondent":"丸谷教育総合支援センター長","answer":"当てにならないというようなご意見かと思いますが、お話を受けたときには、学校に事実関係を我々としては確認いたします。対応が適切ではなかった場合に、その教員に対して指導していただいて、保護者との関係を修復するような形を取らせていただいているところです。","id":"exchange-030"}]},{"id":"topic-04","title":"ヤングケアラー調査の実施結果について（速報）","agenda":"ヤングケアラー調査の実施結果について（速報）","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"２点伺うのですけれども、まず調査のやり方なのですけれども、送付して、どんなやり方で、どういうふうに回収したのでしょうか。その辺をお伺いしたいのと、今後どういうクロス集計などを行って、スケジュール感みたいなものを説明を求めました。","respondent":"染谷子ども家庭支援センター長","answer":"直接ご自宅に郵送させていただいて、インターネットのウェブ上で回答いただくという方法でアンケートを集計しております。まず、一部並行してという作業にはなってまいりますが、今年度中に支援マニュアルのようなものを作成していく予定になっておりますので。","id":"exchange-031"},{"speaker":"安藤委員","kind":"質問","question":"すみません。タブレット以外にも何か回答の仕方というのはあったのかということと、区立小・中学校ではない子というのはどうしたのかを説明を求めました。","respondent":"染谷子ども家庭支援センター長","answer":"それから、タブレット以外の回答ですが、ご自身で使われているような媒体、端末であれば、そちらでの回答も当然していただけるような形ではあります。","id":"exchange-032"},{"speaker":"ゆきた委員","kind":"質問","question":"家事援助の訪問支援や配食サービス、８月の文教委員会では、今年度はヤングケアラーについて既に予算化されているというお話もあったと思います。これからだと思われますが、具体的なところで決まっている事業等など、紹介できる範囲で教えてもらえればと思います。","respondent":"染谷子ども家庭支援センター長","answer":"実施を予定しているものの中で１つ、区に配置しておりますヤングケアラーコーディネーターも併せて、そういったところでお話をしていくと。１つ、相談できる場や、そういった事業は今年度中には展開してまいりたいと考えているところです。","id":"exchange-033"},{"speaker":"ゆきた委員","kind":"意見","question":"このアンケートも引き続き継続していきながら、この結果について反映できるような事業の展開を、ぜひともよろしくお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-034"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"いわゆるその子たちの時間、本来その年齢で享受しなければいけない時間まで割かれてしまっているようなお世話なのかというのが大事なのです。もったいなくなってしまうので、そこはぜひ気をつけて取り組んでほしいと求めましたけれども、この辺でもし何かお考えがあれば説明を求めました。","respondent":"染谷子ども家庭支援センター長","answer":"本来、まさに支援の対象として、区として対応させていただかなければならないところかと考えています。１つ、ケアの１日当たりの時間帯がどのくらいだといったところもお聞きしておりますので、分析を進めていきたいと考えております。","id":"exchange-035"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"よくないのだというのだけは、考えから取っ払っていただいて、ぜひいい方向に進んでほしいと求めました。我々も、できる限りいろいろなアイデアを出させていただきながら、一緒に見つけていきたいと思う。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"高橋（し）委員","kind":"質問","question":"それで、子ども未来部で現在、支援策を進めて、来年度もということなので、ぜひそれはきちんとやっていただければいいと思います。ご質問は、この内容は、学校、特に区立小学校、中学校にどのようにして伝わるのか尋ねました。","respondent":"染谷子ども家庭支援センター長","answer":"学校の教員の皆様にも、ぜひこちらを共有させていただきたいと思いますので、教育委員会事務局と相談をさせていただければと思います。","id":"exchange-037"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"話を聞いてほしいのと、勉強を教えてほしいというところもあるので、私としては生かしていただきたいと思っています。もう既に、個人面談も学校ではされていますから、この実態をしっかりと認識したときの指導をどのようにしていただけるかというところをお尋ねします。","respondent":"丸谷教育総合支援センター長","answer":"子ども家庭支援センターと連携しながら進めておりまして、まず教員として認識を持ってくださいということでの研修を進めてきています。子ども家庭支援センターとも連携をしながら、あとは学習支援であったり、学校にも周知徹底していきたいと考えております。","id":"exchange-038"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"単純な計算ですけれども、そういうところから、やはり、今お話があったような指導をきめ細かくしてほしいと求めました。これは要望で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"せお委員","kind":"質問","question":"調査していただいてありがとうありますという、まずお礼を。協議会みたいなものというのは今準備されているのか、今後そういったことがあるのか、説明を求めました。","respondent":"染谷子ども家庭支援センター長","answer":"ヤングケアラーの支援につきましては、高齢、ヤングケアラーの支援についてそれぞれの視点から意見をいただくというようなことをやっております。","id":"exchange-040"},{"speaker":"せお委員","kind":"質問・要望","question":"庁内連絡会議を開いていただいているということなので、ぜひそれが１回で終わらず、定期的に続けていただきたいと思っています。そういったいろいろな考え方があると思いますので、その辺もぜひ配慮していただきながら、庁内でも検討していただければと要望いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"吉田副委員長","kind":"提案","question":"まず所管に、こういうことを議員提案でやるからということを通して、庁内挙げての仕組みをつくったというお話を伺っております。定期的な協議を進めてほしいというのは、せお委員からもご要望がありましたけれども、教えてほしいと求めました。","respondent":"染谷子ども家庭支援センター長","answer":"子どもたちのためならということで、学校からの配付を引き受けていただけたことで、今回調査を実施できたと考えております。やはりこれまでと同様、子ども未来部のみで検討を進めていくものではないと思いますので、他部署と連携しながら進めていければと考えております。","id":"exchange-042"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"なぜ学校現場がそういう調査を避けるかというと、いろいろな調査は学校に求められるのだけれども、あまりフィードバックがないのだと。もちろん家事支援やレスパイト支援をぜひお願いしたいのですけれども、まだ全然、もし何かご見解があれば伺いたいと思います。","respondent":"染谷子ども家庭支援センター長","answer":"このアンケートを生かせるように、それからあと区民の方にもご回答いただきましたので、きちんとそちらをお示ししていければと思います。何か支援ができるようなことについて、今後、検討してまいりたいと考えております。","id":"exchange-043"}]},{"id":"topic-05","title":"東京都からの一時保護受託の実施","agenda":"東京都からの一時保護受託の実施","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"２３区中２２区で児童相談所ができていくわけなのですが、一時保護の場所については、もうつくられているのでしょうか。どのような中身になるのか、伺いたいと思います。","respondent":"長谷川児童相談所開設準備課長","answer":"一時保護した子どもの取扱いや、措置する場合のルール等につきましては、東京都がこれまで実施してきた体制を基本的には踏襲する形を取ってあります。したがいまして、品川区も開設後はそのルールに従い、措置あるいは保護するという状況です。","id":"exchange-044"},{"speaker":"安藤委員","kind":"質問","question":"その会議体の中でいろいろ話しているということだと思うのですけれども、２２区で児童相談所が全て出来上がったときというのは、もう既にそういう一時保護の預かり先のルールというのですか、そういうものというのは出来上がるという感じでよろしいのか尋ねました。","respondent":"長谷川児童相談所開設準備課長","answer":"全国ルールというものがございまして、児童相談所間の差がないように定めているものがあります。その後に、先行で開設している区が東京都と協議して決定した内容に従い、品川区も保護するといった方針です。","id":"exchange-045"}]},{"id":"topic-06","title":"品川区内保育園等あり方基本方針素案","agenda":"品川区内保育園等あり方基本方針素案","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"ゆとりという意味を含むと思うのですけれども、結局のところ、どういう意味なのでしょうか。結局どれぐらい減らす、何園減らすと想定しているのか、伺いたいと思います。","respondent":"今井保育教育運営担当課長","answer":"今後、統合をどの程度進めていくのかといったご質問ですけれども、まだ具体的に何園というところの検討、結論までは至っておりません。保育の空き状況といったものは変わってまいりますので、どの地区で、どの園をというところでの具体的な検討を今後進めするという予定です。","id":"exchange-046"},{"speaker":"安藤委員","kind":"質問","question":"その辺を伺いたいのが２点目。その２つをお伺いします。","respondent":"今井保育教育運営担当課長","answer":"今後パブリックコメントを実施いたしまして、最終的には令和６年４月に基本方針を公表するまでは「案」の状態で、その確定に向けて今後。は統合していって、必要な機能は持ちつつ統合を進めていくという考えですので、それぞれ逆行するものではないと認識しています。","id":"exchange-047"},{"speaker":"安藤委員","kind":"質問","question":"区立園の統合がなぜ必要なのか、改めて伺います。かなり無理があるというか、矛盾しているのではないかと思うのですけれども、いかがか尋ねました。","respondent":"今井保育教育運営担当課長","answer":"お答えが重複すると思いますので、まとめてお答えしますけれども、在宅の子育て支援といったところへの対応も求められているところです。機能強化された園で地域需要に対応していくといったところで、今回の統合の方針というのは矛盾しないものであると考えているところです。","id":"exchange-048"},{"speaker":"安藤委員","kind":"質問","question":"園を維持したまま、例えば定員を思い切って減らす、ゆとりある保育環境をつくるなど、できるわけではないですか。そして、新たな区立保育園の民営化園というのは何園を考えているのか、伺いたいと思います。","respondent":"今井保育教育運営担当課長","answer":"３点目が、民営化の進め方についてのご質問でございまして、委員のご認識のとおりです。関わって進めていくものではありますけれども、それぞれで統合する園についての検討、別々の考え方で進めていくものです。","id":"exchange-049"},{"speaker":"安藤委員","kind":"質問・要望","question":"どれぐらい保育園を減らすのですかという話をしたら、ここを統合するというような方針というのは発表するお考えなのか、伺いたいというのが１つ。職員の方々への影響も相当あるわけですから、こうした方々の意見をどう集約するつもりなのか、そのお考えをお聞かせいただきたいというのが２点目。","respondent":"今井保育教育運営担当課長","answer":"３点目が、検討の内容を一緒に考えていただいているといったものですので、この方針の中には現場の意見も反映されたものになっているです。説明会の実施についてですけれども、内容が伝わるように対応していますので、現状で説明会を実施する予定はございません。","id":"exchange-050"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"今年も７０万人前半になるのではないかと言われている中で、改めてお考えをお伺いしたいのが、まず１点。私は次に質を求める中では、その質の中の大きなウエイトを占めているのが、やはり保育士の処遇改善だと思うのです。","respondent":"今井保育教育運営担当課長、石井保育支援課長","answer":"地区のバランス等々もありますので、そういったところを総合的に勘案しながら、こういった基本方針というのは進めていきたいと考えているところです。… 例えば在宅支援ということですけれども、今年度、国のモデル事業を使って、未就園児の定期預かり事業を実施しています。","id":"exchange-051"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"その観点で進めていただきたいと思うし、保育士にも一定の処遇というのはされているのかもしれないですが、私立のほうです。やはりそこは改めて強く要望していきたいと思うし、ぜひそこは強く要望して、これはもう要望でとどめますけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-052"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"子どもたちが週に１回、２週間に１遍、その点についてだけお願いします。","respondent":"今井保育教育運営担当課長","answer":"特別な支援が必要なお子さんに対する配慮といった質問です。現状で、例えば品川児童学園と連携した保育所等の訪問支援等を実施していますけれども、引き続き検討させていただきたいと考えております。","id":"exchange-053"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"施設に別の機能を持たせるというときには、そういうことが行われるチャンスだと思うので、ぜひよろしくお願いします。要望で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"},{"speaker":"せお委員","kind":"質問・要望","question":"区立保育園に関する課題のところの６番で、結構、パンクしてしまっているという状況をよく聞くのです。就学後に対しての就学前で行っている支援というのはどういうものがあるのかと、取り組んでいくものがあれば、教えていただきたい。","respondent":"立木保育課長","answer":"ほかの支援が必要でないお子様と一緒に、例えば保幼小連携、やはりお子様の認識を持ってもらうというのが一番大事なのかというところがありますので。","id":"exchange-055"},{"speaker":"せお委員","kind":"質問・要望","question":"何というのですか、ぜひ積極的に、保護者も園に関われるような体制というのは整えてほしいというのを要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-056"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ハード面のことでお尋ねなのですけれども、素案の１３ページで、それぞれ併設の状況を今お示しされております。現時点でどういう方向性、お考えでしていくのかという、方向性だけお聞かせいただければ。","respondent":"今井保育教育運営担当課長","answer":"今後の進め方、手法の検討といった部分のご質問ですけれども、調整に時間がかかってくるといったところもあります。併せまして、もろもろの要素を検討した上で、この園とこの園を統合させていくといった具体的な検討をさせていただきたいと考えているところです。","id":"exchange-057"},{"speaker":"高橋（伸）委員","kind":"意見","question":"当然、これは老朽化していて、恐らく区有施設だと、いろいろ検討も余地はあるのかと思うのですけれども、あと都営住宅ですよね。都との交渉が結構、大変なのかと思っているのですけれども、そのことだけご答弁ほしいと求めました。","respondent":"今井保育教育運営担当課長","answer":"こういった場合には、より慎重に、長期的な目線から交渉を進めていく必要があると考えております。後回しにするなどという話ではなく、長期的な目線を持って、改築に向けて準備を進めていくというような姿勢で取り組んでまいりたいと考えております。","id":"exchange-058"},{"speaker":"吉田副委員長","kind":"質問","question":"皆さんのご意見を伺うと、在宅の方たちも活用する必要があるのではないかというのは、結構前から言われていたかと考えています。今後の保育の重要性、その点についてはどのようにお考えか伺いたいと思います。","respondent":"今井保育教育運営担当課長","answer":"今後、在宅子育て支援等の強化も求められていく中では、まずそれを実施するための人的・施設的な余裕がある必要があると考えております。","id":"exchange-059"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"そういう議論をどんどん深めていっていただきたいと思うのですけれども、いろいろな場面で度々求めておりますので、特に私立園の保育士の処遇改善。なので、その辺のことも、区としてもぜひ国に対しても求めていただきたい。","respondent":"石井保育支援課長","answer":"令和５年８月なのですけれども、国で、子ども・子育て支援制度における継続的な見える化の在り方についてという有識者会議が開かれてあります。そういった動向も注視しながら、今後、引き続き検討してまいりたいと考えています。","id":"exchange-060"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"ほかのところでも見られますので、品川区ではぜひそのようなことがないように、保育の場面ではお願いしたいと思います。これは要望にとどめます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-061"}]},{"id":"topic-07","title":"議会閉会中継続審査調査事項","agenda":"議会閉会中継続審査調査事項","exchanges":[{"speaker":"高橋（し）委員","kind":"意見","question":"１つは、ホームページに８,０００万円ぐらい５市区から返還されたという記事が載っていて、１１月２４日に東京都が体罰の件数を発表したのです。品川区でも体罰等、東京都教育委員会が認定した、あるいは体罰に至らないまでもというものがあったのかどうかだけお願いしますとの意見を述べました。","respondent":"中谷指導課長","answer":"今の体罰のご報告の件なのですけれども、先日、ご指摘いただいたとおり東京都教育委員会からの通知がございまして、これを受けまして品川区としましては、次回の文教委員会で詳細を含めてご報告させていただければと考えていますので、よろしくお願いいたします。","id":"exchange-062"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/106437?Template=document&Id=5116#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":65719,"voices":192}},{"id":"r05-20231128-5","meetingId":"r05-cm11","date":"2023年11月28日","dateIso":"2023-11-28","committee":"総務委員会","time":"午前１０時０８分～午前１０時５６分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を15件整理しています。","topics":[{"id":"topic-01","title":"の給与等に関する条例の一部を改正する条例、(5)第９９号議案、職員の給与に関する条例の一部を改正する条例および(6)第１００号議案…","agenda":"の給与等に関する条例の一部を改正する条例、(5)第９９号議案、職員の給与に関する条例の一部を改正する条例および(6)第１００号議案…","exchanges":[{"speaker":"須貝委員","kind":"意見","question":"区の職員にも我慢をしてほしいところですが、これだけ物価が高騰した中で、今１世帯当たり年間１０万円以上の負担をされている。さらにこの４議案に対しては、人事委員会から勧告されていないにもかかわらずこうやって増額するということも、まずいのではないかと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"},{"speaker":"澤田委員","kind":"質問・要望","question":"昭和３９年から民間の平均を取っていて、毎年４月にその平均を取って決めてきていて、長年職員の皆さんも特別職も下がってきたと理解しております。職員の皆さんと同じように、特別職も改正していくというのがいいのではないか、進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"塚本副委員長","kind":"意見","question":"考え方としては、民間と合わせて上がるときは上がる、下がるときは下がる。そういうのがこの給与の設定としては合理的な、我々も含めて基本的にはそれが一番合理的であると思っていますので、賛成いたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-003"},{"speaker":"須貝委員","kind":"質問","question":"１個ずつですか。第９５号議案については反対します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"松本委員","kind":"意見","question":"では我々議員がどういう成果を出しているのかというところに関しては、そう簡単では、そう断言できるほどではないと私どもは考えております。したがいまして、第９５号議案に関しては反対をしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-005"},{"speaker":"石田（秀）委員","kind":"提案","question":"２回目のときはどうしても連動だから、それは議論をしっかりして、それで連動しようということになった。どうのこうのとかやっているほうが私はおかしいと思っているので、今提案があったとおりやるべきだと思っているので、第９５号議案は賛成との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-006"},{"speaker":"須貝委員","kind":"意見","question":"そういう状況を考えたときに、やはり選挙で選ばれた方たちは、私は自重すべきだと思います。今回の第９６号議案については反対しますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"須貝委員","kind":"質問","question":"逆に減額するべきであると思います。ですから、第９７号議案は反対します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"松本委員","kind":"意見","question":"会計年度任用職員に関しましては、新たに手当の部分を他の職員の方たちと合わせるというところが令和６年度に入ってからの勤勉手当ですね。期末手当の増額分については他の部分と同様のところがありますので、反対としますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-009"}]},{"id":"topic-02","title":"第７６号議案、令和５年度品川区一般会計補正予算","agenda":"第７６号議案、令和５年度品川区一般会計補正予算","exchanges":[{"speaker":"須貝委員","kind":"確認","question":"１７ページの就学支援費のほうですが、確認ですが、それとも品川区に住民票がある子どもたちだけに支援するのですか。一応説明を求めました。","respondent":"遠藤財政課長","answer":"こちらは品川区に在住されている方を対象にして、という形になります。","id":"exchange-010"},{"speaker":"須貝委員","kind":"意見","question":"ならば、公衆浴場だけではなく、また運送事業者だけではなく、他の産業・事業所においてもやはり平等・公平に支援をするべきだと私は思います。意見だけ言わせていただきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"}]},{"id":"topic-03","title":"地方税の賦課及び徴収事務における「特定個人情報保護評価」の実施","agenda":"地方税の賦課及び徴収事務における「特定個人情報保護評価」の実施","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"何かあったときにある方が例えば夜の９時に来てパソコンをいじっていて、すみません、庁内にはそういうカメラみたいなものは設置されているのですか。あくまでそのパソコン上で誰がオンオフして、誰が今これをいじったという情報だけの管理システムなのか尋ねました。","respondent":"提坂税務課長、佐藤（聡）経理課長","answer":"区民の多くの皆様と接する事務室では設置してございませんが、ほかのところでは設置しているところがあるやに聞いておりますが、詳細はちょっと存じかねます。経理課で所管しております入口ですとかエレベーターホールですとか、安全に関わるところについては常時監視という形になっております。","id":"exchange-012"},{"speaker":"須貝委員","kind":"質問・要望","question":"一部大手などは、情報開示したりいろいろやっていますので、そういうことも今後必要になるのではないかと。あるときには一つの調べることができる要素の一つにもなると思いますので、ぜひ私は検討してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"ちょっと不勉強なので教えていただきたいのですが、この根拠法令を見たときに平成２５年とか２６年で、何で今頃なのかと思った私がいます。これは２３区でほかの区はもうとっくにやっていて、その辺はあまり深く勉強していなくて、教えてもらいたいと思います。","respondent":"提坂税務課長","answer":"これまでにも特定個人情報保護評価というのは少なくとも５年に一回実施しておりまして、その後、税のほうも前回４年前に行っております。","id":"exchange-014"},{"speaker":"石田（秀）委員","kind":"質問","question":"今のはそのとおりだと思って伺っていました。ということは４年前にもやっているのだけれども、その時ちゃんとやっているのだからという理解なのかどうなのかというところだけ、説明を求めました。","respondent":"提坂税務課長","answer":"資料の２、これは今回新たに記載したものということではございませんで、もともと記載している部分です。ガバメントクラウドの利用により特定個人情報の保管場所を修正等、追加や修正項目が発生しましたので、この評価書の内容を見直すものです。","id":"exchange-015"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/246119?Template=document&Id=2284#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":16151,"voices":90}},{"id":"r05-20231128-10","meetingId":"r05-cm11","date":"2023年11月28日","dateIso":"2023-11-28","committee":"議会運営委員会","time":"午前 ９時３０分～午前 ９時３６分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/881920?Template=document&Id=5524#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":2897,"voices":16}},{"id":"r05-20231129-14","meetingId":"r05-cm11","date":"2023年11月29日","dateIso":"2023-11-29","committee":"行財政改革特別委員会","time":"午前１０時００分～午前１１時５１分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を41件整理しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"山本委員","kind":"提案","question":"このパブリックコメントを１２月に実施した後、このコメントはどのように答申などに反映されるのでしょうかです。オープンハウス方式でやって、それをその答申案にどのように反映するお考えなのかというところをお聞かせほしいと求めました。","respondent":"吉岡政策推進担当課長","answer":"順不同で私のほうから回答します。１２月にパブリックコメントをやらせていただいて、２月の答申に今のところ間に合うかなというふうな考え方で進めさせていただいているところです。","id":"exchange-001"},{"speaker":"山本委員","kind":"質問・要望","question":"委員会の開催は、ご反映いただけるということなので、そこはこれから出てくる区民の皆様の意見をぜひ酌んで進めてほしいと求めました。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"あくつ委員","kind":"質問","question":"今回のメインコンセプトである図書のことについてまずお伺いをしたいのですが、素案のほうを拝見いたしますと、素案の１７ページ。この図書機能と図書館機能はどう違うのかという、まず言葉の説明から説明を求めました。","respondent":"吉岡政策推進担当課長","answer":"ご紹介いただいた１７ページの図書機能というのは、ゾーニングを考えていくようなイメージで図書機能というような形でつけしています。１９ページの図書館機能というところで入れさせていただいたのですけれども、また統一するかどうか検討させていただきたいと思います。","id":"exchange-003"},{"speaker":"あくつ委員","kind":"質問","question":"それが区のほうの大きな全体的な構想の中でどういう位置づけになるのかということが１つ。司書の配置をどうするのかとか、その辺りはどのようなお考えなのか、決まっていることを説明を求めました。","respondent":"吉岡政策推進担当課長","answer":"そういったところから、策定委員会の委員の皆様からも、そういった意見をいただいたです。運用形態につきましては、次年度、計画の策定を進める中で検討していく形にはなりますけれども。","id":"exchange-004"},{"speaker":"あくつ委員","kind":"質問","question":"いわゆる先ほど私が八戸市の例を紹介しましたが、そういうイメージだということでいいのかどうかということが１つです。こういうところに関しては、策定委員会の役目を終わって、これは庁内のほうで検討していくということになるのか尋ねました。","respondent":"吉岡政策推進担当課長","answer":"そういったところが類似事例というようなイメージを持っていただいているのかなというふうに思っております。委員の皆様にもご覧いただいて、こういう感じだねというような認識を、感想をいただいたです。","id":"exchange-005"},{"speaker":"あくつ委員","kind":"質問","question":"これから先はもう庁内でどんどん進んでいくということになるのですか。その途中で議会への報告があるのかどうかというところも含めて、我々が何か意見を言える場があるのかということも含めて質問させていただきました。","respondent":"吉岡政策推進担当課長","answer":"あるいは地域の方に入っていただく委員会という形式で行いましたけれども、次年度はどちらかというと、庁内の検討会議というのも多く重ねる予定です。当然ながら、計画策定に向けて、議会のほうにも適宜適切に報告させていただきたいと考えています。","id":"exchange-006"},{"speaker":"えのした委員","kind":"質問","question":"複合施設、多岐にわたる取組で、私も拝見させていただきましたが、できるのかなと思いながらも、敷地面積が８,４７２.６９m2ですか。オープンハウス方式の開催の日にちが１２月８日・９日・１４日の３日間出ていますが、これは、そこをお伺いさせていただけますか尋ねました。","respondent":"吉岡政策推進担当課長","answer":"オープンハウス型の説明会の実施場所ですけれども、旧荏原第四中学校の集会室のほうで、３日間行わせていただきます。","id":"exchange-007"},{"speaker":"えのした委員","kind":"質問・要望","question":"新庁舎のときには区内全域ということでしたが、これはもうこちら１か所だけということですね。もう年末１か月の中で、私も先日の一般質問でも質問させていただきましたが、要望として終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"素案の１０ページのところでも、荏原東地区では、区内全域よりも福祉保健施設の要望が強い結果が示されていると思いました。特別養護老人ホームも導入施設に入れていただきたいなと思うのですけれども、いかがか尋ねました。","respondent":"吉岡政策推進担当課長","answer":"第３回の策定委員会のほうでは、こちらのほうで進めるというようなお話をいただいたところです。地域の方からは、なかなか特別養護老人ホームなどの入所施設というところが、特に意見としては上がってこなかったというようなところがあります。","id":"exchange-009"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"要望です。これは何か方針が変わったのか要望があったか伺いたいのと、住民同士がどういう要望をみんなが持っていて、いかがか尋ねました。","respondent":"吉岡政策推進担当課長","answer":"オープンハウスの説明会の実施についてなのですけれども、何かこれは方針が変わったとか、何か要望があったというところではございません。方針の素案のところでも、こちらの施設については、オープン型で説明会を実施したいと考えたところです。","id":"exchange-010"},{"speaker":"石田（ち）委員","kind":"意見","question":"分かりました。本当に充実する、愛される施設になっていくといいなというところでは私たちも一緒に意見を上げていきたいなというふうに思っていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"},{"speaker":"松本委員","kind":"質問","question":"そうすると、例えば二葉のほうは設立が１９７０年で、ゆたか図書館は１９７５年ということなので、場合によっては、この辺り将来的には統合ということも、一応視野には入れていらっしゃるということなのか尋ねました。","respondent":"吉岡政策推進担当課長","answer":"そういったところも含めまして、今回の旧荏原第四中学校のところの図書機能、図書館機能、図書スペース。こういったものがどれだけ拡充できるかといったところで、そういった話になってくるかと考えています。","id":"exchange-012"},{"speaker":"松本委員","kind":"質問・要望","question":"図書機能が３つ重複してしまうというふうなところがあると思いますので、将来的に、しっかりとした施設を造っていただきたいなというふうに思います。最後は要望ですけれども、ＰＦＩの視点は取り入れて、整備を進めていただきたいなというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"まつざわ委員","kind":"質問","question":"まず１点伺いたいのは、実際あそこの人たちは大崎高校に行ったりという、分散している。例えば消防団の活用の中で、消防団の誘致とか防災に関してそういったその文言というのがあったのか、まず説明を求めました。","respondent":"吉岡政策推進担当課長","answer":"５月に行われたワークショップでは、荏原消防署の戸越出張所の老朽化が進んでいるのでここにはどうかというようなご意見がございました。５７２人の区民避難所として指定されているところなのですけれども、最低でもここは確保してほしいというところが、地域の強い声だです。","id":"exchange-014"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"５７０名を入れるというのは重々承知で、例えば少し要望として言わせていただきたいのは、防災リーダーの中で必要だができない現状がある。私も図書館が気になっていまして、例えばゆたか図書館も４８年で、児童センターも５５年か尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"本当に地域の皆さんの一番の要望は、私は防災の拠点だと思っているのです。具体的に絶対これは必要というような何か意見、どういった意見があったのかというのを、まず教えてほしいと求めました。","respondent":"吉岡政策推進担当課長","answer":"今回方針というところで、特に備蓄倉庫とかあまり細かい機能についてのお話はなかったところですが、体育館ですとかこういう教室系のスペース。ソフト面のところでは、こういったところで共助の強化につながるのではないかと、そういったご意見をいただいたところです。","id":"exchange-016"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"それぞれまた区民の要望、おまとめいただいて、進めてほしいと求めました。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"塚本委員","kind":"質問","question":"１つのイメージとしてできてくるのかなと言ったときに、旧三井文庫で、そういう意味での親和性というのもあるのかなと思ったりしましたけれども。質問なのですけれども、そういった中でのにぎわいとか交流というのをどういうふうに織り交ぜていくのかというところについて、お伺いしたい。","respondent":"吉岡政策推進担当課長","answer":"割と図書館に付随して、そういったところはフロアを分けたりですとか、動線を区切ったりとかそういった工夫を重ねているところです。視察先でご提案があったところも含めまして、先行事例を今後研究していきまして、こういったものをまとめていきたいというふうに考えてあります。","id":"exchange-018"},{"speaker":"塚本委員","kind":"提案","question":"交流スペース、思い思いに自分の時間を過ごせるかなという感じだったのですが、そこは１つの参考事例としてご提案させていただきたい。ある程度見越した上でここまで提案書には載せているのか、その辺の議論はどの辺まで詰められたものなのかというのをお伺いしたいと思いますとの意見を述べました。","respondent":"吉岡政策推進担当課長","answer":"屋上緑化の件も含めまして、緑を増やしていきたい、そういった施設にしたいというところでの委員の皆様からのご意見を取りまとめたものです。こういった具体的な計画落としていく中で、適切に進められるよう、区のほうも努力していきたいと考えているところです。","id":"exchange-019"},{"speaker":"塚本委員","kind":"質問","question":"そうすると、ビオトープということで言うと、生き物を飼うということも一応念頭に入っているのか尋ねました。","respondent":"吉岡政策推進担当課長","answer":"ビオトープにつきましては、直接そこまであまり深掘りをされていない部分です。そういった展示会をしたいとか、そこまでの議論は深まっていない部分ではありますので、こちらは今後検討していきたいというふうに考えてあります。","id":"exchange-020"},{"speaker":"塚本委員","kind":"意見","question":"それと、あともう１つ、最後に適応指導教室というところで、不登校は今なかなか大変な課題になっているところです。今、進めていただくべきことだと思うのですけれども、議論の中身はどの辺まで詰められたものだったかというのをお聞かせいただければとの意見を述べました。","respondent":"吉岡政策推進担当課長","answer":"こういった施設の機能を活かして、こういった不登校児童・生徒が活躍できる、来ていただける。そういった場を目指していきたいというふうに考えてあります。","id":"exchange-021"},{"speaker":"松永委員","kind":"質問","question":"少年野球であればネットを使ったりとか、移動式のネットにするのか、その辺も伺いたいと思います。可搬ポンプを使うことができるのかどうかというのと、土だったら多分できるとは思うのですが、その辺を伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"松永委員","kind":"質問","question":"東急大井町線、恐らく高架になると思うのですが、その辺のセットバックとかは関係が出てくるのかどうかというのをお知らせほしいと求めました。すごく危ないので、何かそういった対策とかも含めて考えていただければと思うのですけれども、ご意見を伺いたいと思います。","respondent":"吉岡政策推進担当課長","answer":"高架下のところもありますので、今後基本計画の中で、人の流れ、交通の流れ。そういった部分も確認しながら基本計画の中で、安全にこの施設を使用していただけるように努めてまいるところです。","id":"exchange-023"},{"speaker":"せお副委員長","kind":"質問","question":"そして、様々議論伺っていました。そういった２点、今あるのかどうか、お聞きしたいです。","respondent":"吉岡政策推進担当課長","answer":"述べさせていただいたとおり策定委員会のほうがつくった素案、これを基に今後区が方針を固めて、基本計画を策定していくです。今後の検討になりますけれども、各所管と連携を取っているというところだけ、お伝えさせていただければと思います。","id":"exchange-024"},{"speaker":"せお副委員長","kind":"意見","question":"同じようなものが同じ地域に２つあるとか３つあるとか、私が気づくのが少し遅れてしまったなと思ったのですが、そういったところもぜひ全体のバランスを検討ほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-025"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうした官民癒着の拡大などにつながるような内容ならば、進めるべきではないということを一言申し上げておきたいと思います。その上で、マイナンバーカードがなければ行政サービスが受けられないという仕組みにはすべきではないと思うのですけれども、伺いたいと思います。","respondent":"河西情報戦略担当課長","answer":"マイナンバーカードが利用できる手続もありますが、マイナンバーカードを利用せずとも利用できる手続もあります。従来どおり免許証のコピーですとか、マイナンバーカードがないと利用できないかというと、そうではないということでご報告いたします。","id":"exchange-026"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"もうけの種になっていく、進めないようにということを求めたいし、そういう仕組みにはしないでいただきたいということを言っておきたいと思います。このスライドの９で、以前からも伺っていることを改めて伺いたいのですが、伺いたいと思います。","respondent":"河西情報戦略担当課長","answer":"改めて認識を共有しますと、デジタルを業務に取り入れることによって、質の向上という側面が非常に強いと思っています。これが第一だと考えております。","id":"exchange-027"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"それとともにこれまではそういったＤＸを進めることで、その考えは今も変わらないということで、いいでしょうか。人員削減ありき、行政コスト削減ありきのデジタル化は、改めてやめるように求めたいと思うのですけれども、いかがか尋ねました。","respondent":"河西情報戦略担当課長","answer":"ＤＸ推進基本方針には、ＤＸを進めることによって、そのとおりということでご回答します。","id":"exchange-028"},{"speaker":"石田（ち）委員","kind":"質問","question":"この新テレワークの導入も示されていまして、テレワーク利用促進については、数値の目標というのがあるのかどうか。拡大ありきではなくて、実態や必要に応じて進めていくべきだと思うのですけれども、いかがか尋ねました。","respondent":"河西情報戦略担当課長","answer":"これを向上する１つの手段として、区が提供すると。うまく職員が各所管のほうで工夫して利用できるように、環境を整えるという意味で、拡大のほうをしてまいります。","id":"exchange-029"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"分かりました。改めて、テレワークにおいては、推進ありきではなくて、仕事の実態や職員の要望に応じて進めるように求めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"山本委員","kind":"質問・要望","question":"できそうかどうかというところについて、お伺いしたいと思います。もしくは持ち帰った自宅の中では見られないとか、そういった対策などがおありでしたらぜひ伺いたいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"山本委員","kind":"質問・要望","question":"１５ページのスライドでご説明いただいた、１点確認をさせていただきたいのが、それがテレワークで自宅でも見られるような状況なのでしょうか。確認させてください。","respondent":"河西情報戦略担当課長","answer":"品川区役所は、３つのネットワークで構成されております。ですので、基本的にはマイナンバー系、個人情報、そういったものが扱えない端末を持ち帰って利用するということで、ご報告します。","id":"exchange-032"},{"speaker":"山本委員","kind":"質問・要望","question":"多くの方々が利用できるようにしていただきたい、使いやすい仕組みにしていただきたいという、これは要望です。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"あくつ委員","kind":"確認","question":"接続ルートの隔離、本人性の確認ということであるのですけれども、本庁のほうのＬＧＷＡＮというところにアクセスができないよと。本人確認というのは、何をもって本人確認をするのか。","respondent":"河西情報戦略担当課長","answer":"そのときのＳＳＩＤ認証というのを実施しております。この３つを合わせることで、知識と物がないと接続できないというところを担保して、セキュリティの確保を実施しております。","id":"exchange-034"},{"speaker":"あくつ委員","kind":"確認","question":"今おっしゃっていたような３つの認証があって、本人認証とか本人性の確認というのは突破できない、何かそういう仕組みなのでしょうか。もう１回説明を求めました。","respondent":"河西情報戦略担当課長","answer":"ですので、先ほどご説明したとおり、２要素認証という仕組みを使って、ＩＤパスワードプラス端末、あとモバイルルーター。この３つがセットでないと接続できないというところまでセキュリティの担保をしようというところになっております。","id":"exchange-035"},{"speaker":"あくつ委員","kind":"質問","question":"モバイルルーターというのは、これは説明で多分あったのかもしれないのですけれども、モバイルルーターも一括して貸し出すということなのでしょうか。それはもう間違いないということなのか尋ねました。","respondent":"河西情報戦略担当課長","answer":"ただし、そうなってしまうので、我々日頃からセキュリティに関する研修を実施しております。そういったところを徹底しておりますので、そういったところと併せて、新テレワークシステムの運用をしていこうというふうに考えております。","id":"exchange-036"},{"speaker":"あくつ委員","kind":"質問","question":"本人の顔とか網膜とか指紋とか。そういったものでの、それがなければ突破できないというような、そこまでは今回はつくらないということなのか尋ねました。","respondent":"河西情報戦略担当課長","answer":"先ほど生体認証というお話がありましたが、こちらもシステムを設計する際に議論の１つになりました。今回は外から接続しますので、生体認証は使うのが難しいという回答になりまして、ＩＤとパスワードにしています。","id":"exchange-037"},{"speaker":"あくつ委員","kind":"確認","question":"今、生体認証は難しいということでした。これは人間だから起こり得る、起こり得る可能性があるということですが、限りなく情報の流出は低いのだろうなというところで確認させてきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"えのした委員","kind":"質問","question":"品川区電子申請サービスの利用状況を見ても、訪問者数、申請数、順調に伸びているということで、１９時以降仕事が終わってからですかね。チャットボットはすごく分かりやすいよとか使い勝手がよかったとか、何かそういうような声があれば教えていただけますか尋ねました。","respondent":"河西情報戦略担当課長","answer":"品川区電子申請サービスの使い方が分からないなどの対応について。それに回答できるような仕組みというのが出てきておりますので、その結果次第、どんどん取り入れるものは取り入れていきたいと考えております。","id":"exchange-039"},{"speaker":"山本委員","kind":"質問","question":"シニアスマホ教室は高齢者地域支援課ですか。こちらのところについてもご見解や、もし今進める予定があれば、そういったところを教えていただければ幸いです。","respondent":"河西情報戦略担当課長","answer":"今の高齢者地域支援課のほうでシニア教室を実施しておりますが、ある地域のある特定の方に限られてしまうというのがどうしても課題としています。そちら、我々のほうでも研究してまいりたいと思っています。","id":"exchange-040"},{"speaker":"山本委員","kind":"質問・要望","question":"それから、一般質問やこれまでの議会でも申し上げていますように、工夫をしながら数を増やせる取組についてもご検討いただきたいというところ。それらぜひ進めていただきたいということで、要望として終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/642035?Template=document&Id=6160#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":36725,"voices":111}},{"id":"r05-20231130-19","meetingId":"r05-cm11","date":"2023年11月30日","dateIso":"2023-11-30","committee":"災害・環境対策特別委員会","time":"午前１０時００分～午後 １時４３分","status":"正式会議録","sourceType":"formal","overview":"災害・環境対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を32件整理しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"令和３年度では２５％ということで、この資源化率というものは、どういった値なのかというところをご説明ほしいと求めました。先ほど新しい項目を増やしていくということで、今回それも拡大していくということだったのですけれども、いかがか尋ねました。","respondent":"品川品川区清掃事務所長","answer":"国の法律の流れですけれども、そうですね、図のほうでご説明しているリサイクル率が上がる部分の時期に、様々なリサイクル法ができております。先ほど少し説明したとおり、やはりここを伸ばしていく策をこれから取り組んでいかなければいけないと、このように思っております。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問・要望","question":"進めていっていただきたいと思うのですけれども、資源回収は若干減ってきている中で横ばいという感じで、集団回収は少し減ってきていると。拠点回収のところでは少し増えてきているのですか、資源、区としてはどのようにお考えなのか伺いたいと思います。","respondent":"品川品川区清掃事務所長","answer":"資源化率はやはり一定傾向はあるのですけれども、資源で出される量については、多分人口に比例して徐々には増えてきているのかなと考えています。通販ですか、そのようなものが増えて、やはり段ボールの量などは意外と多くなっている傾向はあるのではないかなと考えています。","id":"exchange-002"},{"speaker":"のだて委員","kind":"質問・要望","question":"それをさらに進めていってほしいと求めましたが、何か具体的な取組、考えていらっしゃることがあれば伺いたいと思います。この実績や、やってきた中での課題というものは、あれば伺いたいと思います。","respondent":"品川品川区清掃事務所長","answer":"６月から進めているところですが、あまり区民の方から反対意見などといったものが出ない説明会も本当珍しいなというような印象を持っております。","id":"exchange-003"},{"speaker":"のだて委員","kind":"質問・要望","question":"そういったところでも、区としても発信をしていっていただきたいと、これは要望しておきたいと思います。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"吉田委員","kind":"確認","question":"この古紙の中に平成３０年度から雑紙が入っているのかどうか伺いたいと思います。それから、よく学校やＰＴＡが回収しているのは、この集団回収のほうに含まれて実績が出ているのか、その３点伺います。","respondent":"品川品川区清掃事務所長","answer":"それからＰＴＡについては、若干そのＰＴＡの団体にもよると思います。ちょっとＰＴＡの回収については、時と場合によってはこの集団回収の部類に入っていないものもあるのではないかと考えています。","id":"exchange-005"},{"speaker":"吉田委員","kind":"質問","question":"そのようなことがないのであれば、何かもう少し工夫したほうがいいのではないかなと思うのですけれども、その点についていかがでしょうか。すごい」と思ったのですが、みんな知らないと言うので、どのような配られ方だったのかなと思って伺いたいと思います。","respondent":"品川品川区清掃事務所長","answer":"事業を開始してから、伸びてはいるのですけれども、ちょっと全体としての効果としてはなかなか見えづらいところはあります。製品プラスチックの説明会のほうですが、全戸配布をしているつもりなのですけれども、多分ちょっと一部に漏れがあったのかなと考えているところです。","id":"exchange-006"},{"speaker":"吉田委員","kind":"質問・要望","question":"ですから、周辺でいうと配られていないというお答えのほうが多いので、その辺どうして配られなかったのか、調べていただけたらと思います。その辺、庁内での徹底といいますか、そのようなものはできているか、今後どのようにしていくか伺いたいと思います。","respondent":"河内環境課長","answer":"まだお時間がかかって本当に申し訳ないのですが、しっかり取組を進めてまいりたい方向で、今も進めているところです。今後ともよろしくお願いします。","id":"exchange-007"},{"speaker":"吉田委員","kind":"質問・要望","question":"とても危機感あおって、本当に全体で進めていかなければいけないことだということを、ぜひ徹底してほしいと求めました。これはもう強い要望で終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"この回収に立ち会っている方々というものはどういった方々が対応なされているのかということを、この点についてお聞きしたいと思います。最後に、その中で、回収後に新たに見えてきた問題点や課題などがあれば教えてもらいたいと思います。","respondent":"品川品川区清掃事務所長","answer":"１点目、啓発講座のほうですけれども、すみません、少し説明不足がありました。そのようなところは必要ではないかとも考えております。","id":"exchange-009"},{"speaker":"ゆきた委員","kind":"質問","question":"来年の４月から区内全域で実施されてからでは、方向の変換等はこの先かなり難しくなってくるとも思われます。改めて、各家庭の回収の仕方で改善できることがあればと思いますけれども、その辺についてもう一度お聞きできればと思います。","respondent":"品川品川区清掃事務所長","answer":"担当者というか、そこの委託業者のほうの声としては、まだ負担までいくところではないというようなことはお話としては聞いております。今後確立されていくのではないかなというような考え方もありますし、ちょっと対応のほうは考えていきたいと、このように思っております。","id":"exchange-010"},{"speaker":"ひがし委員","kind":"提案","question":"以前も提案させていただいたかもしれないのですけれども、新しく令和６年１月から変わりますというところも、何か課題などがあれば教えていただきたいですとの意見を述べました。","respondent":"品川品川区清掃事務所長","answer":"現在非常に詳細に研究を進めておりまして、そのようなアプリやチャットについても、研究の中でも把握をしているつもりです。今後また区民の方に使いやすいような形で、アプリやチャットのほう、何とかやっていきたいように進めていきたいと考えております。","id":"exchange-011"},{"speaker":"澤田委員","kind":"質問","question":"今ひがし委員が質問されたことも、私もちょっと気になっていたのですけれども、以前予算特別委員会で、ＡＩチャットボットどうでしょうかということを質問しましたが、今まだ検討中というか、いろいろ調べていただいているところなのか尋ねました。","respondent":"品川品川区清掃事務所長","answer":"委員のおっしゃるとおりで、現在研究をしているところで、いろいろと物事を進めるためには、自治体の中では予算というハードルもありながら、そのようなところを越えていくように、日々努力をしているというような状況です。","id":"exchange-012"},{"speaker":"澤田委員","kind":"質問・要望","question":"別の質問なのですけれども、今のは要望で、すみません、リサイクル通信の発行部数が今約１万３,０００戸で、全戸配布ではないのではないですか。１０月２０日がリサイクルの日となっているようなのですが、年４回の発行日に、どうか尋ねました。","respondent":"品川品川区清掃事務所長","answer":"何か啓発方法は随時考えていきたいと思いますので、１つの案として、こちらも参考にしてやっていきたいと考えています。","id":"exchange-013"},{"speaker":"澤田委員","kind":"質問","question":"今後、ほかの中学校で行われる予定はあるのでしょうか。いかがか尋ねました。","respondent":"河内環境課長","answer":"こういった取組について非常に重要かというように、認識は一致しています。こういった要望があれば、環境課、そういった方向で考えているところは今も変わりありません。","id":"exchange-014"},{"speaker":"澤田委員","kind":"質問・要望","question":"ということは、この学校側などから要望がないと、特にやっていないということなのか尋ねました。","respondent":"河内環境課長","answer":"企業連携ではないのですが、こういったことが広がっていけば、非常に食品ロスも進むのではないかなと考えております。そのような機会を捉えて、しっかりやっていきたいと考えています。","id":"exchange-015"},{"speaker":"こしば委員","kind":"確認","question":"確認の意味も込めてお聞きしたいのですけれども、これまずは１万か所以外のところでの資源回収というものはされておるのかしていないのか、まずそこの確認だけさせてください。","respondent":"品川品川区清掃事務所長","answer":"すみません。ちょっと説明があれでしたけれども、そこの資源ステーションというものは、週１回回収している場所のことを示しています。","id":"exchange-016"},{"speaker":"こしば委員","kind":"質問","question":"そういったところでどうしても、分かっていない人はどうしても、古紙だけを持っていくのです。その辺の回収車両への影響含めて、どういったように見込んでおるのか、ちょっと教えてほしいと求めました。","respondent":"品川品川区清掃事務所長","answer":"全体的に大体４００トンぐらいかなというところで、車の台数は増やさなくてもいけるのではないかという試算の下で、収集のほうは行っている状況です。状況が変わり次第、車のほうについては対応していこうかと考えています。","id":"exchange-017"},{"speaker":"こしば委員","kind":"意見","question":"でもそれはそれで１つの取組として、そして企業が連携していって、リサイクルに力を入れていくということは大変すてきな試みだと思うのです。その辺との連携について、現状も含めて、今後についてのお話をほしいと求めました。","respondent":"品川品川区清掃事務所長","answer":"やはりどうしても各企業、自社製品のものを回収というような形で、いろいろ実験をしているような動きは出てきているかなと考えています。活用できる部分についてはいろいろと研究をしていって、実行できるものは実行していきたいと、このように思っております。","id":"exchange-018"},{"speaker":"こしば委員","kind":"質問・要望","question":"そうですね。企業もやはりどうしても利益を求めるので、ここからまた。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"西村委員","kind":"質問・要望","question":"今日まさに地元が資源ごみの日でして、今のこしば委員の質問にもありましたけれども、資源ごみの出し方についてちょっと伺いたいなと。以前も伺ったことあるのですが、缶で分かれた黄色と青の箱がありますが、そこからあふれているものをよく見かけております。","respondent":"品川品川区清掃事務所長","answer":"そういったところも日々対応したりなど、やはりまちの美化などを考えると、そのようなスタンスで進めているところです。今考えるところでは、個別のところに積極的に声をかけて、なるべく解消をしていこうというような形で現在は進めているという考え方でやっております。","id":"exchange-020"},{"speaker":"新妻委員","kind":"質問・要望","question":"様々、今の委員の話も聞いている中で、やはりそのリサイクルという意識が高まってきているのだろうなということは感じております。ちょっとまず１点、最初に確認させていただきたいことが、評価をどうされているのかというところをちょっとお聞きしたいと思います。","respondent":"品川品川区清掃事務所長","answer":"区の庁舎のほうのリサイクルのお話ですが、原則的には清掃事務所は家庭ごみを中心にやっていくというスタンスを取っております。清掃事務所のほうもいろいろと対応しているところがありまして、一般家庭と同様な形で分別のほうを進めて、このように思っております。","id":"exchange-021"},{"speaker":"新妻委員","kind":"質問・要望","question":"今後、区としての検討をされている中で、この２つに関してどのようなことを検討されているのかということをお知らせほしいと求めました。品川区としてやっていただきたいと思うのですが、そのようなご検討や、またお考えをお聞きしたいと思います。","respondent":"品川品川区清掃事務所長、河内環境課長","answer":"こちらをうまく、何かこう活用してできないかなというところで、現在は進めているようなところがあります。先行自治体もありますので、そのようなところの事例も参考にしながら考えていきたいと、このように思っております。区民の利用しやすさという点で連携、オイシックスはやはり給食事業者ですので、食の大切さを非常に知っている業者というように認識しています。","id":"exchange-022"},{"speaker":"須貝委員","kind":"質問","question":"一定期間でもいいですから、１か月間ちょっとやってください、そのとき一緒に見られるというような対応も大事なのかなと。見せるような工夫をしてやったらどうかなと思うのですけれども、ちょっとその辺、ご見解を説明を求めました。","respondent":"品川品川区清掃事務所長","answer":"先ほども説明したとおりパトロールの職員などが個別に対応するというような状況もありますし、対応していかなければいけないかなとも思っております。啓発のほうはやはり引き続き進めていって、これからも努力していきたいと、このように思っております。","id":"exchange-023"},{"speaker":"須貝委員","kind":"質問・要望","question":"ここでちょっと２点だけお伺いしますが、太陽光パネルというものが３０年たつと寿命が来るという話を聞いています。やはりもう１点、どうしても若者は大きな気持ちでバンと買ってバンと捨てるということも多々あるのではないかと思うので、説明を求めました。","respondent":"河内環境課長","answer":"特に次世代を担うお子さん方にそういった現実をしっかりお伝えすることによって、こういったものの是正についてやっていければなと考えています。そういったところを踏まえまして、こういったところの改善方向に、区としてしっかり取り組んでいきたいという考えです。","id":"exchange-024"},{"speaker":"せりざわ委員","kind":"提案","question":"せっかくまちの人は資源にしてほしい、リサイクルしてほしいといって集めて、ステーションに出していくわけですから。この２つ、お話をお伺いできればと思いますとの意見を述べました。","respondent":"品川品川区清掃事務所長","answer":"単価が教育委員会の大体見込み、やっている実績ですと、キロ２０円ぐらいになるのです。ただ、資源ステーション１万か所ありますので、どこまでやればというところも含めながら、１つの対策として参考にさせていただきたいと考えています。","id":"exchange-025"},{"speaker":"せりざわ委員","kind":"質問・要望","question":"資源ごみのところの１万か所あるという話はあるのですが、ただ、そこに対して何かプラスアルファで活用していただきたいなと思っています。やはりまず今の拠点回収の段階で持ち去っているかどうかをしっかり、やはり罪は罪ですから、今のうちに取り締まるということに強く要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"つる委員","kind":"提案","question":"ですから、いわゆる区民運動としてどう全体を動かしていく、今申し上げた広報の工夫など。ですから、ぜひそのような広報の工夫や、区民運動をどう今後持っていくかということを、ちょっと全体の話で教えてほしいと求めました。","respondent":"河内環境課長、品川品川区清掃事務所長","answer":"食べることは皆ずっとやめることがありませんので、そういった形でぜひ考え方を整理しつつ、今後も進めてまいりたいと思います。答えになっているかどうか分かりませんが… 広報のほう進めていけることが一番理想かと思いますので、既存のもので、やはり継続してやっていくというところが非常に大事かと思います。","id":"exchange-027"},{"speaker":"つる委員","kind":"質問・要望","question":"ですから、そのような工夫というところをまさにやっていただきたいなと思います。ぜひ、今の広報の工夫、これはぜひもったいなくならないようにやっていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"鈴木副委員長","kind":"質問・要望","question":"この説明会というものは、啓発というものは、この説明会の中にどのように位置づけられているのかを伺いたいと思います。ぜひその啓発の中に入れていただきたいなと思っているのですけれども、だからこそこれを進めたいというあたりは、その点１点伺いたいと思います。","respondent":"品川品川区清掃事務所長","answer":"随時そのような点で、ＣＯ２の部分などというところも機会あるごとに説明をしていきたいと、このように思っております。当然プラスチックは、多分普通の可燃ごみの中でも、ＣＯ２発生量は非常に多いものですので、そういった点も説明していこうかなと考えています。","id":"exchange-029"},{"speaker":"鈴木副委員長","kind":"質問・要望","question":"もう一つ伺いたいことは食品ロスのことなのですけれども、これ何とかならないのですかというようなことで伺ったことがあるのです。そのようなことがあるので何とかならないかということで伺ったこともありまして、今後の方向性として、いかがか尋ねました。","respondent":"平原防災課長","answer":"今、災害備蓄品の廃棄のお話がありましたので、私のほうからお答えします。災害備蓄品を管理し、しっかりやっていきたいと思いますので、よろしくお願いいたします。","id":"exchange-030"},{"speaker":"鈴木副委員長","kind":"質問・要望","question":"何というのですか、そのようなものがあるのかどうなのかというようなところは清掃の方にも聞いていただいて、つかんでいただけたらなと思います。困っている方にとってはすごく助かるものなので、そのようなご活用も含めてご検討いただきたいということで、要望させてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"}]},{"id":"topic-02","title":"環境学習動画","agenda":"環境学習動画","exchanges":[{"speaker":"つる委員","kind":"確認","question":"ごめんなさい。１点だけ確認は、当然内容など充実されているのでしょうけれども、そのようなことでいいのか説明を求めました。","respondent":"河内環境課長","answer":"紙冊子ですが、電子化することによりまして、利用される分母の計算も、そちらの部分につきましては、全て電子化によりまして展開を予定しております。","id":"exchange-032"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/924121?Template=document&Id=6646#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=19&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":46042,"voices":91}},{"id":"r05-20231130-10","meetingId":"r05-cm11","date":"2023年11月30日","dateIso":"2023-11-30","committee":"議会運営委員会","time":"午後 ０時４５分～午後 ０時４７分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/881920?Template=document&Id=5526#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":1361,"voices":8}},{"id":"r05-20231205-10","meetingId":"r05-cm12","date":"2023年12月5日","dateIso":"2023-12-05","committee":"議会運営委員会","time":"午前１０時３０分～午前１１時４０分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を27件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"実質的な審議をやるものですから、区民の皆さん、とりわけ請願や陳情を出した方にとってはかなり関心が高いものだと思います。共産党としては、これはやるべきなのではないかなと思っているというところで、皆さんのご意見をお聞かせほしいと求めました。","respondent":"あくつ副議長、大澤区議会事務局長","answer":"副議長としての発言なのですけれども、確認させてください。今、本会議場では傍聴者によるＳＮＳでのライブ配信は認められているというお話があったのです… 録画を許可するということで、この後の配信については制限をしていないということで、許可をしているという考え方ではございません。 録画は認められている。そのまま流すかどうかは、議会として許可をしているということではないということは確認させていただきました。","id":"exchange-001"},{"speaker":"須貝委員","kind":"質問","question":"ライブ配信ですか、利用できるようなときがきたら、少しずつ進めていくべきものだと私は思います。意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"山本委員","kind":"確認","question":"やはり区議会が発信して、確認することができる状態にしておくことは、十分に考慮する必要があるというふうに考えております。陳情第４７号については……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問","question":"そこら辺についてもクリアできるのではないかというふうに思いますけれども、皆さん、そこら辺はどうですか。スペース上、問題があるとか、ちょっと厳しいのではないかとか、そういった点についてはどうか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"山本委員","kind":"確認","question":"その中で、正しいものは何かということが確認できる状況にしておくことは、とても大事であると思います。これと併せて予算特別委員会、決算特別委員会についても傍聴者の皆様のライブ配信も考えていくべきであるというふうに考えております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"須貝委員","kind":"確認","question":"それから傍聴できる場所があるかどうかを確認した上、そちらのほうで十分審議されて、今後のことを考えられたらいいのではないですか。今は時期尚早ではないかなというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"安藤委員","kind":"提案","question":"私は個人的にもかなりこの問題は打開すべきだなということで、何回か提案もさせていただいていたのです。質問があるのですが、特に規定というのはないということでよろしかったのか、ちょっとそこだけ確認させてもらえますかとの意見を述べました。","respondent":"大澤区議会事務局長","answer":"委員会は委員会室でやらなければいけないという規則はございませんけれども、どこでやるかというのは議会運営委員会の中でその都度確認しているものだと認識しています。","id":"exchange-007"},{"speaker":"安藤委員","kind":"提案","question":"品川区の場合は、すばらしいことにほぼ全議員でやっているということですから、物すごく合理的な提案ではないかなと私も思っています。区民の皆さんがこれだけ議会の議論に関心を持っているということなのですから、それに応えるべきなのではないかなというふうに私は思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-008"},{"speaker":"塚本委員","kind":"質問","question":"まず区としてオーソライズされた同時配信がなされていない現状において、先にそういうものだけを許可していくことは弊害のほうが大きい。他自治体でも同じようなことがあったりもしていますし、そういうふうに捉えておりますので、不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"安藤委員","kind":"提案","question":"本日結論を出して、採択を主張します。特に委員会の中継を強く求める区民の皆さんの提案ということもありますので、すごく議会改革につながると私は思いますので、採択ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-010"},{"speaker":"須貝委員","kind":"意見","question":"私は、これは賛成なのです。物理的な問題とかが様々あるので、そちらの場所で皆さんで検討されて、最後に議会運営委員会で決められたらいいのかなというふうに思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"},{"speaker":"塚本委員","kind":"意見","question":"結論は不採択でお願いいたします。ちょっとリアリティに欠けるかな、いろいろ弊害があるかなというところで、不採択としたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-012"},{"speaker":"安藤委員","kind":"意見","question":"今あるものを使って、何よりも傍聴したいという区民の皆さんの議会への関心にしっかり応えていくということになると思いますので、採択をしたいと考えていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-013"},{"speaker":"須貝委員","kind":"意見","question":"私も本日結論を出すということと、不採択でお願いします。これも第４６号と同様に、最後、議会運営委員会で決められたらいいかと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-014"}]},{"id":"topic-02","title":"議会運営上の変更","agenda":"議会運営上の変更","exchanges":[{"speaker":"須貝委員","kind":"意見","question":"議会運営委員会の中で、こういう申出があって、こういう状況なので議席を変更しましたというふうなことをちゃんと残しておくべきだと思うのです。そうしないと、今後勝手にどんどん移動できることになってしまうので、その辺、委員長はどう思われますかとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"},{"speaker":"松永委員","kind":"質問・要望","question":"この間は椅子に座って一般質問させていただいたのですが、ぜひそうしていただきたいということで、今回このような形で皆さんにご報告をしています。ぜひご理解ほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"}]},{"id":"topic-03","title":"令和５年第４回定例会","agenda":"令和５年第４回定例会","exchanges":[{"speaker":"安藤委員","kind":"提案","question":"賛成ですが、その上でさらに充実した決議にするために、内容について一部修正を提案させていただければと思うのです。この資料を配付させていただきたいのですけれども、委員長、よろしいか尋ねました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-017"},{"speaker":"安藤委員","kind":"提案","question":"今提案させていただいているとおりなのですが、１行目の部分を少し修正して、よりよい内容の決議になるのではないかという提案です。いかがか尋ねました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-018"},{"speaker":"高橋（伸）委員長","kind":"提案","question":"委員長としては、お示しした案のとおりで、議案として提案したいので、よろしくお願いします。今のご発言に対して何かほかにご発言はありますか尋ねました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"},{"speaker":"須貝委員","kind":"質問","question":"やり過ぎ、どうだ云々となってくると思うのですけれども、そこは我々が文面で明記するものではないのかなという気がします。それはちょっと皆さんのご見解をお聞きしてと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"せりざわ委員","kind":"意見","question":"突然新しい修正案が今時点でぱっと示されて、この場でご理解くださいと言われても、それはちょっとやり方がずさんではないかと思っています。そもそもは即時停戦が目的だと思いますので、その意味で言えば、委員長案で進めていただいていいのかなと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-021"},{"speaker":"塚本委員","kind":"意見","question":"もう明日が本会議ですので、もしここでやると結構な変更だと思います。これはなかなかいけないという部分もありますし、物理的な時間の問題もありますので、委員長案で進めていただけるといいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-022"},{"speaker":"松永委員","kind":"意見","question":"私たちの会派といたしましても、先ほど塚本委員からありましたけれども、時間的な問題というのもありますし、あとはどちらが悪いというわけではなくて。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-023"},{"speaker":"安藤委員","kind":"提案","question":"過日私たちから提案させていただいたわけで、案文の提示がかなり直前だったもので、こういったやり方を取らざるを得なかった面もあります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-024"}]},{"id":"topic-04","title":"通年での服装軽装化","agenda":"通年での服装軽装化","exchanges":[{"speaker":"安藤委員","kind":"確認","question":"その他の(4)なのですけれども、例年２日間ぐらいに分かれていたような気がするのですが、１日で全部終わるのかということ、それと当日の説明資料を電子データでという話だったのか、そこら辺をちょっと確認させてください。","respondent":"大澤区議会事務局長","answer":"資料ですけれども、資料は説明の際に配付というふうに聞いてあります。当初予算プレス資料は今回からデータでのご提供ということになります。","id":"exchange-025"},{"speaker":"安藤委員","kind":"質問・要望","question":"どちらに要望すればよいのか分からないですけれども、２点ありまして、例年並みの時間は各会派取っていただければなという要望なのですけれども。そういった要望があるのですけれども、それは伝えてもらえますか尋ねました。","respondent":"大澤区議会事務局長","answer":"ご要望としてどちらかにお伝えすることはできます。","id":"exchange-026"},{"speaker":"須貝委員","kind":"質問","question":"今の件ですけれども、我々はもうタブレットのほうに、ペーパーレスでやっていかなければいけないと思うので、そういう方向で共産党にもご協力願ったほうが良いのではないか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/881920?Template=document&Id=5528#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":20144,"voices":95}},{"id":"r05-20231226-10","meetingId":"r05-cm12","date":"2023年12月26日","dateIso":"2023-12-26","committee":"議会運営委員会","time":"午前 ９時００分～午前 ９時３７分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を12件整理しています。","topics":[{"id":"topic-01","title":"令和５年第２回臨時会","agenda":"令和５年第２回臨時会","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"通常でしたら議案審査の２日前に資料をいただくのですが、今回は明日なので、できれば早めに補正予算議案の資料をいただければと思うのですけれども、そこら辺はいかがか尋ねました。","respondent":"桑村副区長","answer":"ご意見として受け止めしますが、一つは、議案説明会で一定の議案説明をしないうちに説明資料が公式にいくというのは、なかなか難しいのかと思います。","id":"exchange-001"}]},{"id":"topic-02","title":"会派変更届","agenda":"会派変更届","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"日本共産党品川地区委員会名で見解を発表し、本人にも事実確認したところ、全て事実と認めたことによるものであります。私たちとしては、当然、議員として職にとどまるべきではないと考え、本人に辞職するよう求めましたが、本人は受け入れませんでした。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"せりざわ委員","kind":"質問・要望","question":"念のため確認させていただきたいのですが、１３日と、会派としてご本人に確認をされたのでしょうかということが１点。そのご本人との確認の上で、今回の会派の離脱というか、変更に至っているのか、この２点を教えていただきたいのですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"安藤委員","kind":"確認","question":"本人と直接話して事実確認を行ったところ、全て事実と認めております。会派としても確認して、会派としても判断したです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"せりざわ委員","kind":"質問","question":"では、もう１点だけ。それに対して、会派から何か行動を起こすというようなイメージはあるのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"安藤委員","kind":"質問・要望","question":"議員辞職すべきだと強く思っておりますし、共産党としても、本人に繰り返し辞職を求めてきたところです。その際も、繰り返すようですが、二次被害を避けるという観点から、地区委員会の見解以上のことをお話しすることはいたしません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"須貝委員","kind":"意見","question":"今この場で話すべきかどうかは分かりません。私は、明確にこういう事実を相互に認めているということならば、議員辞職勧告決議案を品川区議会として提出するべきだと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"塚本委員","kind":"質問・要望","question":"これは事務局にお聞きしたいのですけれども、いわゆる過去の事例などで、何かこういった対応をとってきたということがあったりするのか。内規みたいなものがあって、こういう対応をとるように定められているみたいなところがあるのか、そこのところを教えてほしいと求めました。","respondent":"大澤区議会事務局長","answer":"品川区議会としては、過去にこのような事例はございません。規程も特には、今のところはないです。","id":"exchange-008"},{"speaker":"塚本委員","kind":"質問","question":"手法というのか、そういうものが、どういったものになるのかということが今の段階で分かれば説明を求めました。","respondent":"大澤区議会事務局長","answer":"ほかの議会の事例ですと、報道ベースではありますが、逮捕された場合に、辞職勧告決議案を提出しているというケースが散見されます。辞職勧告のほかには、不祥事には毅然と対応し、議会の信頼回復に努めることを誓う決議案を提出している場合がございました。","id":"exchange-009"},{"speaker":"塚本委員","kind":"意見","question":"とるべき対応は、本人から、区議会として弁明等を聞く機会も一定必要かなとも思います。いずれにしても、また新たな検討ということでは、何ができるかということを考えていく必要があるかと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-010"},{"speaker":"安藤委員","kind":"提案","question":"私たちから提案するということになりますと、そういうことに答えなくてはいけない状況になってしまうというのを懸念しているということなのです。見解以上のことを言うつもりはないのですけれども、提案者になるのかとか、少し考え直していますとの意見を述べました。","respondent":"あくつ副議長","answer":"我々が持っている情報は、共産党地区委員会なり、共産党区議団の今のご説明しかないのです。先ほど、その可能性は排除しないというお言葉もいただいたので、それはよくよくご検討いただきたいと思います。","id":"exchange-011"},{"speaker":"山本委員","kind":"意見","question":"当会派としても、今までの話を踏まえましても、議会として何らかの対策をとっていくべきではないかと考えておりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-012"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/881920?Template=document&Id=5530#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":12922,"voices":63}},{"id":"r05-20231227-6","meetingId":"r05-cm12","date":"2023年12月27日","dateIso":"2023-12-27","committee":"区民委員会","time":"午前１０時０７分～午前１１時１７分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を19件整理しています。","topics":[{"id":"topic-01","title":"第１０３号議案、令和５年度品川区一般会計補正予算（歳出等 区民委員会所管分）","agenda":"第１０３号議案、令和５年度品川区一般会計補正予算（歳出等 区民委員会所管分）","exchanges":[{"speaker":"山本委員","kind":"質問","question":"プレミアム付区内共通商品券事業についてお伺いします。それからプレミアム率を増加させたこと、それから前倒しにされたことというのはどういった意図や背景があるのかという、区の考えを説明を求めました。","respondent":"小林商業・ものづくり課長","answer":"これを踏まえまして各種統計を見ますと、消費支出につきましても、直近、今年度に入ってやや消費支出も落ち込んでいるような傾向があります。かつプレミアム率も大きく増やすとやはり消費喚起も大きくなるというところで、そういうことを目的として今回事業を実施するところです。","id":"exchange-001"},{"speaker":"山本委員","kind":"質問","question":"金額、プレミアム率が増加し、そして緊急性もあるということで前倒しをされていると理解いたしました。これまでの利用実績の中で、品川区在住の方がどれぐらい使われているのかというのが、もし分かるようでしたら教えてほしいと求めました。","respondent":"小林商業・ものづくり課長","answer":"本事業につきまして、区民の利用実績ですけれども、区内在住に限らず区外の方もご購入いただけるというような形にしております。そのことを通じまして、商店街などでたくさん消費をしていただくというようなことを目的としている事業です。","id":"exchange-002"},{"speaker":"山本委員","kind":"質問","question":"その中で、区民の方がどれだけ使われているのかということ、買われているかということを把握したいとお聞きした次第です。これは申込のときに分かるのかどうかというところも含めて、ご回答ほしいと求めました。","respondent":"小林商業・ものづくり課長","answer":"そのアンケートにご回答いただいた方につきましては、あるいは住所別の購入予定者が分かるわけですけれども、ちょっとそこまでは。実際に住所別の購入予定者がどういうところにいらっしゃるかというと、世田谷区、大半は区内の方ということで把握しています。","id":"exchange-003"},{"speaker":"山本委員","kind":"質問・要望","question":"やはりこういった実態というのはしっかりと確認していったほうが、区民の方がしっかり使われているのかどうかという確認を。実施が６月から７月頃を予定ということで、それと比べると、どういった工程があってこの時期になるのかというのを教えていただきたいです。","respondent":"小林商業・ものづくり課長","answer":"８番目のご質問の、ポイント還元額が５億円で、効率的な予算執行を進めてまいりたいと考えています。令和４年度に実施した場合でいきますと、その中で、消費喚起につながっているのではないかなと分析しているところではあります。","id":"exchange-004"},{"speaker":"山本委員","kind":"質問・要望","question":"それとも今後選定されるのでしょうか。そうすると、そういった契約体系なのかどうかというのを教えていただきたいです。","respondent":"小林商業・ものづくり課長","answer":"議会の議決も経て実施に至っているということを確認しておりまして、また我々品川区だけではなくて、ご理解いただければと思ってあります。これから議決いただいて調整ですので、まだ現時点で具体的にどうするかというところは、これからの検討です。","id":"exchange-005"},{"speaker":"山本委員","kind":"質問・要望","question":"それから、楽天ペイ利用率５０％ということについても、やはり紙と比べると利用率が少ないのかなと。世田谷区、そういったところについて検討をしていただきたいということで、これは要望で質問を終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"えのした委員","kind":"質問","question":"私からは１点だけ。この周知方法として毎回周知をどうするかというのはありますが、利用を促す、それをこれからどうお考えなのかというのを伺いたいと思います。","respondent":"小林商業・ものづくり課長","answer":"そういう方に対するサポートをどう予定しているかですけれども、我々としましては、利用方法の説明をやっていただけるような形にしております。","id":"exchange-007"},{"speaker":"えのした委員","kind":"意見","question":"やはり周知もすごく重要なのですが、区民の方へより丁寧なアドバイスではないですけれども、それをお願いしたいです。支払に関してはやはりまだまだ利用されている方が少ないと思いますので、そこら辺の取組も今後進めていってほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-008"},{"speaker":"あくつ委員","kind":"質問・要望","question":"その上で確認させていただきたいのですが、東京都のほうでもＱＲコード決済ポイント還元事業をやるという報道が先日ありました。先ほども山本委員の質問でありましたが、繰越明許費は先ほどご説明のあったとおり、区はどう考えているのかということを確認させてください。","respondent":"小林商業・ものづくり課長","answer":"区の事業、両方合わせるような形で区内経済の活性化を進めていければということで、なるべく連続してというところを意識して実施するものです。","id":"exchange-009"},{"speaker":"あくつ委員","kind":"質問","question":"大丈夫だとは思うのですけれども、国のほうはこの補正予算ですから、本来であれば年度内で消化というか、それを使わなければいけない。繰越明許費でも来年度もいいのですよということで、これは大丈夫なのか尋ねました。","respondent":"小林商業・ものづくり課長","answer":"今回、都の支出金という形で入れるのが、紙のプレミアム付区内共通商品券事業のほうですけれども、こちらは企画部にも確認をして、こういったような予算執行で問題ないかというところで調整して、今回実施するものです。","id":"exchange-010"},{"speaker":"あくつ委員","kind":"質問・要望","question":"我々も要望していたことですからありがたいと考えていますが、スキームについてはまた私たちも研究していきたいと思います。私はどちらかというと大きいのかなと考えているのですが、例えば、利用可能な店舗を増やしていただくということはできないのか尋ねました。","respondent":"小林商業・ものづくり課長","answer":"中小店舗を中心に、やはり一番消費、売上が落ち込んでいるようなところを含めて下支えということで考えているところです。事業者、利用者両方ということではありますが、そういうところに目を配りながら実施してまいりたいと考えています。","id":"exchange-011"},{"speaker":"あくつ委員","kind":"質問・要望","question":"首をかしげていらっしゃる委員もいますが、これは私としてはどちらかというと、ほかの自治体を見たときにコンビニで使えるところもあります。分析をしているのであれば、ぜひ何か区民・利用者のニーズに応じた拡大をしていただきたいということを要望して、終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"藤原委員","kind":"質問","question":"プレミアム付区内共通商品券についてお伺いしますが、今回内容がよく分からないのですけれども、これは１冊１万円で、１人１冊しか買えないのですか。買える範囲というのはどうなっているのか尋ねました。","respondent":"小林商業・ものづくり課長","answer":"まずそこを利用者の方にきちんとご理解いただいた上でやっていただくような、恐らくそういった同じやり方で進めていくことになるかと考えています。春の場合はもう少し人気があって最大２冊ぐらいまでという形で、品川区商店街連合会のほうでやっていただいているような状況です。","id":"exchange-013"},{"speaker":"藤原委員","kind":"質問","question":"区民への施策ですから、まずは区民の申込希望を優先して、その後にという思いが私の気持ちの中にはあるのです。まず区内の方を優先していくというのが基準でないとという思いがあるのですけれども、その辺についてはいかがか尋ねました。","respondent":"小林商業・ものづくり課長","answer":"今回実施する令和６年度春季分も同様の仕組みの中で、また利用実態を先ほど少しご説明差し上げたときに、アンケートから見えてくる実態としましては。品川区でこういった商品券ですとかキャッシュレス決済でやっている事業のプレミアム率で一番高いのは、３０％です。","id":"exchange-014"},{"speaker":"藤原委員","kind":"質問・要望","question":"他自治体では２０％ではなくて３０％、そういうことをしっかり押さえていかないといけないと私は思うのですけれども、いかがですか。書ける情報というのは、私はやはり書いておいていただきたいと思うのですけれども、その辺についてはいかがか尋ねました。","respondent":"小林商業・ものづくり課長","answer":"記載内容につきましてはより中身について、次回またこのようなご説明、あるいは別の事業につきましても気をつけてまいりたいと考えております。そういうものを踏まえまして、また今後どのように実施していくかというのはよくよく情報を集め、勉強していきたいと考えております。","id":"exchange-015"},{"speaker":"藤原委員","kind":"質問","question":"何で品川区は２０％なのかと聞かれたときに、私たちも議員ですから、聞かれたときにちゃんとした話を地域に持っていかないといけないわけです。だから、その辺についてしっかり教えてくださいと質問しているので、品川区商店街連合会から来ているリクエストが２０％程度と言われているのですね。","respondent":"小林商業・ものづくり課長","answer":"我々所管課としましては、まず実施にあたって円滑にという部分と。でも効果は上げていくという、関係事業者なり、あるいはその地域の声も聞きながら適切に実施してまいりたいと考えています。","id":"exchange-016"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"１点お聞きしたいのが、これが決まるときというのは、所管課からメニューの候補を出すのですか。所管課のほうからこれとこれでお願いしますと限定してしまうのか、こういう交付金の場合の決まり方というのをお聞きしたいと思います。","respondent":"小林商業・ものづくり課長","answer":"例えば事業者支援として、今現在でいきますとエネルギー価格なり燃料費の高騰に対する支援を行うですとか、幾つか。区としても現時点で、そのことは交付金の今回の事業の趣旨というか使途にも合うということで、ご提案をさせていただいているという状況です。","id":"exchange-017"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"幾つかある中から候補を課として挙げる中でこれに決まったのかというのを伺いたいのと、あと、そういうところで言うと。そういったことに対して、区として国に声を挙げていくということをすべきではないかと思うのですけれども、いかがか尋ねました。","respondent":"小林商業・ものづくり課長","answer":"一般財源で区の独自財源でやる部分もございまして、このタイミングで経済対策を区として実施すべきであろうということも同時に判断としてありまして。","id":"exchange-018"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"この限られた交付金をどう使おうかというところでは分かるのですけれども、この目的である消費喚起というのはなかなか進まないと思いますので、ここを区としても積極的に国に求めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/753456?Template=document&Id=2978#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":23902,"voices":48}},{"id":"r05-20231227-7","meetingId":"r05-cm12","date":"2023年12月27日","dateIso":"2023-12-27","committee":"厚生委員会","time":"午前１０時０７分～午前１０時５９分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を21件整理しています。","topics":[{"id":"topic-01","title":"第１０４号議案、専決処分の承認を求めること","agenda":"第１０４号議案、専決処分の承認を求めること","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"６番の申請方法のところのイということは、今のご説明だと、新たに転入した方がイに当たるということで考えていいのでしょうか。なので、新たに転入されたという方でいいのかということの確認をしたいということが、１点です。","respondent":"豊嶋生活福祉課長","answer":"自動的に７万円を振り込めるはずなので、これは何かと聞かれたときに対応ができるというようなことで、準備を進めているです。最後に、リボン等々のコールセンターですが、こちらは３万円と同様に委託を考えております。","id":"exchange-001"},{"speaker":"鈴木委員","kind":"提案","question":"たしか３万円のときは、これから新たに提案のところで均等割まで拡大されるということは、拡大されるということの提案があると思うのですけれども。今回の７万円のときは、なぜ家計急変世帯を、区独自に対象にするということがされないのかとの意見を述べました。","respondent":"豊嶋生活福祉課長","answer":"実は国は令和６年度の新しい税制で新たに非課税になった世帯に対して、また給付をするというような説明が、つい先日の説明会でございました。よって、今回、家計急変の世帯については、次年度の国の方針を待って対応をしていくということで、今、検討をしています。","id":"exchange-002"},{"speaker":"鈴木委員","kind":"質問","question":"次年度というのは、令和６年度ということですか。インボイスも１０月からされましたし、今回の１０万円というところで、家計急変世帯というものも本当に対象にすべきではないかなと思うのです。","respondent":"豊嶋生活福祉課長","answer":"実は今年度の春先に行った３万円の給付ですが、６月１日の基準日で、家計急変に申し込んだ方が３分の１に減りました。先ほどの話ではありませんが、まずはそちらの給付を迅速に一日も早くできるように進めようということで、準備を進めているです。","id":"exchange-003"},{"speaker":"鈴木委員","kind":"質問・要望","question":"３分の１に減ったとはいえ、３万円のときも区独自にされたわけなので、ぜひそれはやっていただきたい。区としては、対象を本当に困っている人のところに届くような形で、ぜひご検討をいただけたらということで要望をしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"こんの委員","kind":"質問・要望","question":"私たちのところにも、「いつになったら振り込まれるのでしょうか」というようなお問合せは結構いただいております。専決処分をしてですが、この時期に支給といったところをもう少しご説明いただけますか尋ねました。","respondent":"豊嶋生活福祉課長","answer":"１日、１日遅れると、１週間単位でどんどん後ろ倒しになっていく。も１月末にはなってしまいますが、今、何とかこれで準備を進めているです。","id":"exchange-005"},{"speaker":"こんの委員","kind":"確認","question":"もう１点は、確認書の通知をされて、初めて支給をするという形になると思うのです。そこら辺のスケジュール感を説明を求めました。","respondent":"豊嶋生活福祉課長","answer":"通知自体の発送は、現在、どちらの通知も１月２２日を予定しております。口座変更であったりなど、いろいろ諸般の事情で変更したいという方の受け付ける期間を設けて、アの受給承諾書のほうです。","id":"exchange-006"},{"speaker":"こんの委員","kind":"質問","question":"前回３万円をもう既に振り込んで、口座が分かっている人、１月末あるいは２月に入ってからになってしまうというような理解でいいのですか。もう一度、そこを説明を求めました。","respondent":"豊嶋生活福祉課長","answer":"そのとおりです。以前に振り込んだ口座がある方には、実際の着金は２月に入ってからという形になります。","id":"exchange-007"},{"speaker":"こんの委員","kind":"確認","question":"そうですか。再度確認をしますが、受給承諾書の支給を早めるということは、なかなか難しいのか尋ねました。","respondent":"豊嶋生活福祉課長","answer":"実は印刷業者のほうの印刷原稿の校了は、もう既に終わっておりまして、あとはもう我々は出来上がりを待つのみです。１月２２日は実現不可能だったのですけれども、この日以降、何とか発送の手はずを整えたです。","id":"exchange-008"},{"speaker":"こんの委員","kind":"質問・要望","question":"どこも一斉に始めていることなので、あとはこのスケジュールどおり、スムーズに進めるようにお願いしたいと思います。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"}]},{"id":"topic-02","title":"第１０３号議案、令和５年度品川区一般会計補正予算（歳出 厚生委員会所管分）","agenda":"第１０３号議案、令和５年度品川区一般会計補正予算（歳出 厚生委員会所管分）","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"これは、タクシー代が上がったことによるその補填分みたいな形で、１か月５００円、年間６,０００円という考え方でいいのでしょうか。６,０００円の考え方についても伺いたいと思います。","respondent":"松山障害者支援課長","answer":"予算が４,５００人を見込みまして、このときも１人当たり６,０００円ということで、３,２１０万円を計上しています。今回の見込みを出す際に、令和６年の１月１日の発送予定の見込み者として出したものは、４,３００人ということで見込ませていただきました。","id":"exchange-010"},{"speaker":"鈴木委員","kind":"質問・要望","question":"引き上げをという要望は常々いただいていますので、これを機会にぜひ３,５００円から４,０００円に引き上げていただきたいと思うのですけれども。その点についてはいかがでしょうかということも、お伺いさせてほしいと求めました。","respondent":"松山障害者支援課長","answer":"１点目、交付方法です。今回の大きなことですので、今後とも物価上昇や燃料費の状況を見ながら、区としては考えていきたいと考えています。","id":"exchange-011"},{"speaker":"鈴木委員","kind":"質問・要望","question":"さらに、ぜひタクシー券そのものの引上げをしていただきたいということで、これは要望をさせてほしいと求めました。その点についても確認をさせてください。","respondent":"豊嶋生活福祉課長","answer":"対象外という方も一部いらっしゃいますので、差が申請していないということは必ずしもイコールにはならないかなと、こちらは考えております。","id":"exchange-012"},{"speaker":"鈴木委員","kind":"質問","question":"それであれば、気づかずに申請がされなくて、本来であれば、受け取れる方が受け取れていないということは、それほど考えなくていいのか、そこのところについては、どのような状況になっているのかも伺いたいと思います。","respondent":"豊嶋生活福祉課長","answer":"前回の３万円の給付金もそうですが、今回も、ある一定期間がたって申請がない方には、全てに勧奨通知をお送りします。なので、今回もそこでまだ申請されていませんということは、こちらからご通知は申し上げる予定です。","id":"exchange-013"},{"speaker":"鈴木委員","kind":"意見","question":"対象者なのに申請がされていないために、受け取れないということがないというところでは、ぜひこれからもくれぐれもよろしくお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-014"},{"speaker":"ひがし委員","kind":"質問","question":"申請しなかった場合に、その原因が何なのかというところを見ていくことがいいのではないかというような意見が出ていたと思います。その追跡調査をして、送れない、その申請をできなかった理由についての追跡の調査はされているのかを説明を求めました。","respondent":"豊嶋生活福祉課長","answer":"３万円の給付のときには、そのようなことはしておりませんでした。先ほどの在宅介護支援センター、委員おっしゃるような追跡調査をしたかと言われたら、してはおりません。","id":"exchange-015"},{"speaker":"ひがし委員","kind":"質問・要望","question":"こちらは、要望です。もともと利用をしているタクシー券等ではなく、区内商品券にした意味というところを確認させていただきたいのです。","respondent":"松山障害者支援課長","answer":"共通商品券についてのご質問です。印刷が間に合わないということがありますので、年度内にお届けするためにはということで、共通商品券で相当分として対応をするものです。","id":"exchange-016"},{"speaker":"ひがし委員","kind":"質問","question":"区内共通商品券は、タクシーは一部しか利用できないという話もあったりして、タクシー券として使いたかった方にとっては利用しづらかったりするのか。変えたところに対してお声はあるのかと思うのですけれども、実際の利用されている方々の反応がありましたら、説明を求めました。","respondent":"松山障害者支援課長","answer":"共通商品券で「よかった」というお声と、「いや、タクシー券が欲しかった」という両方のお声があります。例えば家計への負担ということも大きいことですから、それぞれの方の日常生活に必要な経費の一部として使用していただくことを考えております。","id":"exchange-017"},{"speaker":"ひがし委員","kind":"質問・要望","question":"前回は追加発行が年度内は困難だからということで、もし今年もやるかもしれないのだったら、そこの調査はするべきであると思います。ぜひ調査というものをして、利用しやすいものというところを発行してほしいと求めましたので、要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"こんの委員","kind":"質問・要望","question":"いわゆるこの７万円を支給される方は、先ほどの話とまた確認が同じなのですが、支給までの流れを確認したいのです。やはりこれも２月下旬から３月上旬で受給承諾書を送って、承諾します」という返事を待たないと、支給できないものなのか尋ねました。","respondent":"豊嶋生活福祉課長","answer":"通知を出してからおおよそ２週間程度、おおむね２週間の待機期間を待った後、振り込むというスキームを取っています。恐らく現在、受給承諾書を送って、すぐに振り込むということをやっている自治体はないと思われます。","id":"exchange-019"},{"speaker":"こんの委員","kind":"質問","question":"一定期間というのは、おおむね２週間を待って、その一定の待機期間を待ってということは、受給承諾書を送った後、返事が返ってくるかどうかのおおむね２週間を待って、あともう少し様子を見て、振り込んでいくという理解でいいか尋ねました。","respondent":"豊嶋生活福祉課長","answer":"発送してから２週間たったら、もうその段階で支給の準備はできていますので、会計管理室を通して、決済を行っていくという流れです。","id":"exchange-020"},{"speaker":"こんの委員","kind":"確認","question":"すみません、再度確認ですが、そうすると、３月中に支給開始となっているものは、受給承諾書の方に限っては、３月を待たずして……。いずれにしても、この２週間を待って、その方たちから何らかのアクションがなくても、振込を開始するという理解でいいということですね。","respondent":"豊嶋生活福祉課長","answer":"原則、申請不要ですので、申請漏れがないというやり方で、３万円のときから始めているものです。","id":"exchange-021"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/651938?Template=document&Id=3680#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":16112,"voices":75}},{"id":"r05-20231227-9","meetingId":"r05-cm12","date":"2023年12月27日","dateIso":"2023-12-27","committee":"文教委員会","time":"午前１０時０７分～午前１０時４７分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を15件整理しています。","topics":[{"id":"topic-01","title":"第１０３号議案 令和５年度品川区一般会計補正予算（歳出 文教委員会所管分）","agenda":"第１０３号議案 令和５年度品川区一般会計補正予算（歳出 文教委員会所管分）","exchanges":[{"speaker":"安藤委員","kind":"確認","question":"この２つの給付金を含む、今回、文教委員会所管分の補正予算３つの事業のうち、区の一般財源でお金を受領というのはあるのでしょうか。それぞれ財源を伺いたいと思います。","respondent":"飛田子育て応援課長","answer":"委員がおっしゃいます地方創生臨時交付金も使うということで、予定では１億１,４００万円ほど、地方創生の臨時交付金から使います。予算は４８０万円上げていますが、そのうち、こちらも地方創生交付金等は４００万円ほどこちらから移すということになっております。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"給付金がありましたけれども、コールセンターが設置されていましたけれども、相談実績はどれぐらいあるのかということも分かればお伺いします。それと、資料の裏面にスケジュールで「要申請者受付開始」とありますけれども、この要申請者とはどういう方なのか伺いたいと思います。","respondent":"飛田子育て応援課長","answer":"そのまま引き続きコールセンターを設置しまして、ほかの国の給付がなければ、５月末までというふうに考えているところです。そしてもう１つの「要申請者」についてですが、口座情報をお聞きするために申請が必要になるということになります。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"３０か所とあるのですけれども、４０か所のうち、全部希望して４０か所、３０か所を超えた場合でも全て支援するということでよろしいのでしょうか。伺います。","respondent":"飛田子育て応援課長","answer":"ひとり親世帯のほうでの周知ですが、一応、住基台帳で対象世帯の方の情報を得まして、対象者へは案内を全員に送る予定です。一応、今のところのフードパントリーの実績では３０か所ですが、もし今回調査して増えた場合は、そこにも分担して支給できればと考えております。","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問・要望","question":"奨学金について伺いたいのですが、大変求められている事業だなというふうに思うのですけれども、伺いますけれども。ぜひ検討に踏み出していただきたいのですけれども、区のお考えはいかがか尋ねました。","respondent":"飛田子育て応援課長","answer":"今、国、各自治体でも様々な支援をしているところですが、今また東京都のほうにも、都立大学の無償化とか、そういうことも言って、大学に対しての奨学制度、大きく今、変化があるところですので、私としては、国また都の状況を見ながら、状況は注視していきたいと考えております。","id":"exchange-004"},{"speaker":"安藤委員","kind":"質問・要望","question":"都立大はごく一部ですし、変化を見ているのではなく、やはり区内からも、区民の大学生から、何度か文教委員会にも請願・陳情など上がっておりました。さらなる支援に踏み出していただきたいと、給付型の大学生への奨学金に踏み出していただきたいなと改めて要望させていただいて終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"二、どのように考えているのか教えていただきたいのと、このシステム作業支援委託というのがどのような事業なのかお知らせほしいと求めました。以上、３つ説明を求めました。","respondent":"飛田子育て応援課長","answer":"ですので、やはりコールセンターの設置は必要かと考えております。そういう意味では、少しでも地域の方がやりやすいようにということで、少しでもバックアップをしていければというふうに考えております。","id":"exchange-006"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"そういう根底の部分のところの問題解決に向けて真剣に考えていただきたいなと思うので、これは要望で終わりますけれども、よろしくお願いします。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"高橋（し）委員","kind":"質問","question":"しっかりお子さんたちの口に届くようなものを買ったかどうかというチェックができるような仕組みになっているのかというところが１つです。逆に言うと、フードパントリーだから、食品以外は使えないという仕組みなのかというところをお尋ねします。","respondent":"飛田子育て応援課長","answer":"今回、実際に商品券の購入費としましては４３２万円を予定しておりまして、そのほかに事務費ということで４８万円上げします。１本だけ色が違って、そういう箸とか、そういうところでも何か買っていただければというふうには考えております。","id":"exchange-008"},{"speaker":"高橋（し）委員","kind":"意見","question":"で、なかなかそこにはつながっていかないので支援が必要ではないかなというふうには思っています。柔軟に対応はできるという表現でよろしいのかなと思いますので、子ども食堂のほうには、そういうふうに伝えてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-009"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"どうなのでしょうか、コロナのことがあって、やむを得ずフードパントリーに移行したというのが本来なのではないのか。それをフードパントリーに特化したような形に見えるのですけれども、その辺についてはいかがなのか尋ねました。","respondent":"飛田子育て応援課長","answer":"それと、フードパントリーについてです。ただ、やはり各子ども食堂のやり方がありますので、そこのところは少し柔軟にというふうには考えております。","id":"exchange-010"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"特にこれによって生活保護の制度上、不利益な扱いにはならないという確認でよろしいですね。その点について、もし何か見解があったら伺いたいと思います。","respondent":"飛田子育て応援課長","answer":"今回は、あくまでもメインはフードパントリーというふうに考えております。ただ、どうしてもやはり運営上、必要なものはあると思いますので、それについては、まず相談していただいて、それで判断することは考えています。","id":"exchange-011"},{"speaker":"安藤委員","kind":"確認","question":"すみません、確認なのですが、１番の、基本的にこれ、国の給付金ではないですか。確認なのですけれども、それが支援にならないと思ったので、そこら辺はどうか尋ねました。","respondent":"飛田子育て応援課長","answer":"基本的に国の制度なので、収入認定はないというふうに言われています。","id":"exchange-012"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"どちらも公明党が１２月５日に区長に緊急要望した内容が早急に反映された内容であり、非常に歓迎したい内容だと感じています。各子ども食堂の要望に応じた寄付となるように、より一層の聞き取りと、声を集約しての支援を要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"安藤委員","kind":"質問・要望","question":"賛成です。さらに一歩踏み込んで実施していただきたいという点はあるものの、今回の内容はどれも大切な事業でありますので、賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"１つだけ。その後、区としてどういうふうに子育てを支援していくかというところは、しっかりと検討していただきたいというふうに思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/106437?Template=document&Id=5118#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":13033,"voices":45}},{"id":"r05-20231227-5","meetingId":"r05-cm12","date":"2023年12月27日","dateIso":"2023-12-27","committee":"総務委員会","time":"午前１１時３０分～午前１１時５９分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を9件整理しています。","topics":[{"id":"topic-01","title":"第１０３号議案、令和５年度品川区一般会計補正予算","agenda":"第１０３号議案、令和５年度品川区一般会計補正予算","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"ならない世帯が生まれてしまうと、品川区の所得制限について、改めてどういう考えで事業を行っているのかを伺いたい。その中で、ひとり親世帯だからこういう対応をしたのかと、改めて所得制限の考え方を伺いたいと思います。","respondent":"遠藤財政課長","answer":"所得制限の考え方ですが、こちらは、今回、国の事業の中で所得の制限を設けて実施されているところです。今回、物価高騰対策の地方創生臨時交付金を活用する中で、どういうものが一番効果的かというところを判断した上で今回の事業をやっているところです。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問","question":"だけれども、ここが苦しいから所得制限をなくすという考え方を今後も続けていくのか、拡大していくのか、改めて伺いたいと思います。教育だったり、対象は全ての子どもたちやお年寄りを対象にすべきだと思いますけれども、最後にいかがか尋ねました。","respondent":"遠藤財政課長","answer":"ですので、委員がおっしゃるところで、具体的に誰だとかというところはあろうかと思います。所得制限はやはり念頭に置いて事業は考えている、うちの考え方といいますか、やり方なのだろうなというふうに思っているところです。","id":"exchange-002"},{"speaker":"松本委員","kind":"質問・要望","question":"総務委員会なので、本当に簡単に伺います。実施が６月、７月頃ということなので、もう一度簡単にご説明ほしいと求めました。","respondent":"遠藤財政課長","answer":"キャッシュレス決済ポイント還元事業ですけれども、こちらはどうしても事業者との調整が必要になりまして、おおむね６か月から７か月ぐらい実施にかかるというところで、４月、当初予算でやると遅くなってしまうため、今回、債務負担行為という形でやらせていただくところです。","id":"exchange-003"},{"speaker":"須貝委員","kind":"質問","question":"それともう１点、フードパントリーというものが今回出ていますけれども、子ども未来応援事業、これはフードバンクとどのような違いがあるのですか。その説明だけ分かる範囲で説明を求めました。","respondent":"遠藤財政課長","answer":"いろいろな社会事情等もあろうかと思いますので、そこら辺につきましては、臨機応変に対応させていただければと考えています。フードバンクのほうは、その基となる食べ物を集めるというような、そういうような形で認識しています。","id":"exchange-004"},{"speaker":"須貝委員","kind":"質問・要望","question":"わざわざこういうふうにつくる必要が、子育て応援ということですから、どうなのかなと少し疑問に思います。どういう業種の方たちのところに共通商品券が使われて、一部の方に使っていただくというような形をとってほしいのと、スーパーでも使える。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"なぜ遅いのですかということをまず聞きたい。少し違うような気がしてならなくて、そこら辺をもう少し丁寧に説明してほしいと思うのだけれども、そこら辺の考え方だけ教えてほしい。","respondent":"遠藤財政課長","answer":"１回、５月のときは別のメニューをやらせていただきましたが、債務負担行為という形でやらせていただいたところです。なかなかすぐにパッとご納得いただける説明は、そこは丁寧に説明しながら、説明を今のところさせていただいたというようなところで考えております。","id":"exchange-006"},{"speaker":"塚本副委員長","kind":"確認","question":"確認ですけれども、これは３月３１日の年度内に使い切らないと、年度内にやり切らなければいけないものなのだという認識でよろしいか尋ねました。","respondent":"遠藤財政課長","answer":"こちら２つの事業については、万が一難しい場合には、一部繰越などもするような形で進めたいと思っています。","id":"exchange-007"},{"speaker":"須貝委員","kind":"質問・要望","question":"残る、私はやはり区民に何とかして買っていただくような仕組みにするよう、区のほうでもしっかり取り組んでほしいと求めました。〔「所管が違う」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"須貝委員","kind":"質問","question":"だから、意見だけ。質問ではなくて、それだけは今指摘しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/246119?Template=document&Id=2286#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":10574,"voices":40}},{"id":"r05-20231227-10","meetingId":"r05-cm12","date":"2023年12月27日","dateIso":"2023-12-27","committee":"議会運営委員会","time":"午後 ２時３０分～午後 ２時３２分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/881920?Template=document&Id=5532#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":1100,"voices":8}}]);
